SELECT 'moj-all-verified-judgments-review-002-chunk-162' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"04f3bc31-bd8c-535f-840c-7b8c4b7aaf80","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -عقد مضاربة -مطالبة بفسخ عقد املضاربة وإعادة رأس املال لعدم تسليم األرباح -حتديد ربح املضاربة بنسبة ثابتة من رأس املال غير جائز -فسخ العقد -عدم قبول الرجوع عن اإلقرار بحق آلدمي -مين اقوى املتداعين.","document_number":"3410654","case_number":"32595757","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة وبتكليف من فضيلته لي بالنظر يف هذه املعاملة احملالة إليه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/13","year":"1434","subject":"شراكة -عقد مضاربة -مطالبة بفسخ عقد املضاربة وإعادة رأس املال لعدم تسليم األرباح -حتديد ربح املضاربة بنسبة ثابتة من رأس املال غير جائز -فسخ العقد -عدم قبول الرجوع عن اإلقرار بحق آلدمي -مين اقوى املتداعين.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/1/13 :‬هـ َر ْق ُم‬\n                         ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3410654 :‬‬\n                              ‫الدعوى‪32595757 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 34246456‬تاريخه‪1434/6/20:‬هـ‬\n\n\n   ‫شــراكة ‪ -‬عقــد مضاربــة ‪ -‬مطالبــة بفســخ عقــد املضاربــة وإعــادة رأس‬\n   ‫املــال لعــدم تســليم األربــاح‪ -‬حتديــد ربــح املضاربــة بنســبة ثابتــة مــن‬\n   ‫رأس املــال غيــر جائــز‪ -‬فســخ العقــد‪ -‬عــدم قبــول الرجــوع عــن اإلقــرار‬\n                                     ‫بحــق آلدمــي ‪ -‬ميــن اقــوى املتداعيــن‪.‬‬\n\n\n\n\n   ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                               ‫علــى مــن أنكــر)‪.‬‬\n   ‫‪ -2‬قــرار مجمــع الفقــه اإلســامي املتضمــن مــا يلــي‪( :‬وقد وقــع اإلجماع‬\n   ‫مــن الفقهــاء علــى مــدى القــرون ويف جميــع املذاهــب بأنــه ال يجــوز‬\n   ‫حتديــد ربــح اإلســتثمار يف املضاربــة وســائر الشــركات مببلــغ مقطــوع‬\n                                             ‫أو نســبة مــن املبلــغ املســتثمر) ‪.‬‬\n   ‫‪ -3‬قــول ابــن قدامــة يف املغنــي (‪( :)96/5‬فأمــا حقــوق اآلدميــن وحقــوق‬\n   ‫اهلل التــي ال تــدرأ بالشــبهات كالــزكاة و الكفــارات فــا يقبــل رجوعــه‬\n                                            ‫عنهــا وال نعلــم يف هــذا خالفـ ًا) ‪.‬‬\n\n\n\n\n                                                                                     ‫‪118‬‬\n\f      ‫ادعــى وكيــل املدعــن بــأن املدعــى عليهــا اســتلمت مــن موكليــه مبالــغ‬\n      ‫ماليــة (محــددة يف دعــواه) للمضاربــة بهــا مقابــل ربــح معــن ومحــدد‬\n      ‫مــن رأس املــال؛ إال أن موكليــه ال يعلمــون أيــن صرفــت هــذه األمــوال‬\n      ‫وهــل متــت املضاربــة بهــا أم ال ولــم تســلمهم املدعــى عليهــا أي أربــاح‪،‬‬\n      ‫لــذا طلــب احلكــم عليهــا بإعــادة املبالــغ التــي اســتلمتها‪ ،‬أقــرت املدعــى‬\n      ‫عليهــا بوجــود تعامــل مالــي بينهــا وبــن املدعــن يفــوق املبلــغ املدعــى بــه‬\n      ‫وثبــوت جــزء مــن املبلــغ يف ذمتهــا ودفعــت بأنهــا ســلمتهم مبالــغ ماليــة‬\n      ‫إال أنهــا ال تعــرف حتديــد ًا مــا الــذي ســلمته لهــم مــن األربــاح ومــا الــذي‬\n      ‫أعادتــه مــن رأس املــال‪ ،‬طلبــت احملكمــة مــن املدعــى عليهــا إثبــات‬\n      ‫مــا دفعــت بــه فعجــزت عــن ذلــك ســوى جــزء مــن املبلــغ وافــق وكيــل‬\n      ‫املدعــن علــى خصمــه مــن املبلــغ املدعــى بــه كمــا أنهــا لــم تقبــل ميــن‬\n      ‫املدعــن علــى نفــي مــا دفعــت بــه‪ ،‬التعامــل اجلــاري بــن موكلــي املدعــي‬\n      ‫واملدعــى عليهــا تعامــل محــرم ألنــه مــن املقــرر شــرع ًا عــدم جــواز حتديــد‬\n      ‫ربــح االســتثمار يف املضاربــة بنســبة مــن رأس املــال‪ ،‬قضــت احملكمــة‬\n      ‫بإلــزام املدعــى عليهــا بإعــادة املبلــغ املدعــى بــه بعــد خصــم املبلــغ الــذي‬\n      ‫أثبتــت تســليمه للمدعــن ووافــق وكيلهــم علــى خصمــه‪ ،‬قنــع املدعــن‬\n      ‫باحلكــم وعارضــت عليــه املدعــى عليهــا‪ ،‬قــررت محكمــة االســتئناف‬\n                                              ‫باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫‪119‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ .....‬املــازم القضائــي لــدى فضيلــة الشــيخ ‪ .....‬مســاعد رئيــس احملكمــة‬\n‫العامــة ببريــدة وبتكليــف مــن فضيلتــه لــي بالنظــر يف هــذه املعاملــة‬\n‫احملالــة إليــه مــن فضيلــة الرئيس برقــم ‪ 32595757‬يف ‪1432/12/23‬هـ‬\n‫واملقيــدة باحملكمــة برقــم ‪ 321584817‬يف ‪1432/12/18‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافــق ‪1433/ 11/ 30‬ه ـ يف متــام احلاديــة عشــرة صباحــا‬\n‫فتحــت اجللســة األولــى لهــذه الدعــوى وفيهــا حضــر ‪ .....‬ســعودي اجلنســية‬\n‫حامــل الســجل املدنــي رقــم الســجل ي ‪ .....‬الوكيــل الشــرعي عــن ‪..... .....‬‬\n‫‪ ..... .....‬أوالد ‪ .....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫ببريدة ‪ 33429641‬يف ‪1433/11/28‬هـ وحضرت حلضوره‪ .....‬ســودانية‬\n‫اجلنســية مبوجــب اإلقامــة الصــادرة مــن بريــدة برقــم ‪ .....‬فقــال املدعــي‬\n‫وكالــة يف تقريــر دعــواه علــى املدعيــة ‪ : ...‬إن هــذه احلاضــرة اســتلمت‬\n‫مــن موكلــي مبالــغ ماليــة قدرهــا خمســمائة وثمانيــة وأربعــون ألــف ريــال‬\n‫علــى دفعــات للمضاربــة بهــا إال أن موكلــي ال يعلمــون أيــن صرفــت هــذه‬\n‫األموال وهل متت املضاربة بها أم ال وإذا ســئلت تغضب وتقول ســر املهنة‬\n‫ولــم تســلمهم املدعــى عليهــا أي أربــاح علمــا بــأن الربــح معــن ومحــدد‬\n‫مــن رأس املــال لــذا أطلــب احلكــم عليهــا بإعــادة املبالــغ التــي اســتلمتها‬\n‫هــذه دعــواي وبينتــي األوراق املكتوبــة بخــط يدهــا ‪ .‬وهــي مرفقــة يف‬\n‫املعاملــة وبســؤال املدعــى عليهــا عــن الدعــوى أجابــت‪ :‬مــا ذكــره املدعــي‬\n‫وكالــة يف دعــواه بعــض صحيــح وبعضــه غيــر صحيــح أمــا الصحيــح‬\n‫فهــو تعاملــي املالــي مــع موكليــه فصحيــح وكذلــك اخلــط املكتــوب يف‬\n\n                                                                                     ‫‪120‬‬\n\f      ‫األوراق املرفقــة وأمــا غيــر الصحيــح فهــو القيمــة املدعــى بهــا فالتعامــل‬\n      ‫املالــي أكثــر مــن املبلــغ املدعــى بــه وأصــل املضاربــة كان مببلــغ قــدره‬\n      ‫مائــة وعشــرة أالف ريــال ثــم تضاعــف بعــد ذلــك واختلطــت األوراق وال‬\n      ‫أعــرف بالضبــط الــذي ســلمته لهــم مــن قيمــة األربــاح ومــا الــذي أعدتــه‬\n      ‫مــن رأس املــال لكــن الــذي أذكــره أنــي ســلمتهم مــا مجموعــه أربعمائــة‬\n      ‫وتســعة وثالثــون ألفــا وخمســمائة ريــال ســعودي بعضهــا ســلمته نقـ ًـدا‬\n      ‫ألخــت املدعــي وكالــة ‪ ...‬وبعضهــا حوالــة بنكيــة ملــوكل املدعــي ‪.....‬‬\n      ‫هــذه إجابتــي وبســؤالها عمــا يف ذمتهــا مــن مبالــغ لــم تعدهــا ملوكلــي‬\n      ‫املدعــي أجابــت قائلــة يف ذمتــي لهــم مبلــغ قــدره مائتــان وســبعة عشــر ألف‬\n      ‫ريــال لــم أســددها أطلــب حتديــد موعــد جللســة قادمــة أحضــر فيهــا بينتــي‬\n      ‫هكــذا أجابــت ونظــرا النتهــاء وقــت اجللســة مت رفــع اجللســة ‪ .‬ويف يــوم‬\n      ‫األربعــاء ‪1433/12/1‬ه ـ فتحــت اجللســة متــام الســاعة التاســعة صباحــا‬\n      ‫وفيهــا حضــر الطرفــان وبســؤال املدعــى عليهــا عــن البينــة التــي وعــدت‬\n      ‫بإحضارهــا أجابــت قائلــة‪ :‬نظــرا لضيــق الوقــت لــم أمتكــن مــن طلبهــا‬\n      ‫مــن البنــك‪ .‬أطلــب حتديــد موعــد قــادم ألمتكــن مــن إحضارهــا‪ .‬وحيــث‬\n      ‫األمــر مــا ذكــر جــرى رفــع اجللســة إلــى يــوم االثنــن ‪1433/12/20‬ه ـ‬\n      ‫صباحــا وعليــه جــرى التوقيــع ‪ .‬ويف يــوم‬   ‫ً‬     ‫الســاعة الثامنــة والنصــف‬\n      ‫االثنــن ‪1433/12/20‬ه ـ فتحــت اجللســة الثالثــة وفيهــا حضــر املدعــي‬\n      ‫وكالــة ‪ .....‬وحضــرت أختــه ‪ .....‬وحضــر حلضورهمــا املدعــى عليهــا ‪.....‬‬\n      ‫و ‪ .....‬الوكيــل الشــرعي عــن املدعــى عليهــا مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة ببريــدة برقــم ‪ 48716‬يف ‪1433/9/19‬ه ـ‬\n      ‫وجــرى منــي ســؤال املدعــي وكالــة عــن بينتــه يف املبالــغ املتبقيــة حيــث‬\n      ‫إن بينتــه تثبــت اســتالم املدعــى عليهــا مبل ًغــا قــدره خمســمائة واثنــان‬\n\n\n‫‪121‬‬\n\f‫وعشــرون ألــف ريــال؟ فأجــاب قائــا‪ :‬هــذا املبلــغ الثابــت بهــذه األوراق‬\n‫وقــدره خمســمائة واثنــان وعشــرون ألــف ريــال هــو مــا أطالــب بــه‪ .‬وجــرى‬\n‫ســؤال املدعــى عليهــا عمــا وعــدت بــه مــن إحضــار البينــة؟ فقدمــت ورقــة‬\n‫مــن مطبوعــات بنــك ‪ ...‬وفيهــا حوالــة مــن ‪ .....‬إلــى حســاب‪ .....‬مببلــغ‬\n‫قــدره عشــرون ألــف ريــال وأحضــرت نســخة مــن احلكــم الصــادر مــن‬\n‫فضيلــة الشــيخ ‪ .....‬جتــاه احلــق العــام الصــادر مــن احملكمــة اجلزائيــة‬\n‫برقــم ‪ 6/107‬يف ‪1433/3/15‬ه ـ ضدهــا وفيــه إقــرار موكلــة املدعــي‬\n‫‪ .....‬باســتالم مبلــغ قــدره ثالثــة أالف ريــال‪ .‬وبســؤال املدعــي وكالــة‬\n‫عــن بينــة املدعــى عليهــا قــال ال مانــع لــدي مــن خصــم املبلــغ الــوارد يف‬\n‫بينتــه وقــدره ثالثــة وعشــرون ألــف ريــال هكــذا أجــاب‪ .‬وبســؤال املدعــى‬\n‫عليهــا هــل حضــر معهــا أحــد وقــت الســداد؟ فأجابــت قائلــة‪ :‬لــم يحضــر‬\n‫معــي أحــد وقــت الســداد‪ .‬وقــد جــرى منــي ســؤال املدعيــة أصالــة ‪:.....‬‬\n‫هــل ســلمت إليــك املدعــى عليهــا أي مبلــغ مــن املبالــغ املدعــى بهــا يف هــذه‬\n‫القضيــة ســوى مــا أحضــرت مــن بينــة؟ فأجابــت‪ :‬لــم تســلم لــي املدعــى‬\n‫عليهــا ‪ .....‬وال أحــد مــن طرفهــا أي مبلــغ‪ .‬فســألت املدعــى عليهــا ‪.....‬‬\n‫هــل تطلبــن ميــن املدعيــة أصالــة ‪ .....‬علــى نفــي اســتالم املبالــغ؟ فأجابــت‬\n‫قائلــة‪ :‬ال أطلــب ميينهــا ‪ .‬فبنــاء علــى مــا ســبق مــن ســماع الدعــوى واإلجابــة‬\n‫واالطــاع علــى أوراق املعاملــة وبينــة املدعــي وكالــة وإلقــرار املدعــى‬\n‫عليهــا بصحــة التعامــل وأن يف ذمتهــا املبلــغ املذكــور وقــدره خمســمائة‬\n‫واثنــان وعشــرون ألــف ريــال منــه مبلــغ قــدره مائتــان وســبعة عشــر ألــف‬\n‫ريــال لــم تســددها ولــم تســتثمرها وأمــا الباقــي وقــدره ثالثمائــة وواحــد‬\n‫وثالثــون ألــف ريــال فقــد ســددتها ولــم حتضــر مــا يثبــت ســدادها للمبلــغ‬\n‫املتبقــي إال مببلــغ قــدره ثالثــة وعشــرون ألــف ريــال وملصادقــة املدعــي‬\n\n\n                                                                                         ‫‪122‬‬\n\f      ‫وكالــة للســداد‪ .‬ولقــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى‬\n      ‫املدعــي واليمــن علــى مــن أنكــر) ولعــدم وجــود البينــة املثبتــة لســداد‬\n      ‫املبلــغ املتبقــي وقــدره ثالثمائــة وثمانيــة أالف ريــال ولرفــض املدعى عليها‬\n      ‫ميــن املدعيــة أصالــة ‪ .....‬علــى نفــي اســتالم املبالــغ املتبقيــة وملــا جــرى مني‬\n      ‫مــن االطــاع علــى احلكــم الصــادر مــن فضيلــة الشــيخ ‪ .....‬جتــاه احلــق‬\n      ‫العــام الصــادر مــن احملكمــة اجلزئيــة برقــم ‪ 6/107‬يف ‪1433/3/15‬ه ـ‬\n      ‫والــوارد فيــه مصادقــة املدعــى عليهــا علــى املبلــغ املذكــور ‪ .....‬وإقــرار‬\n      ‫موكلــة املدعــي ‪ .....‬باســتالم ثالثــة أالف ريــال‪ ،‬لهــذا كلــه وملــا جــاء‬\n      ‫يف قــرار مجلــس املجمــع الفقــه اإلســامي يف دورتــه الرابعــة عشــرة يف‬\n      ‫شــهر ذي القعــدة مــن عــام ‪1432‬ه ـ مــا يلــي‪ »:‬وقــد وقــع اإلجمــاع مــن‬\n      ‫الفقهــاء علــى مــدى القــرون‪ ،‬ويف جميــع املذاهــب‪ :‬بأنــه ال يجــوز حتديــد‬\n      ‫ربــح االســتثمار يف املضاربــة وســائر الشــركات مببلــغ مقطــوع‪ ،‬أو‬\n      ‫بنســبة مــن املبلــغ املســتثمر ‪-‬رأس املــال‪-‬؛ ألن يف ذلــك ضمانــا لألصــل‬\n      ‫وهــو مخالــف لألدلــة الشــرعية الصحيحــة ويــؤدي إلــى قطــع املشــاركة‬\n      ‫يف الربــح واخلســارة التــي هــي مقتضــى الشــركة واملضاربــة‪ ،‬وهــذا‬\n      ‫اإلجمــاع ثابــت مقــرر إذ لــم تنقــل أي مخالفــة لــه‪ ،‬ويف ذلــك يقــول ابــن‬\n      ‫قدامــة يف املغنــي «(‪ )34/3‬أجمــع مــن يحفــظ عنــه مــن أهــل العلــم علــى‬\n      ‫إبطــال القــراض (املضاربــة) إذا شــرط أحدهمــا أو كالهمــا لنفســه‬\n      ‫دراهــم معــدودة‪ ،‬واإلجمــاع دليــل قائــم بنفســه»أ‪.‬هـ وحيــث إن التعامــل‬\n      ‫اجلــاري بــن موكلــي املدعــي واملدعــى عليهــا تعامــل محــرم وهــو مضاربة‬\n      ‫بربــح محــدد مــن رأس املــال لهــذا كلــه فقــد حكمــت علــى املدعــى‬\n      ‫عليهــا ‪ ...‬بإعــادة املبلــغ املتبقــي وقــدره أربعمائــة وتســع وتســعون ألــف‬\n      ‫ريــال ســعودي وبعــرض احلكــم علــى املدعــي وكالــة ‪ .....‬وأختــه ‪.....‬‬\n\n\n‫‪123‬‬\n\f‫قــررا القناعــة والرضــا بــه وأمــا املدعــى عليهــا فقــررت االعتــراض علــى‬\n‫احلكــم وطلبــت رفعــة حملكمــة االســتئناف مبنطقــة القصيــم بالئحــة‬\n‫اعتراضيــة فأجيــب طلبهــا وأفهمــت بتعليمــات االســتئناف ففهمــت ذلــك‬\n‫وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                             ‫وصحبــه أجمعــن‪ .‬حــرر يف ‪1433/12/20‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫يــوم الســبت املوافــق‪1434/ 5/4‬ه ـ الســاعة التاســعة صباحــا فتحــت‬\n‫اجللســة و جــرى فيهــا االطــاع علــى املعاملــة الــواردة مــن محكمــة‬\n‫االســتئناف مبنطقــة القصيــم برقــم‪ 34780381‬وتاريــخ ‪4 / 15‬‬\n‫‪1434/‬ه ـ واملالحــظ عليهــا مــن قبــل أصحــاب الفضيلــة قضــاة الدائــرة‬\n‫احلقوقيــة الثانيــة بالقــرار رقــم ‪ 34185310‬وتاريــخ ‪ 1434/ 4 / 10‬ه ـ‬\n‫علــى الصــك الصــادر منــا برقــم ‪ 3410654‬يف ‪1434/1/13‬ه ـ و نــص‬\n‫احلاجــة منــه بعــد املقدمــة (لوحــظ مــا يلــي‪ :‬أوال‪ :‬لــم يذكــر فضيلتــه‬\n‫مســتنده علــى ثبــوت املبلــغ املدعــى بــه يف ذمــة املدعــى عليهــا ولعــل‬\n‫ذلــك اعترافهــا بــه عنــد محاكمتهــا يف احلــق العــام كمــا هــو موجــود‬\n‫يف القــرار املرفــق باملعاملــة فالبــد مــن تدوينــه وعرضــه علــى املدعــى‬\n‫ثانيــا‪ :‬ادعــت املدعــى عليهــا تســديد بعــض املبلــغ علــى دفعــات‬  ‫عليهــا‪ً .‬‬\n‫كمــا جــاء يف الئحتهــا االعتراضيــة وكمــا جــاء يف صــك احلكــم باحلــق‬\n‫العــام‪ ،‬ولــم ُي ْجـ ِـر فضيلتــه شــيئًا نحــو ذلــك‪ .‬فعلــى فضيلتــه مالحظــة مــا‬\n‫ذكــر‪ ،‬وإجــراء مــا يلــزم نحــوه‪ ،‬ثــم إعــادة املعاملــة إلكمــال الزمهــا‪.‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬قاضــي‬\n‫اســتئناف د‪ ..... .‬ختمــه و توقيعــه قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه‬\n‫رئيــس الدائــرة ‪ .....‬ختمــه وتوقيعــه) وعليــه أجيــب أصحــاب الفضيلــة‬\n\n\n                                                                                        ‫‪124‬‬\n\f      ‫‪-‬وفقهــم اهلل‪ -‬مبــا يلــي‪ :‬بخصــوص املالحظــة األولــى فمســتندي هــو مــا‬\n      ‫بينتــه يف تســبيب احلكــم وهــو مــا ورد يف إقرارهــا أثنــاء نظــر القضيــة‬\n      ‫بصحــة هــذا املبلــغ بقولهــا (وأمــا غيــر الصحيــح فهــو القيمــة املدعــى بهــا‬\n      ‫فالتعامــل املالــي أكثــر مــن املبلــغ املدعــى بــه) فهــي لــم تنفــي ثبــوت املبلــغ‬\n      ‫وأن التعامــل املالــي بينهمــا أكثــر مــن املبلــغ املدعــى بــه‪.‬‬‫إمنــا نفــت قــدره‪ّ ،‬‬\n      ‫وإجابــة لطلــب أصحــاب الفضيلــة فقــد حضــر الطرفــان املدعــي أصالــة‬\n      ‫ووكالــة واملدعــى عليهــا أصالــة ووكيلهــا‪ .....‬ومت ســؤال املدعــى عليهــا‬\n      ‫عــن إقرارهــا املــدون يف القــرار رقــم ‪ 6/107‬يف ‪1433/3/15‬ه ـ ونصــه‬\n      ‫(مــا ذكــره املدعــي العــام يف دعــواه ضــدي فصحيــح ومقــدار املبالــغ‬\n      ‫خمســمائة وثمانيــة وأربعــون ألــف ريــال ســددت منهــا مائتــن وثمانــون‬\n      ‫ألــف ومســتعدة بتســليم أصحــاب احلقــوق اخلاصــة حقوقهــم الباقيــة عنــد‬\n      ‫طلبهــا) فأجابــت قائلــة‪ :‬إن اإلقــرار املوجــود يف القــرار رقــم ‪6/107‬‬\n      ‫الصــادر مــن احملكمــة اجلزئيــة ببريــدة ضــدي غيــر صحيــح ألنــي أقــر‬\n      ‫بالتعامــل املالــي فقــط‪ .‬هكــذا أجابــت‪ .‬وبخصــوص املالحظــة الثانيــة‪:‬‬\n      ‫فقــد ادعــت املدعــى عليهــا ‪ .....‬ســداد بعــض املبالــغ بقولهــا (لكــن‬\n      ‫الــذي أذكــره أنــي ســلمتهم مــا مجموعــه أربعمائــة وتســعة وثالثــون‬\n      ‫ألفــا وخمســمائة ريــال ســعودي بعضهــا ســلمته نقـ ًـدا ألخــت املدعــي‬\n      ‫وكالــة ‪ ...‬وبعضهــا حوالــة بنكيــة ملــوكل املدعــي ‪ .....‬هــذه إجابتــي)‬\n      ‫وجــرى مناقشــتها عــن ذلــك علــى النحــو املبــن يف الصــك وإجابــة‬\n      ‫ألصحــاب الفضيلــة فقــد ســألت املدعــى عليهــا أصالــة عــن بينتهــا علــى‬\n      ‫ـاهدا علــى‬\n                ‫مــا ذكرتــه يف الالئحــة االعتراضيــة فقالــت‪ :‬أحضــرت شـ ً‬\n      ‫تســليم أخــت املدعــي وكالــة ‪ .....‬وهــو ب‪ .....‬ســوادني اجلنســية مبوجــب‬\n      ‫اإلقامــة الصــادرة مــن جــوازات بريــدة برقــم ‪ .....‬وبســؤاله عمــا لديــه مــن‬\n\n\n‫‪125‬‬\n\f‫شــهادة قــال أشــهد هلل تعالــى علــى ثــاث وقائــع األولــى‪ :‬أنــي ذهبــت‬\n‫باملدعــى عليهــا ‪ ...‬إلــى حــي الشــقة وكان مــع املدعــى عليهــا ‪ .....‬مبلــغ‬\n‫بعدهــا ثــم تســليمها للمدعــى عليهــا‬  ‫قــدره ســبعة وســتون ألــف ريــال قمــت ّ‬\n‫فنزلــت مــن ســيارتي ثــم ذهبــت إلــى ســيارة متوقفــة عنــد صــراف بنــك‬\n‫الريــاض فيهــا رجــل وامــرأة فنــزل منهــا الســائق وركبــت املدعــى عليهــا‬\n‫‪ .....‬ثــم نزلــت منهــا وعــادت إلــى ســيارتي فســألتها عــن تســليم املبلــغ‬\n‫فقالــت نعــم ســلمته‪ .‬هكــذا شــهد وبســؤاله هــل تعــرف نــوع الســيارة‬\n‫أو مــن فيهــا؟ أجــاب قائــا‪ :‬ال أذكــر نــوع الســيارة وال أعــرف مــن فيهــا‪.‬‬\n‫هكــذا أجــاب‪ .‬والواقعــة الثانيــة التــي أشــهد هلل تعالــى فيهــا أنــه يف يــوم‬\n‫ال أذكــر تاريخــه ســلمتني املدعــى عليهــا ‪ ..... .....‬ظرفــا مغلفــا وقالــت‬\n‫لــي هــذا الظــرف فيــه مبالــغ ماليــة ســلمها إلــى رجــل جالــس يف محــل ‪.....‬‬\n‫الواقــع قــرب إشــارة ‪ ...‬يف شــارع ‪ ...‬وال أعــرف قيمــة املبالــغ املاليــة وال‬\n‫موضوعهــا‪ .‬والواقعــة الثالثــة التــي أشــهد هلل تعالــى فيهــا أنــي ذهبــت مــع‬\n‫‪ .....‬الســاعة ‪ 12‬ليــا إلــى منــزل ‪ .....‬وكان معهــا مبلغــا ال أعــرف قــدره‬\n‫لتســليمه لهــم ثــم عنــد وصولنــا وقفــت مــع أبــي ‪ .....‬ودخلــت ‪ .....‬بيتــه ثــم‬\n‫خرجــت ولــم أر يف يدهــا أي مبلــغ‪ .‬هكــذا شــهد وبســؤال املدعــى عليهــا‬\n‫أصالــة هــل لديــك بينــة أخــرى أجابــت قائلــة‪ :‬إن املســتندات املرفقــة يف‬\n‫املعاملــة تثبــت اســتالم األربــاح‪ .‬وعنــدي شــاهد آخــر لــم يحضــر هــو الــذي‬\n‫ســلم ‪ .....‬مبالــغ ماليــة عبــارة عــن قيمــة ســيارة‪ .‬هكــذا أجابــت‪ .‬فســألت‬\n‫املدعــى عليهــا هــل مت تســليم مبالــغ ماليــة ألحــد غيــر ‪ ...‬يـ ًـدا بيــد؟ أجابــت‬\n‫قائلــة‪ :‬نعــم ســلمت أخــت املدعــي وكالــة ‪ ...... .....‬وليــس لــدي بينــة علــى‬\n‫تســليمهم وأطلــب ميينهــم‪ .‬وبطلــب اليمــن مــن ‪ .....‬حاملــة الســجل رقــم‬\n‫‪ .....‬واملعــرف بهــا مــن قبــل أخويهــا ‪ .....‬ســعودي بالســجل املدنــي رقــم ‪.....‬‬\n\n\n                                                                                           ‫‪126‬‬\n\f      ‫و‪ .....‬ســعودي بالســجل املدنــي رقــم ‪ .....‬واملدعــى عليهــا اســتعدت قائلــة‬\n      ‫واهلل الــذي ال إلــه إال هــو أنــي لــم اســتلم مــن هــذه احلاضــرة ‪ .....‬أي مبلــغ‬\n      ‫مالــي‪ .‬هكــذا حلفــت‪ .‬وبالســؤال عــن ‪ .....‬أفــاد املدعــي وكالــة بأنهــا‬\n      ‫ليســت مــن املدعــن ولــم نطالــب بنصيبهــا‪ .‬ثــم ســألتها هــل تطلبــن ميــن‬\n      ‫‪ ...‬فأجابــت قالــت ال أطلــب ميينهــا‪ .‬فبنــاء علــى مــا ســبق وألن اإلقــرار‬\n      ‫الصــادر مــن املدعــى عليهــا مــدون يف صــك مصــدق مــن اســتئناف منطقــة‬\n      ‫القصيــم والرجــوع عنــه ال يقبــل ألنــه إقــرار يف حــق اآلدميــن‪ .‬قــال ابــن‬\n      ‫قدامــة ‪-‬رحمــه اهلل‪ -‬يف املغنــي (‪« :)96/5‬فأمــا حقــوق اآلدميــن‪،‬‬\n      ‫وحقــوق اهلل التــي ال تــدرأ بالشــبهات‪-‬كالزكاة والكفــارات‪ -‬فــا‬\n      ‫يقبــل رجوعــه عنهــا وال نعلــم يف هــذا خالفــا»‪ .‬وأمــا الشــهادة فهــي غيــر‬\n      ‫موصلــة جلهــل الشــاهد بقــدر املبالــغ فضــا عــن كــون التســليم ملبلــغ لــم‬\n      ‫يــدع بــه‪ ،‬وأمــا الشــاهد الغائــب فشــهادته كمــا أفــادت املدعــى عليهــا‬\n      ‫ـاء علــى ذلــك فــا زلــت علــى مــا حكمــت بــه‬     ‫علــى أمــر لــم يــدع بــه‪ .‬فبنـ ً‬\n      ‫وبعــرض احلكــم علــى املدعــى عليهــا أجابــت أنهــا باقيــة علــى اعتراضهــا‬\n      ‫وأمــا املدعــي وكالــة فقــرر قناعتــه واهلل أعلــم وقــررت إعــادة املعاملــة‬\n      ‫ألصحــاب الفضيلــة قضــاة االســتئناف التخــاذ مــا يرونــه وصلــى اهلل علــى‬\n                                              ‫نبينــا محمــد حــرر يف ‪1434/ 5 / 4‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n      ‫ـاء‬\n      ‫هــذا اليــوم الســبت املوافــق ‪1434/8/6‬ه ـ فتحــت هــذه اجللســة بنـ ً‬\n      ‫علــى ورود املعاملــة املتعلقــة بدعــوى ‪ .....‬بالوكالــة عــن ‪..... ..... ..... .....‬‬\n      ‫‪ .....‬أوالد ‪ .....‬ضــد ‪ ..... .....‬ســودانية اجلنســية مــن محكمــة االســتئناف‬\n      ‫بالقصيــم مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم ‪34/1239478‬‬\n      ‫يف ‪1434/7/8‬ه ـ املرفــق بــه القــرار الصــادر مــن أصحــاب الفضيلــة‬\n\n\n‫‪127‬‬\n\f‫قضــاة الدائــرة الثانيــة لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n‫بالقصيــم رقــم ‪ 34246456‬يف ‪1434/6/20‬ه ـ املتضمــن املصادقــة علــى‬\n‫هــذا احلكــم وللبيــان جــرى تدوينــه وعليــه حصــل التوقيــع وصلــى اهلل‬\n       ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/8/6‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                ‫‪128‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":118,"source_page_end":128,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ccc35a32d4a17b36cc6d822a4ec30ec3e10ed6ba471bb4de3e993f0ecc050b4c","normalized_text_hash":"b5661ef2fc13f084a8bf462ae67f8f739119bb5f34a8d439f7dbcb8e67436c21","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p118-3410654"},{"id":"e2fad480-9af7-5696-bcc0-3484397cdef4","document_type":"judgment","category":"judicial","subcategory":"general","title":"شركة مضاربة -املطالبة باألرباح يف شركة مضاربة -دعوى خسارة شركة مضاربة -عدم ثبوت الربح يف شركة املضاربة - صرف النظر عن املطالبة بأرباح شركة املضاربة لعدم ثبوتها - املضارب مؤمتن واألمن يقبل قوله بيمنه- ( اتفاق أهل العلم أن املضارب مؤمتن ال ضمان عليه فيما يتلفه من املال من غير جناية فيه وال استهالك له وال تصحيح هذه سبيل األمانة وهذا سبيل االمناء) االستذكار البن عبد البر - 124/121","document_number":"34298408","case_number":"33185453","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/16","year":"1434","subject":"شركة مضاربة -املطالبة باألرباح يف شركة مضاربة -دعوى خسارة شركة مضاربة -عدم ثبوت الربح يف شركة املضاربة - صرف النظر عن املطالبة بأرباح شركة املضاربة لعدم ثبوتها - املضارب مؤمتن واألمن يقبل قوله بيمنه- ( اتفاق أهل العلم أن املضارب مؤمتن ال ضمان عليه فيما يتلفه من املال من غير جناية فيه وال استهالك له وال تصحيح هذه سبيل األمانة وهذا سبيل االمناء) االستذكار البن عبد البر - 124/121","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/16 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34298408 :‬‬\n                         ‫َر ْق ُم الدعوى‪33185453 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34343374‬تاريخه‪1434/10/28:‬هـ‬\n\n\n      ‫شــركة مضاربــة ‪ -‬املطالبــة باألربــاح يف شــركة مضاربــة ‪ -‬دعــوى‬\n      ‫خســارة شــركة مضاربــة ‪ -‬عــدم ثبــوت الربــح يف شــركة املضاربــة ‪-‬‬\n      ‫صــرف النظــر عــن املطالبــة بأربــاح شــركة املضاربــة لعــدم ثبوتهــا ‪-‬‬\n                               ‫املضــارب مؤمتــن واألمــن يقبــل قولــه بيمنــه‪-‬‬\n\n\n\n\n      ‫( اتفــاق أهــل العلــم أن املضــارب مؤمتــن ال ضمــان عليــه فيمــا يتلفــه مــن‬\n      ‫املــال مــن غيــر جنايــة فيــه وال اســتهالك لــه وال تصحيــح هــذه ســبيل‬\n      ‫األمانــة وهــذا ســبيل االمنــاء) االســتذكار البــن عبــد البــر ‪- 124/121‬‬\n         ‫بدايــة املجتهــد البــن رشــد ‪ - 178/2‬كشــاف القنــاع للبهوتــي ‪524/8‬‬\n\n\n\n\n      ‫دعــوى املدعــي وكالــة ضــد املدعــى عليــه ان موكلــه ســلم للمدعــى‬\n      ‫عليــه مبلغــا مــن املــال لغــرض املتاجــرة بــه وتقســيطه علــى النــاس واتفــق‬\n      ‫معــه علــى ان يكــون الربــح محــددا شــهريا وأن املدعــى عليــه لــم يلتــزم‬\n      ‫بتســليم موكلــه أي شــيء ممــا مت االتفــاق عليــه وطلــب الــزام املدعــى‬\n      ‫عليــه بتســليم االربــاح املتفــق عليهــا‪ ،‬اجــاب املدعــى عليــه باملصادقــة على‬\n      ‫الدعــوى وقــرر انــه اســتلم مــن املدعــي اصالــة واخوتــه مبلغــا مــن املــال وملــا‬\n      ‫علــم بفســاد هــذا العقــد فقــد اثبــت لهــم يف ذمتــه هــذا املبلغ الذى اســتلمه‬\n\n‫‪129‬‬\n\f‫مبوجــب صكــوك شــرعية‪ ،‬صــادق املدعــي وكالــة علــى اجابــة املدعــى‬\n‫عليــه وطالــب باألربــاح‪ ،‬اجــاب املدعــى عليــه بــأن الشــركة خســرت وال‬\n‫اربــاح فيهــا‪ ،‬قــرر املدعــي وكالــة أن الشــركة ربحــت حســب اخبــار‬\n‫املدعــى عليــه ملوكلــه ‪ -‬احضــر املدعــي وكالــة بينــة غيــر موصلــة تثبــت‬\n‫ربــح الشــركة افهــم ناظــر القضيــة املدعــي وكالــة بــأن لــه ميــن املدعــى‬\n‫عليــه علــى خســارة الشــركة فطلبهــا ‪،‬حلــف املدعــى عليــه علــى خســارة‬\n‫الشــركة‪ ،‬صــدر احلكــم بصــرف النظــر عــن مطالبــة املدعــى وكالــة‬\n‫باألربــاح‪ ،‬قــرر املدعــى وكالــة عــدم القناعــة‪ ،‬صــدق احلكــم مــن‬\n                                                         ‫محكمــة االســتئناف‬\n\n\n\n\n‫احلمد هلل وحده والصالة والســام على من ال نبي بعده وبعد‪ :‬ففي هذا‬\n‫اليــوم االثنــن املوافــق ‪1433/6/9‬ه ـ ويف متــام الســاعة الثامنــة والنصــف‬\n‫لــدي أنــا القاضــي‪ ...‬يف احملكمــة العامــة بالطائــف بنــاء علــى املعاملــة‬\n‫احملالــة مــن فضيلــة الرئيــس برقــم ‪ 33185453‬وتاريــخ ‪1433/3/14‬ه ـ‬\n‫واملقيــدة يف هــذه احملكمــة برقــم ‪ 33489250‬وتاريخ‪1433/3/14‬ه ـ‬\n‫افتتحــت اجللســة احملــددة لســماع دعــوى ‪ ...‬مينــي اجلنســية باإلقامــة رقــم‬\n‫‪ ...‬ضــد ‪ ...‬والتــي يطالبــه فيهــا مببلــغ وقــدره ســتة وســبعون ألــف وســتمائة‬\n‫ا‬‫ريــال ســعودي وهــي قــرض حســن وحيــث لــم يحضــر املدعــي وال وكيـ ً‬\n‫عنــه ولــم يقــدم عــذر ًا تقبلــه احملكمــة لــذا جــرى شــطب هــذه الدعــوى‬\n‫للمــرة األولــى بنــاء علــى املــادة الثالثــة واخلمســن مــن نظــام املرافعــات‬\n‫الشــرعية ولوائحــه التنفيذيــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                          ‫نبينــا محمــد حــرر يف ‪1433/6/9‬ه ـ‬\n\n                                                                                      ‫‪130‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n      ‫هــذا اليــوم االثنــن املوافــق ‪1433/10/23‬ه ـ ويف متــام الســاعة الثانيــة‬\n      ‫عشــرة ظهــر ًا لــدي أنــا‪ ...‬القاضــي يف احملكمــة العامــة بالطائــف بنــاء‬\n      ‫علــى املعاملــة احملالــة مــن فضيلــة الرئيــس برقــم ‪ 33185453‬وتاريــخ‬\n      ‫‪1433/3/14‬ه ـ واملقيــدة يف هــذه احملكمــة برقــم ‪ 33489250‬وتاريــخ‬\n      ‫‪1433/3/14‬ه ـ افتتحــت اجللســة وفيهــا حضــر‪ ...‬مينــي اجلنســية باإلقامــة‬\n      ‫رقــم ‪ .....‬ولــم يحضــر املدعــى عليــه وال وكيــل عنــه وباالطــاع علــى‬\n      ‫املعاملــة تبــن أن إفــادة محضــري اخلصــوم لــم تــرد رغــم مخاطبتهــم‬\n      ‫بخطابنــا رقــم ‪ 331272102‬وتاريــخ ‪1433/7/7‬ه ـ لتبليــغ املدعــى عليــه‬\n      ‫وحيــث اقتضــى النظــر إعــادة االستفســار عــن خطابنــا املشــار إليــه لــذا‬\n      ‫رفعــت اجللســة يف متــام الســاعة الثانيــة عشــر والربــع ظهــر ًا وحــددت‬\n      ‫موعــد ًا لنظــر هــذه القضيــة يف يــوم االثنــن املوافــق ‪1434/2/4‬ه ـ يف‬\n      ‫متــام الســاعة الثامنــة صباحـ ًا وأفهمــت املدعــي مبراجعــة قســم محضــري‬\n      ‫اخلصــوم يف هــذه احملكمــة لتزويدهــم مبــا يلــزم كــي يتمكنــوا مــن‬\n      ‫تبليــغ املدعــى عليــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                          ‫حــرر يف ‪1433/10/23‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n      ‫هــذا اليــوم االثنــن املوافــق ‪1434/2/4‬ه ـ ويف متــام الســاعة الثامنــة‬\n      ‫صباح ـ ًا افتتحــت اجللســة وفيهــا حضــر ‪ ...‬مينــي اجلنســية باإلقامــة‬\n      ‫رقــم‪ .....‬ولــم يحضــر املدعــى عليــه رغــم تبلغــه لشــخصه حســب إفــادة‬\n      ‫محضــري اخلصــوم رقــم ‪ 331880023‬يف ‪1433/10/24‬ه ـ وبســؤال‬\n      ‫املدعــي عــن إثبــات هويتــه أبــرز صــورة مــن إقامتــه وذكــر أن األصــل‬\n      ‫لــدى اجلــوازات بغــرض التجديــد هكــذا أفــاد ولعــدم االكتفــاء بذلــك‬\n\n\n‫‪131‬‬\n\f‫قــررت رفــع اجللســة يف متــام الســاعة الثامنــة والنصــف صباح ـ ًا وأفهمــت‬\n‫املدعــي بإحضــار أصــل إثباتاتــه الرســمية وبينتــه علــى دعــواه يف اجللســة‬\n‫القادمــة ففهــم ذلــك واســتعد بــه وعليــه حــددت للطرفــن موعــد ًا يف يــوم‬\n‫الثالثــاء املوافــق ‪1434/4/23‬ه ـ يف متــام الســاعة التاســعة والنصــف‬\n‫صباح ـ ًا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                 ‫‪1434/2/4‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n‫هــذا اليــوم الثالثــاء املوافــق ‪1434/4/23‬ه ـ ويف متــام الســاعة التاســعة‬\n‫والنصــف صباحـ ًا لــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة بالطائــف‬\n‫والقائــم بعمــل املكتــب القضائــي الســابع افتتحــت اجللســة وفيهــا حضــر‬\n‫‪ ...‬مينــي اجلنســية باإلقامــة رقــم‪ .....‬ولــم يحضــر املدعــى عليــه وال وكيــل‬\n‫عنــه ولــم يقــدم عــذر ًا تقبلــه احملكمــة رغــم تبلغــه لشــخصه حســب‬\n‫خطــاب محضــري اخلصــوم رقــم ‪ 331880023‬يف ‪1434/10/24‬ه ـ‬\n‫واخلطــاب رقــم ‪ 33587837‬يف ‪1433/3/28‬ه ـ وتبلــغ ابنه حســب خطاب‬\n‫محضــري اخلصــوم برقــم ‪ 34288166‬يف ‪1434/2/4‬ه ـ لــذا قــررت‬\n‫الســير يف نظــر هــذه القضيــة بنــاء علــى املــادة ‪ 1/55‬مــن نظــام املرافعــات‬\n‫الشــرعية ولوائحــه التنفيذيــة وبســؤال املدعــي عــن دعــواه ادعــى قائـاً‪:‬‬\n‫ادعــي علــى املدعــى عليــه بــأن لــي يف ذمتــه ســتة وســبعني ألفـ ًا وســتمائة‬\n‫ريــال لــم يدفــع لــي منهــا شــيء مقابــل قــرض حســن وذلــك مبوجــب ورقــة‬\n‫وصــل أمانــة و بينتــي هــم الشــهود املذكوريــن يف وصــل األمانــة هــذه‬\n‫دعــواي وبطلــب البينــة منــه قــال ســوف أحضرهــم يف اجللســة القادمــة‬\n‫وعليــه قــررت رفــع اجللســة يف متــام الســاعة العاشــرة وحــددت للطرفــن‬\n‫موعــدا يف يــوم األربعــاء املوافــق ‪1434/6/14‬ه ـ يف متام الســاعة العاشــرة‬\n\n\n                                                                                     ‫‪132‬‬\n\f      ‫صباح ـ ًا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                          ‫‪1434/4/23‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة العامــة بالطائــف‬\n      ‫والقائــم بعمــل املكتــب القضائــي الســابع ففــي هــذا اليــوم االربعــاء‬\n      ‫املوافق ‪1434/6/14‬هـ ويف متام الســاعة العاشــرة صباح ًا فتحت اجللســة‬\n      ‫وفيهــا حضــر املدعــي املنــوه عــن صفتــه وهويتــه يف اجللســات املاضيــة‬\n      ‫وحضــر حلضــوره املدعــى عليــه ‪ ...‬نيجيــري اجلنســية مبوجــب رخصــة‬\n      ‫اإلقامــة رقــم الصــادره مــن الطائــف وبســؤال املدعــي وكالــة عــن حتريــر‬\n      ‫ا ســبق ان اقتــرض املدعــى عليــه مــن موكلــي مبلغ ـ ًا‬       ‫دعــواه اجــاب قائ ـ ً‬\n      ‫مــن املــال وقــدره ســتة وســبعون ألفـ ًا وســتمائة ريــال يف ‪1432/11/30‬ه ـ‬\n      ‫وهــي قــرض حســن يســدد املبلــغ متــى مــا طلــب منــه مــن قبــل موكلــي‬\n      ‫وحتــى اآلن لــم يســدد أي شــيء أطلــب ســؤاله واحلكــم عليــه بســداد‬\n      ‫املبلــغ حــا ًال ملوكلــي وبســؤال املدعــى عليــه عــن دعــوى املدعــي وكالــة‬\n      ‫ا مــا ذكــره املدعــي وكالــة يف دعــواه غيــر صحيــح جملــة‬            ‫أجــاب قائ ـ ً‬\n      ‫ا فأنــا لــم أقتــرض مــن املدعــى عليــه بــل وال أعرفــه وهــذا‬            ‫وتفصي ـ ً‬\n      ‫املبلــغ الــذي يدعــى بــه هــو بســبب شــراكه بيننــا حيــث أحضــر املبلــغ‬\n      ‫لــي بقصــد املتأجــرة باملبلــغ الــذي أحضــروه وقــدرة مائــة وخمســون ألــف‬\n      ‫ريــال وقــد خســرت هــذه الشــركة وقــد اثبــت حقهــم بصــك شــرعي مــن‬\n      ‫املكتــب القضائــي العاشــر واملكتــب القضائــي الســابع عشــر وقــد‬\n      ‫حكــم علــي مببلــغ وقــدره مائــة وخمســون ألــف ريــال واملبلــغ الــذي دفعــه‬\n      ‫ومــن معــه عــن طريــق املذكــور أعــاه وهــذا املبلــغ الــذي يدعــي بــه هــو‬\n      ‫األربــاح التــي حســبوها وحقيقــة األمــر أن الشــركة قــد خســرت فليــس‬\n      ‫يف ذمتــي للمدعــي مــن هــذا املبلــغ املدعــي بــه شــيئ ًا هــذه أجابتــي ولضيــق‬\n\n\n‫‪133‬‬\n\f‫الوقــت رفعــت اجللســة إلــى يــوم االثنــن املوافــق ‪1434/8/15‬ه ـ الســاعة‬\n‫التاســعة والنصــف صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/14‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n‫هــذا اليــوم االثنــن املوافــق ‪1434/8/15‬ه ـ ويف متــام الســاعة التاســعة‬\n‫والنصــف صباح ـ ًا لــدي أنــا القاضــي يف احملكمــة العامــة بالطائــف‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة مينــي جلنســية باإلقامــة‬\n‫رقــم بالوكالــة عــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بالطائــف رقــم ‪ 34504686‬وتاريــخ ‪1434/4/23‬ه ـ وحضــر‬\n‫حلضــوره املدعــي عليــه نيجيــري اجلنســية مبوجــب اإلقامــة رقــم وبتــاوة‬\n‫مــا مت ضبطــه ســابق ًا صــادق عليــه الطرفــان وبســؤال املدعــي عــن دعــواه‬\n‫ا أننــي ادعــي علــى هــذا احلاضــر معــي حيــث أنــه بتاريــخ‬    ‫أجــاب قائ ـ ً‬\n‫‪1432/11/30‬ه ـ دفــع موكلــي للحاضــر معــي مبلــغ وقــدره خمســون‬\n‫ألــف ريــال لغــرض املتاجــرة بهــا وتقســيطها علــى النــاس واتفقــت معــه‬\n‫علــى أن يكــون الربــح مبلغ ـ ًا قــدره ســتة وعشــرون ألــف وســتمائة‬\n‫ريــال منجم ـ ًا علــى أشــهر بواقــع كل شــهر مبلغ ـ ًا وقــدره ســبعة آالف‬\n‫وخمســمائة ريــال إال إن هــذا املدعــى عليــه لــم يقــم بســداد أي شــيء‬\n‫منهــا أطلــب إلزامــه بســداد هــذا املبلــغ ملوكلــي حــا ًال وإنــي أســأله‬\n‫ا مــا ذكــره‬  ‫اجلــواب هــذه دعــواي وبســؤال املدعــى عليــه أجــاب قائ ـ ً‬\n‫ا إال إنــي قــد اســتلمت‬  ‫املدعــي وكالــة فكلــه صحيــح جملــة وتفصي ـ ً‬\n‫مــن املدعــي وكالــة وأخوتــه مبلــغ إجمالــي قــدره مائــة وخمســون ألــف‬\n‫ريــال وملــا علمــت بفســاد هــذا العقــد أثبــت لهــم يف ذمتــي املائــة واخلمســن‬\n‫ألــف ريــال مبوجــب صكــوك شــرعية هــذه إجابتي وعليهــا أوقع وبعرض‬\n\n\n                                                                                       ‫‪134‬‬\n\f      ‫ذلــك علــى املدعــي وكالــة قــرر بقولــه ماذكــره فصحيــح وموكلــي‬\n      ‫وزوجتــي ســبق أن صــدرت صكــوك بهــذه املبالــغ لــدي احملكمــة وعليــه‬\n      ‫إنــي أطالبــه بأربــاح هــذه الشــركة وقدرهــا ســتة وعشــرون ألــف ريــال‬\n      ‫يدفعهــا ملوكلــي حــا ًال هــذه دعــواي وبســؤال املدعــي عليــه عــن أربــاح‬\n      ‫هــذه الشــركة قــال إن هــذه الشــركة قــد خســرت وال أربــاح فيهــا‬\n      ‫وأنــا غيــر مســتعد بدفــع أي شــيء للمدعــي هكــذا قــرر وبعرضــه علــى‬\n      ‫ا إن هــذه الشــركة فيهــا أربــاح بحســب مــا‬    ‫املدعــي وكالــة أجــاب قائـ ً‬\n      ‫أخبرنــا بــه املدعــي عليــه هكــذا قــرر وعليــه طلبــت مــن املدعــي وكالــة‬\n      ‫البينــة علــى وجــود أربــاح فأبــرز لنــا ورقــة محــررة تتضمــن جــدول ســداد‬\n      ‫وأقســاط الســيارات لألســتاذ مبلــغ الشــراء للســيارات خمســون ألــف‬\n      ‫ريــال فقــط ال غيــر تســدد بالتقســيط مبلــغ قــدره ســبعة آالف ريــال علــى‬\n      ‫النحــو التالــي يف ‪1432/11/30‬ه ـ مبلــغ ســبعة آالف ريــال ويف تاريــخ‬\n      ‫‪1432/12/30‬ه ـ مبلــغ ســبعة آالف ريــال ويف تاريــخ ‪1433/1/30‬ه ـ‬\n      ‫مبلــغ ســبعة آالف ريــال يف تاريــخ ‪1433/2/30‬ه ـ مبلــغ ســبعة آالف‬\n      ‫ريــال يف تاريــخ ‪1433/2/30‬ه ـ مبلــغ ســبعة آالف ريــال يف تاريــخ‬\n      ‫‪1433/3/30‬ه ـ مبلــغ ســبعة آالف ريــال يف تاريــخ ‪1433/4/30‬ه ـ مبلــغ‬\n      ‫ســبعة آالف ريــال يف تاريــخ ‪1433/5/30‬ه ـ مبلــغ ســبعة آالف ريــال يف‬\n      ‫تاريــخ ‪1433/6/30‬ه ـ مبلــغ ســبعة آالف ريــال يف تاريــخ ‪1433/7/30‬ه ـ‬\n      ‫مبلــغ ســبعة آالف ريــال يف تاريــخ ‪1433/8/30‬ه ـ وبســؤاله هــل لديــك‬\n      ‫ا ليــس لــدي مزيــد بينــة هكــذا قــرر وعليــه‬      ‫مزيــد بينــة؟ اجــاب قائ ـ ً‬\n      ‫أفهمتــه إن لــه ميــن املدعــي عليــه فطلبهــا وبعرضــه علــى املدعــي عليــه‬\n      ‫ا واهلل العظيــم الــذي ال الــه‬\n                                     ‫قــال ال مانــع لــدي واســتعد بهــا وحلــف قائ ـ ً‬\n      ‫إال هــو الــذي يعلــم الســر والعالنيــة ويعلــم اجلهــر ومــا يخفــى إن الشــركة‬\n\n\n‫‪135‬‬\n\f‫املوصوفــة يف دعــوى املدعــي قــد خســرت ولــم آخــذ منهــا أي أربــاح وحتــى‬\n‫ـاء‬\n‫بعــض رأس املــال قــد خســرته واهلل واهلل واهلل هكــذا حلــف فبنـ ً‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه حلــف‬\n‫اليمــن التــي طلبــت منــه ومبــا أن حكــم القــراض الفاســد كصحيحــة‬\n‫مــن حيــث الضمــان وعدمــه ومبــا أن املدعــي وكالــة أقــر باحلكــم لــه‬\n‫بــرأس املــال وانحصــرت دعــواه يف املطالبــة باألربــاح والتفــاق أهــل العلــم‬\n‫أن املضــارب مؤمتــن ال ضمــان عليــه يف مــا يتلفــه مــن املــال مــن غيــر جنايــة‬\n‫فيــه وال اســتهالك لــه وال تصحيــح هــذه ســبيل األمانــة وهــذا ســبيل‬\n‫األمنــاء حــكاه بــن عبدالبــر يف االســتذكار ‪ 124/121‬وابــن رشــد يف‬\n‫بدايــة املجتهــد ‪ 178/2‬والبهوتــي يف كشــاف القنــاع ‪ 524/8‬ولعجــز‬\n‫املدعــي وكالــة عــن إثبــات مــا ادعــي بــه مــن ربــح الشــركة لذلــك كلــه‬\n‫فقــد صرفــت النظــر عــن دعــوي املدعــي هــذا مــا ظهــر لــي وبــه حكمــت‬\n‫واهلل تعالــي أعلــم وبعــرض ذلــك علــى املدعــي وكالــة قــرر اعتراضــه‬\n‫علــى احلكــم وطلــب اســتئناف احلكــم بــدون الئحــة وعليــه قــررت بعــث‬\n‫كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪ 1434/8/15‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بالطائف‬\n‫فقــد أعيــدت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫بخطــاب فضيلــة رئيســها برقــم ‪ 33489250‬يف ‪1434/11/3‬ه ـ واملرفــق‬\n‫معهــا قــرار الدائــرة احلقوقيــة األولــى بالقــرار الصــادر برقــم ‪34343374‬‬\n‫يف ‪1434/10/28‬ه ـ املــدون علــى ظهــر الصــك واملتضمــن مــا نصــه‬\n‫بعــد املقدمــة ( وبدراســة احلكــم وصــورة ضبطــه تقــرر باألكثريــة‬\n‫املوافقــة علــى احلكــم واهلل املوفــق قاضــي اســتئناف لــي وجهــة نظــر‬\n\n\n                                                                                        ‫‪136‬‬\n\f      ‫ختمــه وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه‬\n      ‫وتوقيعــه ) أ‪.‬ه ـ وعليــه فقــد أمــرت بإحلاقــه علــى ســجله وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                  ‫‪ 1434/11/12‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪ 33489250‬وتاريــخ‬\n      ‫‪1434/10/19‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪...../‬‬\n      ‫القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد ‪34298408‬‬\n      ‫وتاريــخ ‪ 1434/8/16‬هـ ـ واملتضمــن دعــوى‪ ...../‬مينــي اجلنســية ضــد‪...../‬‬\n      ‫واحملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه‬\n      ‫تقــرر باألكثريــة املوافقــة علــى احلكــم واهلل املوفق‪.‬وصلــى اهلل علــى‬\n                                            ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪137‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":129,"source_page_end":137,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f88d43166c5fa1a4b9c5dce4e615a333726c9ebcc347553df318fe54383b7174","normalized_text_hash":"a53c39f21e3475317afc3abf387fb4fe16adcb32b27bdf642e2c81dd8a98d0f9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p129-34298408"},{"id":"29053c42-890e-521e-a956-475146ff71b0","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -عقد مضاربة -تدافع اختصاص حسمة املجلس األعلى للقضاء -صور فواتير شراء وعدم وجود أصولها -مطالبة بإعادة رأس املال مع األرباح -عجز عن إثبات الدفع بعدم االستحقاق -نكول املدعى عليه عن اليمن -ثبوت الدعوى مع التنازل عن","document_number":"346305","case_number":"33258094","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/7","year":"1434","subject":"شراكة -عقد مضاربة -تدافع اختصاص حسمة املجلس األعلى للقضاء -صور فواتير شراء وعدم وجود أصولها -مطالبة بإعادة رأس املال مع األرباح -عجز عن إثبات الدفع بعدم االستحقاق -نكول املدعى عليه عن اليمن -ثبوت الدعوى مع التنازل عن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫تاريخه‪1434/1/7 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪346305 :‬‬\n                   ‫َر ْق ُم الدعوى‪33258094 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34178269‬تاريخه‪1434/4/3:‬هـ‬\n\n\n‫شــراكة ‪ -‬عقــد مضاربــة ‪ -‬تدافــع اختصــاص حســمة املجلــس األعلــى‬\n‫للقضــاء ‪ -‬صــور فواتيــر شــراء وعــدم وجــود أصولهــا ‪ -‬مطالبــة بإعــادة‬\n‫رأس املــال مــع األربــاح ‪ -‬عجــز عــن إثبــات الدفــع بعــدم االســتحقاق‬\n‫‪ -‬نكــول املدعــى عليــه عــن اليمــن ‪ -‬ثبــوت الدعــوى مــع التنــازل عــن‬\n                                                                   ‫األربــاح‪.‬‬\n\n\n\n\n‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                           ‫علــى مــن أنكــر)‪.‬‬\n‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬علــى اليــد مــا أخــذت حتــى‬\n                                                                     ‫تؤديــه)‪.‬‬\n\n\n\n\n‫ادعــى وكيــل املدعــي أن موكلــه اتفــق مــع املدعــى عليــه علــى الدخــول‬\n‫معــه يف مســاهمة لغــرض املتاجــرة بأجهــزة حاســب آلــي وســلمه نصيبــه‬\n‫مــن رأس املــال علــى أن تصــرف األربــاح يف نهايــة كل شــهر دون أن‬\n‫يتفقــا علــى نســبة محــددة مــن الربــح‪ ،‬إال أن املدعــى عليــه لــم يقــم بإعــادة‬\n‫رأس املــال واألربــاح ملوكلــه‪ ،‬لــذا طلــب إلــزام املدعــى عليــه بدفــع رأس‬\n‫املــال مــع األربــاح ملوكلــه‪ ،‬أنكــر املدعــى عليــه مــا جــاء يف الدعــوى‬\n\n                                                                                        ‫‪138‬‬\n\f      ‫ا ســوى أنــه اســتلم مــن املدعــي جــزء مــن املبلــغ املدعــى‬   ‫جملــة وتفصي ـ ً‬\n      ‫بــه نظيــر قيمــة أجهــزة حاســب آلــي اشــتراها منــه‪ ،‬طلبــت احملكمــة‬\n      ‫مــن املدعــى عليــه إثبــات مــا دفــع بــه فقــدم صــور ًا لفواتيــر تتضمــن بيــع‬\n      ‫أجهــزة للمدعــي وعجــز عــن إحضــار أصولهــا وقــرر عــدم رغبتــه يف ميــن‬\n      ‫خصمــه علــى نفــي دفعــه‪ ،‬طلبــت احملكمــة مــن املدعــي البينــة علــى‬\n      ‫باقــي املبلــغ الــذي لــم يقــر املدعــى عليــه باســتالمه فقــرر أنــه ال بينــة‬\n      ‫لديــه وطلــب ميــن املدعــى عليــه علــى نفيــه فنــكل عــن أدائهــا وامتنــع عــن‬\n      ‫بذلهــا رغــم إنــذاره بأنــه ســيقضى عليــه بالنكــول‪ ،‬املدعــي قــرر تنازلــه‬\n      ‫عــن املطالبــة باألربــاح‪ ،‬قضــت احملكمــة بثبــوت تنــازل املدعــي عــن‬\n      ‫املطالبــة باألربــاح وحكمــت علــى املدعــى عليــه بدفــع املبلــغ املدعــى بــه‬\n      ‫بعــد خصــم األربــاح للمدعــي وأفهمــت املدعــى عليــه أن لــه ميــن املدعــي‬\n      ‫أصالــة متــى مــا طلبهــا‪ ،‬قنــع املدعــي باحلكــم وعــارض املدعــى عليــه‪،‬‬\n                             ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة اخلــرج بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة باخلــرج ‪ /‬املســاعد برقــم ‪ 33258094‬وتاريــخ‬\n      ‫‪1433/04/13‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33694420‬وتاريــخ‬\n      ‫‪ 1433/04/13‬ه ـ ففــي يــوم الســبت املوافــق ‪1433/05/29‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 30‬صباحـ ًا بنــاء علــى خطــاب معالي رئيس املجلس‬\n      ‫األعلــى للقضــاء رقــم ‪ 2648‬وتاريــخ ‪1433/3/6‬ه ـ واملرفــق بــه قــرار جلنــة‬\n      ‫الفصــل يف تنــازع االختصــاص رقــم ‪/17‬ت وتاريــخ ‪1433/2/22‬ه ـ‬\n\n‫‪139‬‬\n\f‫واملتضمــن أن القضيــة مــن اختصــاص القضــاء العــام‪ ،‬وفيهــا حضــر ‪.....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬الوكيــل عــن ‪.....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وذلــك مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة عــدل محافظــة اخلــرج برقــم‬\n‫‪ 310503014356‬وتاريــخ ‪1427/2/26‬ه ـ واملجعــول فيهــا للوكيــل حق‬\n‫املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح وادعــى علــى احلاضــر‬\n‫معــه يف املجلــس الشــرعي ‪ .....‬فلســطيني اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم ‪ .....‬قائــا يف حتريــر دعــواه عليــه لقــد قــام موكلــي بتاريــخ‬\n‫‪2005/3/24‬م باالتفــاق مــع املدعــى عليــه هــذا احلاضــر علــى الدخــول‬\n‫معــه يف مســاهمة لغــرض املتاجــرة بأجهــزة احلاســب اآللــي‪ ،‬علــى أن‬\n‫تصــرف األربــاح يف نهايــة كل شــهر ميــادي ولــم يتفقــا علــى نســبة‬\n‫محــددة مــن الربــح‪ ،‬وكانــت قيمــة الســهم الواحــد عشــرة آالف‬\n‫ريالــ‪ 10000‬فســلمه موكلــي مجموعــة مــن املبالــغ علــى فتــرات متفاوتــة‬\n‫بلــغ مجموعهــا مليونــان وثمامنائــة وألــف وســبعمائة وعشــرين ريــاال‬\n‫‪ 2801720‬وقــد ربحــت هــذه املســاهمة مبلغــا قــدره ثمانيــة وخمســون‬\n‫ألفــا ومائتــان وثمانــون ريــاال‪ 58280‬وعليــه فيكــون مجمــوع املبلــغ قــدره‬\n‫مليونــان وثمامنائــة وســتون ألــف ريالــ‪ 2860000‬وقــد مضــت مــدة طويلــة‬\n‫ولــم يقــم املدعــى عليــه بإعــادة رأس املــال واألربــاح ملوكلــي‪ ،‬وقــد أقــام‬\n‫موكلــي عليــه دعــوى لــدى فضيلــة ســلفكم وصــدر بهــا الصــك رقــم‬\n‫‪ 48/4/99‬وتاريــخ ‪1427/12/4‬ه ـ املتضمــن إلزامــه بســداد مبلــغ قــدره‬\n‫مليونــان واثنــان وثالثــون ألفــا وثمانــون ريــاال ثــم رجــع فضيلتــه عــن‬\n‫احلكــم لعــدم االختصــاص وصــدق احلكــم مــن التمييز ثــم أقام موكلي‬\n‫دعــوى لــدى ديــوان املظالــم وصــدر لــه حكــم مــن الديــوان باملبلــغ‬\n\n\n                                                                                      ‫‪140‬‬\n\f      ‫الســابق‪ ،‬وذلــك مبوجــب القــرار رقــم ‪/193‬د‪/‬جت لعــام ‪1429‬ه ـ ثــم نقــض‬\n      ‫مــن التدقيــق ثــم صــدر احلكــم رقــم ‪/157‬د‪/‬جت لعــام ‪1427‬ه ـ املتضمــن‬\n      ‫عــدم اختصــاص الديــوان والئيــا يف هــذه القضيــة ثــم رفعــت للجنــة‬\n      ‫الفصل يف تنازع االختصاص والتي رأت أن هذه القضية من اختصاص‬\n      ‫احملكمــة لــذا أطلــب إلــزام املدعــى عليــه هــذا احلاضــر بدفــع رأس املــال‬\n      ‫مــع األربــاح وقــدره مليونــان وثمامنائــة وســتون ألــف ريالــ‪ 2860000‬هــذه‬\n      ‫دعــواي وأســأل املدعــى عليــه احلاضــر اجلــواب وبســؤال املدعــى عليــه عــن‬\n      ‫دعــوى املدعــي وكالــة أجــاب قائــا إن مــا ذكــره املدعــي وكالــة يف‬\n      ‫دعــواه مــن أن موكلــه قــد اتفــق معــي علــى الدخــول يف مســاهمة بتاريــخ‬\n      ‫‪2005/3/24‬م بغــرض املتاجــرة يف أجهــزة احلاســب اآللــي وأن األربــاح‬\n      ‫غيــر محــددة النســبة‪ ،‬ويكــون صرفهــا يف نهايــة كل شــهر ميــادي‬\n      ‫فهــذا غيــر صحيــح فلــم أدخــل معــه يف مســاهمة إطالقــا وأمــا مــا ذكــره‬\n      ‫مــن تســليم موكلــه إيــاي مبلغــا قــدره مليونــان وثمامنائــة وســتون ألــف‬\n      ‫ريالــ‪ 2860000‬فهــذا غيــر صحيــح‪ ،‬وإمنــا املبلــغ الــذي اســتلمته مــن‬\n      ‫املدعــي أصالــة هــو فقــط مليونــان واثنــان وثالثــون ألفــا وثمانــون‬\n      ‫ريــاال‪ 2032080‬وهــو عبــارة عــن قيمــة بضاعــة وليــس كمــا ذكــر‬\n      ‫املدعــي وكالــة‪ ،‬ومســتعد بإثبــات ذلــك‪ ،‬وبالتالــي فلســت مســتعدا‬\n      ‫باملبلــغ الــذي طلبــه املدعــي وكالــة هــذا مــا لــدي وبعــرض ذلــك علــى‬\n      ‫املدعــي وكالــة قــال الصحيــح مــا ذكرتــه ومــا ذكــره املدعــى عليــه‬\n      ‫ليــس بصحيــح‪ ،‬هــذا مــا لــدي فجــرى ســؤال املدعــى عليــه عــن بينتــه‬\n      ‫علــى مــا دفــع بــه فقــال بينتــي عبــارة عــن فواتيــر تثبــت مــا ذكرتــه ولــم‬\n      ‫أحضرهــا يف هــذه اجللســة ومســتعد بإحضارهــا يف اجللســة القادمــة‬\n      ‫ورفعــت اجللســة مــن أجــل ذلــك ومــن أجــل االطــاع علــى أوراق املعاملــة‬\n\n\n‫‪141‬‬\n\f‫ويف جلســة أخــرى حضــر الطرفــان ثــم أبــرز املدعــي وكالــة وكالــة‬\n‫جديــدة صــادرة مــن كتابــة عــدل محافظــة اخلــرج برقــم ‪33325397‬‬\n‫وتاريــخ ‪1433/7/2‬ه ـ وباالطــاع عليهــا وجــد أنهــا تتضمــن توكيــل‬\n‫املدعــي أصالــة للمدعــي وكالــة وجعــل فيهــا للوكيــل حــق املرافعــة‬\n‫واملدافعــة واإلقــرار واإلنــكار والصلــح ثــم جــرى ســؤال املدعــى عليــه‬\n‫عــن البينــة التــي وعــد بإحضارهــا فقــال لقــد أحضــرت صــور ثــاث‬\n‫فواتيــر صــادرة مــن مجموعــة ‪ ...‬للحاســب والتقنيــة وهــذه املؤسســة‬\n‫عائــدة لكفيلــي الســابق الــذي كنــت أعمــل لديه تثبــت تعاملي التجاري‬\n‫مــع املدعــي أصالــة وليــس كمــا ذكــر وكيلــه‪ ،‬وباالطــاع علــى صــور‬\n‫الفواتيــر املذكــورة تبــن أنهــا صــادرة مــن مجموعــة ‪ ....‬للحاســب‬\n‫والتقنيــة تتضمــن بيــع أجهــزة علــى العميــل ‪ .....‬األولــى برقــم ‪1732‬‬\n‫وتاريــخ ‪2005/12/7‬م مببلــغ قــدره ثالثمائــة وثمانيــة وســبعون ألفــا‬\n‫ومائتــا ريالــ‪ 378200‬والثانيــة برقــم‪ 1489‬وتاريــخ ‪2005/7/14‬م مببلــغ‬\n‫قــدره ثالثمائــة وخمســة وثمانــون ألفــا وخمســمائة ريالــ‪ 385500‬والثالثــة‬\n‫برقــم ‪ 1490‬وتاريــخ ‪2005/7/14‬م مببلــغ قــدره أربعمائة وثالثة وأربعون‬\n‫ألفــا وأربعــون ريــاال‪ 443040‬ومجمــوع قيمــة صــور الفواتيــر الثــاث‬\n‫مبلغــا قــدره مليــون ومائتــان وســتة آالف وســبعمائة وأربعــون‬\n‫ريــاال‪ 1206740‬ثــم أردف املدعــى عليــه قائــا وهــذه الفواتيــر مت أخــذ‬\n‫توقيــع املدعــي أصالــة عليهــا ألنهــا كانــت باآلجــل ثــم ســددها الحقــا‬\n‫وهنــاك فواتيــر أخــرى لــم آخــذ توقيعــه عليهــا ألنــه كان يدفــع ثمنهــا‬\n‫مباشــرة وبالتالــي فــا حاجــة ألخــذ توقيعــه عليهــا وبعرضهــا على املدعي‬\n‫وكالــة قــال إن هــذه الصــور ســبق أن اطلعــت عليهــا وهــي مــزورة وغيــر‬\n‫صحيحــة وإن كان صادقــا فليحضــر أصلهــا‪ ،‬كمــا أن التوقيــع‬\n\n\n                                                                                ‫‪142‬‬\n\f      ‫املنســوب ملوكلــي ليــس توقيعــه‪ ،‬إضافــة إلــى أن كميــات األجهــزة‬\n      ‫املوجــودة يف الفواتيــر ضخمــة جــدا وموكلــي ليــس لديــه محــات لبيــع‬\n      ‫هــذه األجهــزة وال يتعامــل بهــا‪ ،‬كمــا أنــه يف دعوانــا لــدى ديــوان املظالــم‬\n      ‫طالبنــا املدعــى عليــه بإثبــات أن مؤسســة كفيلــة ‪ ...‬متتلــك هــذه الكميــة‬\n      ‫مــن األجهــزة ولــم يســتطع إثبــات ذلــك إذ أن احملــل الــذي يعمــل فيــه محــل‬\n      ‫جتزئــة وليــس محــل جملــة‪ ،‬كمــا أن قيمــة الفواتيــر تختلــف عــن قيمــة‬\n      ‫الشــيكات املســلمة لــه هــذا مــا لــدي وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫قــال بالنســبة ألصــل الفواتيــر فــا يوجــد لــدي وذلــك ألنهــا ســرقت منــي‬\n      ‫بتاريــخ ‪1427/3/18‬ه ـ وقــد عممــت عنهــا لــدى الشــرطة مبوجــب‬\n      ‫التعميــم رقــم ‪/945/19‬ب وتاريخ‪1427/3/18‬ه ـ وبالنســبة ملــا ذكــره‬\n      ‫مــن أن موكلــه ليــس لديــه محــا لبيــع األجهــزة وال يتعامــل بهــا فأنــا ال‬\n      ‫عالقــة لــي بذلــك واملهــم عنــدي أن يشــتري مــن محلــي فقــط‪ ،‬ومــا ذكره‬\n      ‫مــن مطالبتــه إيــاي لــدى الديــوان بإثبــات هــذه الكميــة فأنــا ال علــم لــي‬\n      ‫بذلــك إذ أن وكيلــي هــو الــذي كان يحضــر لــدى الديــوان ولســت أنــا‪،‬‬\n      ‫وبالنســبة لعــدم مطابقــة مبالــغ الشــيكات مــع الفواتيــر فذلــك يعــود ألن‬\n      ‫املدعــي أصالــة كان يســدد القيمــة علــى دفعــات وبالتالــي فطبيعــي أال‬\n      ‫تتطابــق القيــم مــع بعضهــا‪ ،‬ثــم جــرى ســؤال املدعــى عليــه هــل لديــه زيادة‬\n      ‫بينــة علــى مــا دفــع بــه فقــال ال بينــة لــي ســوى هــذه الفواتيــر هــذا مــا لــدي‬\n      ‫وبســؤال املدعــي وكالــة عــن بينتــه قــال بينتــي هــي كالتالــي ‪ :‬أوال ‪/‬‬\n      ‫إقــراره لديكــم باســتالم مبلــغ قــدره مليونــان واثنــان وثالثــون ألفــا‬\n      ‫وثمانــون ريــاال ‪ . 2032080‬ثانيــا ‪ /‬أربــع شــيكات مســحوبة علــى‬\n      ‫مصــرف ‪ .....‬باســم املدعــى عليــه اثنــان منهــا ذكــر فيهــا أنهــا مقابــل‬\n      ‫مســاهمة يف مؤسســة ‪ ...‬التجاريــة‪ ،‬ثــم أبــرز صــور الشــيكات املذكورة‬\n\n\n‫‪143‬‬\n\f‫وباالطــاع عليهــا تبــن أنهــا مســحوبة علــى مصــرف ‪ .....‬صــادرة مــن‬\n‫املدعــي أصالــة ‪ .....‬األول برقــم ‪ 3‬وتاريــخ ‪1426/5/27‬ه ـ مببلــغ قــدره‬\n‫ســتمائة واثنــان وثالثــون ألــف ريالــ‪ 632000‬ألمــر ‪ .....‬وذلــك مقابــل‬\n‫املساهمة يف مؤسسة ‪ .....‬التجارية والثاني برقم ‪ 5‬وتاريخ ‪2005/9/6‬م‬\n‫مببلــغ قــدره مائتــان وســبعون ألــف ريالــ‪ 270000‬ألمــر ‪ .....‬والثالــث برقــم‬\n‫‪ 10‬وتاريــخ ‪2005/1/5‬م مببلــغ قــدره مائتــان وســبعة وســتون ألــف‬\n‫ريالــ‪ 267000‬مقابــل شــراء ‪ 47‬ســهم يف مؤسســة ‪ .....‬التجاريــة والرابــع‬\n‫برقــم ‪ 11‬وتاريــخ ‪2005/11/12‬م مببلــغ قــدره خمســمائة وثالثــة‬\n‫وخمســون ألفــا وثمانــون ريــاال‪ 553080‬ومجمــوع قيمــة الشــيكات مبلغا‬\n‫قــدره مليــون وســبعمائة واثنــان وعشــرون ألفــا وثمانــون ريــاال‪1722080‬‬\n‫وبعرضهــا علــى املدعــى عليــه صــادق عليهــا وقــال لقــد اســتلمت قيمــة‬\n‫هــذه الشــيكات مــن املدعــي أصالــة وبســؤاله عمــا كتــب علــى‬\n‫الشــيكني مــن أنهمــا مســاهمة يف مؤسســة ‪ .....‬التجاريــة قــال إننــي ال‬\n‫أذكــر ذلــك لطــول املــدة ثالثــا‪ /‬حــواالت بنكيــة مــن موكلــي للمدعــى‬\n‫عليــه علــى حســابه يف مصــرف ‪ .....‬وعددهــا أربــع حــواالت ســأحضرها‬\n‫يف اجللســة القادمــة ‪ .‬رابعــا ‪ /‬صــور لثالثــة عقــود بــن موكلــي وبــن‬\n‫املدعــى عليــه وقــد طعــن فيهــا املدعــى عليــه بالتزويــر وأنكرهــا ســابقا‬\n‫ونظــرا ألن املدعــى عليــه قــد ســحب أصلهــا مــن موكلــي حجــة حتويــل‬\n‫املؤسســة إلــى شــركة فإننــي أســتغني عــن ذكرهــا مــن ضمــن البينــات‬\n‫‪ .‬خامســا‪ /‬صــدور حكمــن األول مــن هــذه احملكمــة والثانــي حكــم‬\n‫مــن الديــوان بإلــزام املدعــى عليــه بدفــع مبلــغ قــدره مليونــان واثنــان‬\n‫وثالثــون ألفــا وثمانــون ريــاال ‪ .‬هــذا مــا لــدي مــن بينــات وبعــرض ذلــك‬\n‫علــى املدعــى عليــه قــال بالنســبة للعقــود التــي أشــار لهــا املدعــي وكالــة‬\n\n\n                                                                                      ‫‪144‬‬\n\f      ‫فهــي غيــر صحيحــة ولــم أوقــع مــع موكلــه علــى أي عقــد‪ ،‬وبالنســبة‬\n      ‫للحكمــن اللــذان أشــار إليهمــا املدعــي وكالــة فإنهمــا قــد نقضــا مــن‬\n      ‫االســتئناف ورفعــت اجللســة مــن أجــل إحضــار املدعــي وكالــة للحــواالت‬\n      ‫التــي حولهــا موكلــه للمدعــى عليــه ويف جلســة أخــرى حضــر الطرفــان‬\n      ‫ثــم جــرى ســؤال املدعــي وكالــة عــن احلــواالت التــي وعــد بإحضارهــا يف‬\n      ‫اجللســة املاضيــة فقــال نعــم لقــد أحضرتهــا ثــم أبــرز أربــع ورقــات‬\n      ‫وباالطــاع عليهــا وجــد أنهــا صــورة حلــواالت صــادرة مــن مصــرف ‪ .....‬مــن‬\n      ‫حســاب املدعــي أصالــة إلــى حســاب املدعــى عليــه وهــي علــى النحــو‬\n      ‫التالــي األولــى مببلــغ قــدره عشــرون ألــف ريالــ‪ 20000‬بتاريــخ‬\n      ‫‪2005/3/24‬م والثانيــة مببلــغ قــدره مائتــان وتســعون ألــف ريالــ‪290000‬‬\n      ‫بتاريــخ ‪2005/5/30‬م والثالثــة مببلــغ قــدره تســعة آالف وســبعمائة‬\n      ‫ريالــ‪ 9700‬بتاريــخ ‪2005/10/7‬م والرابعــة مببلــغ قــدره عشــرون ألــف‬\n      ‫ريالــ‪ 20000‬بتاريــخ ‪2005/10/7‬م ومجموعهــا مبلغــا قــدره ثالثمائــة‬\n      ‫وتســعة وثالثــون ألفــا وســبعمائة ريالــ‪ 339700‬وبعرضهــا علــى املدعــى‬\n      ‫عليــه قــال إن هــذه احلــواالت صحيحــة وعليــه فيكــون مجمــوع املبلــغ‬\n      ‫الــذي اســتلمته مــن املدعــي أصالــة قــدره مليونــان وواحــد وســتون ألفــا‬\n      ‫وســبعمائة وثمانــون ريــاال ‪2061780‬ولكــن هــذا املبلــغ كمــا ذكــرت‬\n      ‫ســابقا هــو عبــارة عــن قيمــة بضاعــة وليــس كما ذكر املدعــي وكالة‪،‬‬\n      ‫هــذا مــا لــدي ثــم جــرى ســؤال املدعــي وكالــة عــن رأس مــال موكلــه يف‬\n      ‫املســاهمة التــي يدعــي فقــال إن رأس موكلــي الــذي ســلمه للمدعــى‬\n      ‫عليــه قــدره مليونــان ومائــة وثالثــة وســتون ألفــا وثمانــون ريــاال‪2163080‬‬\n      ‫وهــو علــى النحــو التالــي ‪ -1‬مليــون وســبعمائة واثنــان وعشــرون ألفــا‬\n      ‫وثمانــون ريــاال‪ 1722080‬مبوجــب شــيكات مت ذكرهــا ســابقا ‪-2‬‬\n\n\n‫‪145‬‬\n\f‫ثالثمائــة وتســعة وثالثــون ألفــا وســبعمائة ريالــ‪ 339700‬مبوجب حواالت‬\n‫مصرفيــة مت ذكرهــا ســابقا ‪ -3 .‬مائــة وألفــا ريالــ‪ 102000‬وهــي عبــارة‬\n‫عــن مبلــغ نقــدي ســلمه موكلــي بيــد املدعــى عليــه وبذلك يصبــح مجموع‬\n‫املبلــغ قــدره مليونــان ومائــة وثالثــة وســتون ألفــا وثمانــون ريــاال‪2163080‬‬\n‫هــذا مــا لــدي ثــم جــرى ســؤال الطرفــن هــل لديهمــا مــا يضيفانــه فقــال‬\n‫املدعــى عليــه إننــي أريــد أن أضيــف أن شــاهدي ‪ .....‬مصــري اجلنســية‬\n‫قــد ســافر إلــى مصــر ســفرا نهائيا وال أســتطيع إحضــاره وأطلب االطالع‬\n‫علــى شــهادته املدونــة يف الصــك الصــادر مــن هــذه احملكمــة برقــم‬\n‫‪ 48/4/99‬وتاريــخ ‪1427/12/4‬ه ـ عليــه فقــد قــررت رفــع اجللســة مــن‬\n‫أجــل ذلــك والنتهــاء وقتهــا ويف جلســة أخــرى حضــر الطرفــان كمــا‬\n‫حضــر املدعــي أصالــة ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقم‬\n‫‪ .....‬ثــم جــرى منــا االطــاع علــى شــهادة املدعــو ‪ .....‬املدونــة علــى الصــك‬\n‫الصــادر مــن فضيلــة ســلفنا برقــم ‪ 48/4/99‬وتاريــخ ‪1427/12/4‬ه ـ‬\n‫وهــذا نصهــا « ثــم حضــر الشــاهد ‪ .....‬مبوجــب إقامــة رقــم ‪ .....‬بتاريــخ‬\n‫‪1425/9/12‬ه ـ وبســؤاله عــن شــهادته قــال إننــي حضــرت مــع ‪ .....‬واألخ‬\n‫‪ .....‬وقــد طلــب مــن ‪ .....‬تصويــر ثــاث فواتيــر بيــع بضاعــة مــن‬\n‫الكمبيوتــرات مببلــغ مليــون ومائتــن وســتة آالف وســبعمائة وأربعــن‬\n‫ريــاال وقمــت بتصويرهــا وإعطــاء ‪ .....‬صــورة منهــا وبســؤاله هــل حضــر‬\n‫عقــد البيــع أو تســليم البضاعــة فقــال إننــي لــم أحضــر عقــد البيــع وال‬\n‫تســليم البضاعــة وأنــي ســمعتهم يتكلمــون يف البضاعــة وبســؤاله عــن‬\n‫عالقتــه باملدعــو ‪ .....‬قــال إنــه مديــر املؤسســة وأعمــل حتــت إدارتــه‬\n‫لصالــح صاحــب املؤسســة كفيلــي ‪ ...‬هكــذا شــهد « وبعــرض ذلــك‬\n‫علــى املدعــي أصالــة قــال إن الشــاهد املذكــور أعرفــه وهــو يعمــل يف‬\n\n\n                                                                                      ‫‪146‬‬\n\f      ‫املؤسســة مــع املدعــى عليــه وهــو يكــذب يف شــهادته فلــم يحصــل شــيء‬\n      ‫مــن الــذي ذكــره إطالقــا هــذا مــا لــدي‪ ،‬ثــم جــرى ســؤال املدعــي أصالــة‬\n      ‫هــل لديــه زيــادة بينــة علــى دعــواه فقــال ليــس لــدي زيــادة بينــة ســوى مــا‬\n      ‫قدمــه وكيلــي فجــرى ســؤاله عــن املبلــغ النقــدي الــذي يدعــي أنــه ســلمه‬\n      ‫للمدعــى عليــه بيــده وقــدره مائــة وألفــا ريالــ‪ 102000‬هــل لديــه بينــة عليــه‬\n      ‫فقــال ال بينــة لــدي علــى ذلــك وأطلــب ميــن املدعــى عليــه علــى نفــي ذلــك‬\n      ‫وعلــى نفــي وجــود املســاهمة التــي ذكرتهــا يف دعــواي ووجــود أربــاح‬\n      ‫فيهــا هــذا مــا لــدي وبعــرض ذلــك علــى املدعــى عليــه قــال ال مانــع لــدي‬\n      ‫مــن أداء اليمــن الشــرعية علــى نفــي اســتالمي ملبلــغ املائــة وألفــي‬\n      ‫ريالــ‪ 102000‬وعلــى عــدم وجــود مســاهمة بينــي وبــن املدعــي أصالــة‬\n      ‫ولكــن أوراق القضيــة موجــودة بالكامــل لــدى احملامــي وأطلــب إمهالي‬\n      ‫للجلســة القادمــة حتــى أمتكــن مــن االطــاع عليهــا وأســتطيع أداء اليمــن‬\n      ‫علــى يقــن هــذا مــا لــدي عليــه فقــد قــررت رفــع اجللســة مــن أجــل ذلــك‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان كمــا حضــر املدعــي أصالــة ‪.....‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وبعــرض مــا مت ضبطه‬\n      ‫ســابقا علــى املدعــي أصالــة صــادق عليــه وقــال إننــي أقــرر تنازلــي عــن‬\n      ‫املطالبــة باألربــاح وأحصــر دعــواي يف املبلــغ األخيــر ومجموعــه مليونــان‬\n      ‫ومائــة وثالثــة وســتون ألفــا وســبعمائة وثمانــون ريــاال‪ 2163780‬وهــو‬\n      ‫عبــارة عــن املبلــغ الــذي أقــر بــه لديكــم وقــدره مليونــان وواحــد وســتون‬\n      ‫ألفــا وســبعمائة وثمانــون ريــاال ‪ 2061780‬إضافــة إلــى املبلــغ اآلخــر‬\n      ‫وقــدره مائــة وألفــا ريالــ‪ 102000‬فقــط علمــا بــأن قيمــة الشــيكات‬\n      ‫واحلــواالت داخلــة يف املبلــغ الــذي أقــر بــه املدعــى عليــه لديكــم عــدا‬\n      ‫املائــة وألفــي ريالــ‪ ،102000‬وبســؤال املدعــى عليــه هــل راجــع حســاباته‬\n\n\n‫‪147‬‬\n\f‫فقــال نعــم لقــد راجعتهــا ولــم أجــد أن املدعــي أصالــة ســلمني مبلــغ املائــة‬\n‫وألفــي ريالــ‪ 102000‬وبعــرض اليمــن التالــي نصهــا علــى املدعــى عليــه «‬\n‫واهلل العظيــم أن املدعــي أصالــة ‪ .....‬لــم يســلمني مبلــغ املائــة وألفــي‬\n‫ريالــ‪ 102000‬التــي يدعــي بهــا واهلل العظيــم « قــال إننــي غيــر مســتعد‬\n‫ببــذل اليمــن الشــرعية‪ ،‬وذلــك ألننــي غيــر متأكــد مــن ذلــك‪ ،‬فجــرى‬\n‫إنــذاره ثالثــا بأنــه إذا لــم يحلــف اليمــن الشــرعية فســيقضى عليــه‬\n‫بالنكــول إال أنــه امتنــع عــن أدائهــا‪ ،‬ثــم جــرى ســؤال املدعــى عليــه عــن‬\n‫دفعــه بــأن املبالــغ التــي اســتلمتها مــن املدعــي أصالــة كانــت عبــارة عــن‬\n‫قيمــة بضاعــة اشــتراها األخيــر منــه‪ ،‬هــل لديــه زيــادة بينــة علــى ذلــك‬\n‫فقــال ليــس لــدي زيــادة بينــة فجــرى إفهامــه بأنــه ليــس لــه إال ميــن املدعــي‬\n‫أصالــة علــى نفــي ذلــك فقــال ال أريــد مينيــه‪ ،‬ثــم جــرى االطــاع علــى‬\n‫احلكــم الصــادر مــن فضيلــة ســلفنا برقــم ‪ 48/4/99‬وتاريــخ‬\n‫‪1427/11/4‬ه ـ واملتضمــن إفهــام املدعــي بــأن دعــواه مــن اختصــاص‬\n‫ديــوان املظالــم واملصــدق مــن محكمــة االســتئناف برقــم ‪/122‬ق‪/5‬أ‬\n‫وتاريــخ ‪1428/3/26‬ه ـ كمــا جــرى االطــاع علــى احلكــم الصــادر مــن‬\n‫ديــوان املظالــم برقــم ‪/157‬د‪/‬ت ج‪ 7‬لعــام ‪1427‬ه ـ واملتضمــن عــدم‬\n‫اختصــاص الديــوان والئيــا بنظــر هــذه الدعــوى كمــا جــرى االطــاع‬\n‫علــى خطــاب معالــي رئيــس املجلــس األعلــى للقضــاء رقــم ‪ 2648‬وتاريــخ‬\n‫‪1433/3/6‬ه ـ واملرفــق بــه قــرار جلنــة الفصــل يف تنــازع االختصــاص رقــم‬\n‫‪/17‬ت وتاريــخ ‪1433/2/22‬ه ـ واملتضمــن قــرار اللجنــة بــأن القضيــة مــن‬\n‫اختصــاص القضــاء العــام ثــم جــرى ســؤال الطرفــن هــل لديهمــا مــا‬\n‫يضيفانــه فقــاال ليــس لدينــا مــا نضيفــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ونظــرا إلقــرار املدعــى عليــه باســتالمه مبلغــا قــدره مليونــان‬\n\n\n                                                                                         ‫‪148‬‬\n\f      ‫وواحــد وســتون ألفــا وســبعمائة وثمانــون ريــاال‪ 2061780‬مــن املدعــي‬\n      ‫أصالــة ودفــع بأنهــا قيمــة بضاعــة اشــتراها منــه‪ ،‬وأنكــر املدعــي ذلــك‬\n      ‫وعجــز املدعــى عليــه عــن إحضــار البينــة املوصــل علــى دفعــه ذلــك‪ ،‬وقــرر‬\n      ‫عــدم رغبتــه يف ميــن خصمــه علــى نفــي دفعــه ذلــك‪ ،‬ونظــرا إلنــكار‬\n      ‫املدعــى عليــه مبلــغ املائــة وألفــي ريالــ‪ 102000‬التــي ادعاهــا املدعــي‬\n      ‫وحيــث قــرر املدعــي عــدم وجــود بينــة لــه علــى ذلــك وطلــب ميــن املدعــى‬\n      ‫عليــه علــى نفــي ذلــك‪ ،‬ونظــرا المتنــاع املدعــى عليــه عــن بــذل اليمــن‬\n      ‫الشــرعية وحيــث جــرى إفهامــه ثالثــا بأنــه إذا لــم يحلــف فســيقضى عليه‬\n      ‫بالنكــول‪ ،‬وبنــاء علــى مــا قــرره أهــل العلــم مــن مشــروعية القضــاء‬\n      ‫بالنكــول‪ ،،‬ولقولــه صلــى اهلل عليــه وســلم ‪»:‬البينــة علــى املدعــي‬\n      ‫واليمــن علــى مــن أنكــر « وقولــه صلــى اهلل عليــه وســلم ‪»:‬علــى اليــد مــا‬\n      ‫أخــذت حتــى تؤديــه « ونظــرا لتقريــر املدعــي أصالــة تنازلــه عــن املطالبــة‬\n      ‫باألربــاح لــكل مــا تقــدم فقــد ثبــت لــدي تنــازل املدعــي أصالــة عــن‬\n      ‫املطالبــة باألربــاح وحكمــت علــى املدعــى عليــه ‪ .....‬بدفــع مبلــغ قــدره‬\n      ‫مليونــان ومائــة وثالثــة وســتون ألفــا وســبعمائة وثمانــون ريــاال ‪2163780‬‬\n      ‫للمدعــي أصالــة ‪ .....‬وأفهمــت املدعــى عليــه أن لــه ميــن املدعــي أصالــة‬\n      ‫متــى مــا طلبهــا‪ ،‬وبعرضــه علــى الطرفــن قــرر املدعــي أصالــة القناعــة‬\n      ‫بــه وقــرر املدعــى عليــه عدمهــا فجــرى إفهامــه بأنــه ســيجري تســليمه‬\n      ‫نســخة مــن احلكــم بتاريــخ ‪1434/1/7‬ه ـ لتقــدمي اعتراضــه عليــه يف مدة‬\n      ‫أقصاهــا ثالثــون يومــا مــن ذلــك التاريــخ ففهــم ذلــك وكان ختــام اجللســة‬\n      ‫يف الســاعة ‪ 11 : 00‬صباح ـ ًا وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                      ‫محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/01/05‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق‪ 1434/05/06‬ه ـ‬\n\n\n‫‪149‬‬\n\f‫فتحــت اجللســة الســاعة ‪ 12 : 30‬وفيهــا كانــت قــد عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف برقــم ‪ 34653461‬وتاريــخ ‪1434/4/9‬ه ـ بشــرح‬\n‫فضيلــة رئيــس احملكمــة رقــم ‪ 34/653461‬وتاريــخ ‪1434/4/14‬ه ـ‬\n‫وبرفقهــا القــرار الصــادر مــن الدائــرة اخلامســة لتمييــز القضايــا احلقوقيــة‬\n‫مبحكمــة االســتئناف بالرياض رقــم ‪ 34178269‬وتاريخ ‪1434/4/3‬هـ‬\n‫املتضمــن املصادقــة علــى احلكــم وقــد ظهــر الصــك مبــا نصــه ( احلمــد‬\n‫هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك برقــم ‪ 346305‬وتاريــخ‬\n‫‪1434/1/7‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة العامــة باخلــرج‬\n‫الشــيخ ‪ .....‬وأصدرنــا القــرار رقــم ‪ 34178269‬وتاريــخ ‪1434/4/3‬ه ـ‬\n‫املتضمــن أنــه لــم يظهــر مــا يوجــب االعتــراض علــى احلكــم واهلل املوفــق‬\n‫قاضي اســتئناف ‪ .....‬توقيعه وختمه قاضي اســتئناف ‪ .....‬توقيعه وختمه‬\n‫رئيــس الدائــرة ‪ .....‬توقيعــه وختمــه) أ‪.‬ه ـ لــذا جــرى احلاقــه والتهميــش‬\n‫مبوجبــه وكان ختــام اجللســة الســاعة (‪ )1:00‬وبــاهلل التوفيــق‪ ،‬وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه وســلم ‪ .‬حرر يف ‪1434/5/6‬هـ‪.‬‬\n\n\n\n\n                                                                                     ‫‪150‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":138,"source_page_end":150,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0b6c0b0deed2033ce4a6d7a64c5d2715799c96615e2c3afd4f343aab61bcf34f","normalized_text_hash":"d4505046b802c1a2ac198efc3f76bb7e048a1cbbe2cea8023e6f9267d1f8982b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p138-346305"},{"id":"14b33022-ec33-5784-9828-a446123a422d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة مالية -إعادة مبلغ -إدعاء املدعي أن املبلغ سلفة -دفع املدعى عليه أن املبلغ مضاربة -كمبيالة ال تتضمن سبب املبلغ -شهادة شهود غير موصلة -بينة املدعى عليه وميينه -إحضار شاهد بعد احلكم -القول قول املضارب يف الربح واخلسارة -صرف نظر عن الدعوى.","document_number":"34176551","case_number":"33311796","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/1","year":"1434","subject":"مطالبة مالية -إعادة مبلغ -إدعاء املدعي أن املبلغ سلفة -دفع املدعى عليه أن املبلغ مضاربة -كمبيالة ال تتضمن سبب املبلغ -شهادة شهود غير موصلة -بينة املدعى عليه وميينه -إحضار شاهد بعد احلكم -القول قول املضارب يف الربح واخلسارة -صرف نظر عن الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/4/1 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34176551 :‬‬\n                         ‫َر ْق ُم الدعوى‪33311796 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34275764‬تاريخه‪1434/7/23:‬هـ‬\n\n\n      ‫مطالبــة ماليــة ‪ -‬إعــادة مبلــغ ‪ -‬إدعــاء املدعــي أن املبلــغ ســلفة ‪ -‬دفــع‬\n      ‫املدعــى عليــه أن املبلــغ مضاربــة ‪ -‬كمبيالــة ال تتضمــن ســبب املبلــغ‬\n      ‫‪ -‬شــهادة شــهود غيــر موصلــة ‪ -‬بينــة املدعــى عليــه وميينــه ‪ -‬إحضــار‬\n      ‫شــاهد بعــد احلكــم‪ -‬القــول قــول املضــارب يف الربــح واخلســارة ‪ -‬صــرف‬\n                                                                 ‫نظــر عــن الدعــوى‪.‬‬\n\n\n\n\n      ‫مــا قــرره الفقهــاء مــن أن القــول يف الربــح واخلســارة هــو قــول املضــارب‬\n                                                                        ‫مــع ميينــه‪.‬‬\n\n\n\n\n      ‫أقــام املدعــي وكالــة دعــواه ضــد املدعــى عليــه بأنــه أخــذ مــن موكلــه‬\n      ‫مبلــغ أربعمائــة وثالثــة وخمســن ألــف ريــال ألجــل أن يشــتري لــه بيت ـ ًا‬\n      ‫ويزوجــه ولكنــه لــم يفعــل وعنــد مطالبتــة باملبلــغ دفــع مائــة ألــف ريــال‬\n      ‫ولــم يدفــع الباقــي وطالــب إلزامــه بســدادها وقــد دفــع املدعــى عليــه أن‬\n      ‫املبلــغ أخــذه ليضــارب بــه يف األســهم وقــد خســرها ولــم يبــق إال خمســة‬\n      ‫وثمانــن ألــف ريــال أكملهــا عمــه إلــى مائــة ألــف واعطاهــا للمدعــي‬\n      ‫وأستشــهد بشــاهد علــى ذلــك وجــرى حتليفــه اليمــن وحكمــت‬\n      ‫احملكمــة بــرد دعــوى املدعــي وإخــاء ســبيل املدعــى عليــه‪ ،‬اعتــرض‬\n\n‫‪151‬‬\n\f‫املدعــي بالئحــة وأحضــر شــاهد ًا وقــررت احملكمــة عــدم تأثيــر ذلــك‬\n             ‫علــى احلكــم وجــرى التصديــق مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33311796‬وتاريــخ‬\n‫‪ 1433/05/04‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33781349‬وتاريــخ‬\n‫‪ 1433/05/04‬ه ـ ويف يــوم األربعــاء املوافــق‪ 1433/07/09‬ه ـ فتحــت‬\n‫اجللســة وفيهــا حضــر (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )........‬بصفتــه وكيــا عــن (‪ )........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ )........‬مبوجــب الوكلــة رقــم ‪ 17673‬يف‬\n‫‪1432/04/11‬ه ـ الصــادرة مــن كتابــة عــدل الثانيــة بالطائــف واملخــول‬\n‫لــه فيهــا حــق املرافعــة واملدافعــة وحضــور اجللســات واملطالبــة وادعــى‬\n‫علــى احلاضــر معــه يف مجلــس احلكــم (‪ )........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ )........‬بصفتــه وكيــا عــن (‪ )........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬مبوجــب الوكالــة رقــم‬\n‫‪ 3317327‬يف ‪1433/01/10‬ه ـ الصــادرة مــن كتابــة عــدل الثانية غرب‬\n‫مكــة املكرمــة واملخــول لــه فيهــا حــق املدافعــة واملرافعــة وحضــور‬\n‫اجللســات قائــا يف دعــواه إن املدعــى عليــه أصالــة ســبق وأن اســتغل طيبة‬\n‫والــدي موكلــي وجهلــه وكبــر ســنه وأخــذ منــه مبلــغ وقــدره أربعمائــة‬\n‫وثالثــة وخمســون ألــف ريــال مدعيــا أنــه سيشــتري بهــا لوالــدي منــزال‬\n‫وأنــه ســيزوجه منهــا إال أنــه لــم يفعــل ذلــك ولــم يعــد املبلــغ لوالــدي ثــم بعــد‬\n\n                                                                                              ‫‪152‬‬\n\f      ‫مطالبــة والــدي لــه بإعــادة املبلــغ أعــاد منــه مبلــغ وقــدره مائــة ألــف ريــال‬\n      ‫وذلــك عــن طريــق عــم املدعــى عليــه أصالــة (‪ )........‬ولــم يعــد الباقــي حتــى‬\n      ‫تاريخــه أطلــب احلكــم بإلــزام املدعــى عليــه بــأن يعيــد لوالــدي موكلــي‬\n      ‫املبلــغ املتبقــي بذمتــه وقــدره ثالثمائــة وثالثــة وخمســون ألــف ريــال هــذه‬\n      ‫دعــواي وبســؤال املدعــى عليــه وكالــة عــن دعــوى املدعــي قــال ماذكــره‬\n      ‫املدعــي فيــه مغالطــات والواقــع أن موكلــي أخــذ مــن املدعــي أصالــة‬\n      ‫مبلــغ وقــدره أربعمائــة وثالثــة وخمســون ألــف ريــال للمســاهمة فيهــا يف‬\n      ‫ســوق األســهم وكل ذلــك كان بنــاء علــى طلــب املدعــي أصالــة علــى أن‬\n      ‫يكــون ملوكلــي نســبة مــن األربــاح وأمــا ذكــر مــن أن موكلــي أعــاد‬\n      ‫للمدعــي أصالــة مبلــغ مائــة ألــف ريــال ســلمت لــه عــن طريــق عمــه‬\n      ‫املذكــور فأســال فيهــا موكلــي وأفيدكــم يف اجللســة القادمــة هكــذا‬\n      ‫أجــاب عندهــا أضــاف املدعــي وكالــة قائــا ماذكــره املدعــى عليــه‬\n      ‫وكالــة غيــر صحيــح والصحيــح ماذكرتــه ووالــدي كبيــر يف الســن‬\n      ‫وجاهــل واليعــرف ســوق األســهم ويف جلســة أخــرى حضــر املدعــي‬\n      ‫وكالــة كمــا حضــر يف هــذه اجللســة املدعــى عليــه أصالــة (‪)........‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬وبعــرض مــامت‬\n      ‫ضبطــه علــى املدعــى عليــه قــال ماذكــره املدعــي مــن أننــي أخــذت مــن‬\n      ‫والــده مبلــغ أربعمائــة وثالثــة وخمســون ألــف ريــال فهــذا صحيــح وكانت‬\n      ‫بنــاء علــى طلبــه وقــد أمرنــي أن ادخــل باملبلــغ ســوق االســهم وكان ذلــك‬\n      ‫بطلبــه وعلمــه ثــم بعــد خســارة االســهم طلــب منــي بيــع االســهم علــى‬\n      ‫خســارتها ورفــض اإلنتطــار وبعــد بيعهــا خرجــت االســهم مببلــغ خمســة‬\n      ‫وثمانــون ألــف ريــال فدفعتهــا للمدعــي أصالــة وأضــاف عليهــا أحــد‬\n      ‫أعمامــي مبلــغ وقــدره خمســة عشــر ألــف ريــال فهــذه املائــة ألــف التــي‬\n\n\n‫‪153‬‬\n\f‫ذكــر املدعــي وكالــة أنهــا عــادت ملوكلــه هكــذا أجــاب عندهــا‬\n‫أضــاف املدعــي وكالــة قائــا مــا ذكــره املدعــى عليــه غيــر صحيــح‪.‬‬\n‫والصحيــح ماذكرتــه وقــد كان لــدى موكلــي ســند علــى املدعــى عليــه‬\n‫يتضمــن أن ملوكلــي يف ذمــة املدعــى عليــه مبلــغ وقــدره أربعمائــة وســتون‬\n‫ألــف ريــال قــرض حســن إال أن املدعــى عليــه اســتطاع أن يســحب هــذا‬\n‫الســند مــن موكلــي ويدفــع لــه كمبيالــة تتضمــن مبلــغ وقــدره أربعمائــة‬\n‫وثالثــة وخمســون ألــف ريــال وهــي عامــة ولــم يذكــر فيهــا أنهــا مقابــل‬\n‫قــرض حســن وقــد كتبهــا ابــن عمــه املدعــو (‪ )........‬عندهــا أضــاف‬\n‫املدعــى عليــه قائــا هــذا الــكالم غيــر صحيــح فلــم يكــن هنــاك ســند‬\n‫كمــا يذكــر املدعــي وكالــة وأمــا الكمبيالــة التــي يذكرهــا املدعــي‬\n‫وكالــة فأنــا الــذي كتبتهــا وأشــهدت عليهــا عندهــا أضــاف املدعــي‬\n‫وكالــة قائــا إذا حلــف املدعــى عليــه علــى نفــي ماذكرتــه وأنــه لــم‬\n‫يكــن هنــاك ســند علــى املدعــى عليــه بالوصــف الــذي ذكرتــه وأن‬\n‫املدعــى عليــه لــم يســحب ذلــك الســند مــن والــدي بعــد ذلــك وأن املذكور‬\n‫(‪ )........‬لــم يكــن هــو الكاتــب للكمبيالــة التــي ذكرتهــا فــإن موكلي‬\n‫يقبــل ميينــه يف ذلــك ومســتعد ألن يتنــازل عــن هــذه الدعــوى ويف جلســة‬\n‫أخــرى حضــر املدعــي أصالــة (‪ )........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ )........‬وحضــر حلضــوره املدعــى عليــه أصالــة ويف هــذه‬\n‫اجللســة قــرر املدعــي أصالــة قائــا إننــي ال أزال أطالــب املدعــى عليــه‬\n‫أصالــة باملبالــغ التــي ذكرهــا وكيلــي يف اجللســات الســابقة وال أقبــل‬\n‫ميــن املدعــى عليــه أصالــة بخصــوص مــا دون يف اجللســة الســابقة عندهــا‬\n‫جــرى ســؤال املدعــى عليــه أصالــة عــن بينتــه علــى مــا جــاء يف إجابــة‬\n‫وكيلــه وإجابتــه يف اجللســات املاضيــة فقــال لــدي البينــة علــى ذلــك‬\n\n\n                                                                                 ‫‪154‬‬\n\f      ‫وأطلــب إمهالــي إلحضارهــا ويف جلســة أخــرى حضــر املدعــي أصالــة‬\n      ‫واملدعــى عليــه أصالــة وبســؤال املدعــى عليــه أصالــة عــن بينتــه التــي وعــد‬\n      ‫بإحضارهــا فقــال أحضرتهــا يف هــذه اجللســة ويف هــذه اجللســة حضــر‬\n      ‫(‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬وبســؤاله‬\n      ‫عمــا لديــه مــن شــهادة اشــهد هلل بأننــي اجتمعــت يف بيتــي أنــا وأخــي‬\n      ‫فيصــل ووكيــل املدعــي ابنــه (‪ )........‬وكانــت هنــاك مطالبــة ماليــة‬\n      ‫دائــرة بــن املدعــي أصالــة واملدعــى عليــه أصالــة فســمعت (‪ )........‬ابــن‬\n      ‫املدعــي أصالــة يف بيتــي يقــول إن والــدي اتصــل علــي وأخبرنــي قائــا مــا‬\n      ‫رايــك أن نشــغل املبلــغ الــذي لــدي وقــدره أربعمائــة وثالثــة وخمســن ألــف‬\n      ‫ريــال يف ســوق األســهم عــن طريــق (‪ )........‬املدعــى عليــه أصالــة فقلــت لــه‬\n      ‫تــوكل علــى اهلل هــذا مــا أشــهد بــه واهلل علــى مــا أقــول شــهيد هكــذا‬\n      ‫شــهد كمــا حضــر يف هــذه اجللســة (‪ )........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ )........‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد‬\n      ‫هلل أننــا اجتمعنــا أنــا وأخــي (‪ )........‬يف بيتــه مــع (‪ )........‬وكيــل املدعــي‬\n      ‫أصالــة حملاولــة اإلصــاح فيمــا بينهــم وبــن املدعــى عليــه (‪)........‬‬\n      ‫بخصــوص مبالــغ ماليــة فســألنا (‪ )........‬املذكــور عــن املبالــغ املاليــة‬\n      ‫فقــال إن والــدي اتصــل علــى وقــال لــي مــا رأيــك أن نشــغل املبلــغ الــذي‬\n      ‫لــدي وقــدره أربعمائــة وثالثــة وخمســن ألــف ريــال يف ســوق األســهم عــن‬\n      ‫طريــق (‪ )........‬املدعــى عليــه أصالــة فقلــت لــه تــوكل علــى اهلل هــذا مــا‬\n      ‫أشــهد بــه واهلل علــى مــا أقــول شــهيد هكــذا شــهد كمــا أحضــر‬\n      ‫للشــهادة (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)........‬‬\n      ‫وبســؤاله عمــا لديــه مــن شــهادة اشــهد هلل أنــه حضــر لــدي املدعــى عليــه‬\n      ‫أصالــة (‪ )........‬يف اســتراحة مبكــة وكان معــي أخــي (‪ )........‬وشــخص‬\n\n\n‫‪155‬‬\n\f‫يدعــى (‪ )........‬وكان مــع املدعــى عليــه (‪ )........‬كمبيالــة وطلــب منــا‬\n‫الثالثــة جميعــا أن نشــهد علــى تلــك الكمبيالــة وبســؤالنا لــه عــن‬\n‫الكمبيالــة قــال أعطانــي (‪ )........‬مبلــغ مالــي أذكــر اآلن أنــه أربعمائــة‬\n‫وثالثــة وخمســون ألــف ريــال أو أربعمائــة وخمســة وثالثــون ألــف ريــال‬\n‫ألجــل أن أضــارب لــه يف ســوق األســهم وحفظــا حلقــه أريــد حتريــر هــذه‬\n‫الكمبيالــة وأريــد شــهادتكم عليهــا هكــذا شــهد وبعــرض الشــهود‬\n‫وشــهاداتهم علــى املدعــي قــال شــهادتهم غيــر صحيحــة واملبلــغ هــو قــرض‬\n‫حســن أقرضتهــا للمدعــى عليــه وبســؤاله عــن بينتــه علــى أن املبلــغ قــرض‬\n‫حســن قــال بينــي وبــن املدعــى عليــه (‪ )........‬ســند يتضمــن إقــرار منــه أن‬\n‫املبلــغ قــرض حســن إال أنــه ســحب منــي ذلــك الســند وأعطانــي كمبيالــة‬\n‫وليــس لــدي مايثبــت أنــه ســحب منــي الســند وإذا نفــى ذلــك فأطلــب ميينــه‬\n‫علــى ذلــك وبعرضــه علــى املدعــى عليــه قــال لــم اســحب منــه أي ســند‬\n‫وليــس بينــي وبينــه مكاتبــات إال الكمبيالــة التــي ذكــر كمــا أن‬\n‫الكمبيالــة أنــا الــذي كتبتهــا بنفســي ومســتعد علــى احللــف علــى نفــي‬\n‫مــا ذكــره مــن أننــي ســحبت الســند الــذي يذكــره منــه ثــم اســتعد‬\n‫باحللــف فحلــف قائــا واهلل العلــي العظيــم الــذي ال إلــه إال هــو الغالــب‬\n‫الطالــب املــدرك املهلــك أننــي ماســحبت مــن املدعــي أي ســندات تتضمــن‬\n‫أن املبلــغ املدعــى بــه قــرض حســن هكــذا حلــف ثــم أضــاف املدعــي بــأن‬\n‫الســند املثبــت للمبلــغ حاليــا هــو الكمبيالــة املؤرخــة بتاريــخ‬\n‫‪1429/11/05‬ه ـ واملرفــق صــورة منهــا يف املعاملــة كمــا أضــاف املدعــى‬\n‫عليــه قائــا بأننــي مســتعد باحللــف مــع شــهادة الشــاهد الثالــث علــى أن‬\n‫الكمبيالــة محــررة يف املبلــغ املالــي املــدون فيهــا واملتضمــن أربعمائــة‬\n‫وثالثــة وخمســون ألــف ريــال علــى أن ذلــك املبلــغ اســتلمته مــن املدعــي‬\n\n\n                                                                                     ‫‪156‬‬\n\f      ‫ألجــل املضاربــة لــه يف ســوق األســهم عندهــا أذنــت لــه باحللــف علــى ذلــك‬\n      ‫ثــم حلــف قائــا واهلل العلــي الــذي ال إلــه إال هــو الغالــب الطالــب املــدرك‬\n      ‫املهلــك أن املبلــغ الــذي تضمنتــه الكمبيالــة التــي شــهد عليهــا الشــاهد‬\n      ‫الثالــث شــاهر وشــهد عليهــا املدعــو (‪ )........‬واملؤرخــة بتاريــخ‬\n      ‫‪1429/11/05‬ه ـ واملتضمنــة ملبلــغ أربعمائــة وثالثــة وخمســون ألــف ريــال‬\n      ‫هــو مبلــغ للمدعــي ســلمني إيــاه للمضاربــة لــه يف ســوق األســهم وليــس‬\n      ‫قــرض حســن واهلل علــى مــا أقــول شــهيد هكــذا حلــف ويف جلســة أخرى‬\n      ‫وفيهــا حضــر املدعــي أصالــة واملدعــى عليــه أصالــة ويف هــذه اجللســة‬\n      ‫جــرى تأمــل مــا مت ضبطــه ســابقا كمــا جــرى االطــاع علــى أوراق‬\n      ‫املعاملــة ومنهــا الصــك رقــم ‪ 32220243‬يف ‪1432/08/25‬ه ـ والصــادر‬\n      ‫مــن هــذه احملكمــة واملتضمــن احلكــم علــى املدعــى عليــه بتســليم‬\n      ‫املدعــي أصالــة مبلــغ وقــدره ثالثمائــة وثالثــة وخمســون ألــف ريــال‬\n      ‫واملنقــوض مــن محكمــة االســتئناف مبكــة املكرمــة بالقــرار رقــم‬\n      ‫‪ 33191694‬يف ‪1433/04/14‬ه ـ فبنــاء علــى ماتقــدم مــن الدعــوى‬\n      ‫واإلجابــة ومبــا أن املدعــى عليــه أقــر بإســتالمه ملبلــغ وقــدره أربعمائــة‬\n      ‫وثالثــة وخمســون ألــف ريــال ومبــا أنــه دفــع بــأن املبلــغ املدعــى بــه مســلم‬\n      ‫لــه مــن قبــل املدعــي ألجــل املضاربــة لــه بســوق األســهم ومبــا أنــه لــم يقــم‬\n      ‫البينــة املوصولــة علــى مادفــع ومبــا أن املدعــي قــرر بــأن بينتــه علــى دعــواه‬\n      ‫القــرض هــي ســند يتضمــن إقــرار املدعــى عليــه بإقتراضــه للمبلغ املدعى‬\n      ‫بــه ومبــا أنــه قــرر بــأن ذلــك الســند أخــذه منــه املدعــى عليــه ومبــا أن‬\n      ‫املدعــى عليــه نفــى ذلــك ومبــا أن املدعــي طلــب ميــن املدعــى عليــه علــى‬\n      ‫ذلــك النفــي ومبــا أن املدعــى عليــه حلــف بنحــو ماطلــب منــه ومبــا أن‬\n      ‫املدعــي قــرر بعــد ذلــك بــأن املثبــت لدعــواه هــو الكمبيالــة ومبــا أن‬\n\n\n‫‪157‬‬\n\f‫الشــاهد الثــاث املــدون شــهادته أعــاه شــهد بــأن املبلــغ الــذي تضمنتــه‬\n‫الكمبيالــة هــو مضاربــة يف ســوق األســهم وليــس قرضــا ومبــا أن املدعــى‬\n‫عليــه حلــف مــع شــهادة الشــاهد الثالــث علــى أن مبلــغ الكمبيالــة هــو‬\n‫مضاربــة يف ســوق األســهم وليــس قرضــا ولقضــاء النبــي صلــى اهلل عليــه‬\n‫وســلم بالشــاهد واليمني ومبا أن املدعى عليه قرر خســارته يف املضاربة‬\n‫وأنــه لــم يتبــق ســوى مبلــغ خمســة وثمانــن ألــف ريــال ومبــا أن املدعــي‬\n‫وكالــة قــرر باســتالمه مبلــغ مائــة ألــف ريــال وملــا قــرره الفقهــاء مــن أن‬\n‫القــول يف الربــح واخلســارة هــو قــول املضــارب لذلــك كلــه فقــد صرفــت‬\n‫النظــر عــن دعــوى املدعــي وأخليــت ســبيل املدعــى عليــه من هــذه الدعوى‬\n‫وبذلــك كلــه حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n‫عليــه القناعــة بــه وقــرر املدعــي اعتراضــه علــى احلكــم بتقــدمي الئحــة‬\n‫اعتراضيــة وطلــب االســتئناف وأجيــب لطلبــه وأفهــم مبراجعــة احملكمــة‬\n‫يــوم األربعــاء املوافــق ‪1434/04/03‬ه ـ الســتالم صــورة مــن احلكــم‬\n‫لتقــدمي اعتراضــه عليــه يف مــدة أقصاهــا ثالثــون يومــا مــن ذلــك التاريــخ‬\n‫إذا لــم يقــدم اعتراضــه خاللهــا ســقط حقــه يف االعتــراض واكتســب‬\n‫احلكــم القطعيــة حــرر يف ‪1434/04/01‬ه ـ وصلــى اهلل وســلم على نبينا‬\n                                            ‫محمد وعلى آله وصحبه أجمعني ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافــق ‪1434/06/24‬ه ـ فتحــت‬\n‫اجللســة ملناقشــة الئحــة املدعــي بخصــوص مــا ورد فيهــا يف البنــد ثالث ـ ًا‬\n‫واملتضمــن أن لديــه بينــة علــى النحــو الــوارد يف الالئحــة ويف هــذه اجللســة‬\n‫حضــر املدعــي أصالــة واملدعــى عليــه أصالــة كمــا حضــر يف هــذه‬\n‫اجللســة (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)........‬‬\n‫بصفتــه وكيــا عــن (‪ )........‬الوكيــل عــن املدعــي أصالــة بالوكالة رقم‬\n\n\n                                                                                      ‫‪158‬‬\n\f      ‫‪ 34450160‬يف ‪1434/4/13‬ه ـ وبســؤال املدعــي أصالــة عــن بينتــه قــال‬\n      ‫بينتــي أن املدعــى عليــه حضــر لــدى الشــاهدين وهمــا (‪ )........‬و(‪)........‬‬\n      ‫ابنــي (‪ )........‬وأخبرهمــا أن يف ذمتــه لــي مبلــغ وقــدره ثالثمائــة وثالثــة‬\n      ‫وخمســون ألــف ريــال ويف هــذه اجللســة حضــر (‪ )........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )........‬وبســؤاله عمــا لديــه مــن شــهادة‬\n      ‫قــال أشــهد هلل أن املدعــى عليــه هــذا احلاضــر حضــر لــدي يف منزلــي يف‬\n      ‫الهــدا وطلــب منــي أن أكلــم لــه املدعــي لتأجيلــه يف دفــع مبلــغ وقــدره‬\n      ‫ثالثمائــة وثالثــة وخمســون ألــف ريــال مــدة ســنة وثالثــة أشــهر اعتبــارا‬\n      ‫مــن تاريــخ حضــوره لــي وكان ذلــك يف نهايــة شــعبان عــام ‪1430‬ه ـ إال أن‬\n      ‫املدعــى عليــه لــم يفصــح لــي عــن ســبب هــذا املبلــغ وإمنــا قــال للمدعــي يف‬\n      ‫ذمتــي مبلــغ أربعمائــة وثالثــة وخمســون ألــف وصــل لــه مائــة ألــف وبقــي‬\n      ‫ثالثمائــة وثالثــة وخمســون ألــف ريــال هــذا مــا لــدي مــن شــهادة كمــا‬\n      ‫حضــر يف هــذه اجللســة (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ )........‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد أن املدعــى عليــه‬\n      ‫اتصــل بــي وطلــب حضــوري لــدى أخــي الشــاهد األول فاعتــذرت عــن‬\n      ‫احلضــور فقــال جتــد العلــم عنــد أخيــك وبعــد حضــوري عنــد أخــي كان‬\n      ‫املدعــى عليــه قــد غــادر وأخبرنــي بــأن املدعــى عليــه يطلــب منــا التوســط‬\n      ‫لــه لــدى املدعــي يف إمهالــه لســداد مبلــغ ثالثمائــة وثــاث وخمســن ألــف‬\n      ‫ريــال وباالتصــال علــى املدعــي رفــض اإلمهــال فاتصلــت علــى املدعــى‬\n      ‫عليــه وأخبرتــه بالرفــض وال أعلــم ســبب اســتحقاق ذلــك املبلــغ هــذا مــا‬\n      ‫لــدي مــن شــهادة وبعــرض الشــهود وشــهادتهم علــى املدعــى عليــه قــال‬\n      ‫حضــرت لــدى الشــاهد األول إلفادتــه عــن طبيعــة املبلــغ وأنــه كان يف‬\n      ‫األســهم حيــث إن ابــن املدعــي أفادهــم بأنــه قــرض ولــم أطلــب منهــم‬\n\n\n‫‪159‬‬\n\f‫التوســط لدى املدعي يف مهلة ألجل الســداد وأفدتهم أن املتبقي والبالغ‬\n‫ثالثمائــة وثالثــة وخمســون ألــف ريــال يف ســوق األســهم ولكــون ذلــك ال‬\n‫يؤثــر علــى مــا حكمــت بــه أعــاه كمــا أن ســائر الالئحــة ليــس فيهــا‬\n‫مــا يؤثــر علــى مــا حكمــت بــه لــذا أمــرت بإحلــاق ذلــك بالصــك وســجله‬\n‫حــرر يف ‪1434/06/24‬ه ـ ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                                     ‫آلــه وصحبــه أجمعــن ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق ‪1434/08/07‬ه ـ فتحــت‬\n‫اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫برقم ‪ 33781349‬يف ‪1434/07/29‬هـ وبرفقها القرار رقم ‪34275764‬‬\n‫يف ‪1434/07/23‬ه ـ ألصحــاب الفضيلــة قضــاة الدائرة احلقوقية الرابعة‬\n‫مبحكمــة االســتئناف مبكــة املكرمــة واملتضمــن املوافقــة علــى‬\n‫احلكــم أعــاه وللبيــان جــرى إحلاقــه حــرر يف ‪1434/08/07‬ه ـ وصلــى‬\n              ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n\n\n\n\n                                                                                 ‫‪160‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":151,"source_page_end":160,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aab8f90d1bf3be529cf91f8012aed962977a448ce75809e5a3f8a473c11d87f9","normalized_text_hash":"decba803e20e645213e30043c386fdf1ecaff5bbd3954c7561eb1916235083e5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p151-34176551"},{"id":"ace885f3-fc59-5640-a768-27eb66634154","document_type":"judgment","category":"judicial","subcategory":"general","title":"شركة مضاربة -مطالبة بأرباح وراس املال -تكييف التعامل بن الطرفن بشركة مضاربة -انعقاد شركة املضاربة بكل قول يدل عليها -شرط صحة شركة املضاربة تقدير نصيب العامل من الربح -تعدي العامل يف املضاربة يجعله ضامن ا -اقرار املدعى عليه -الزام املدعى عليه بإعادة رأس املال بشركة املضاربة -احلكم ببطان عقد املضاربة -اثبات ما اصطلح الطرفان عليه يف كيفية سداد املبلغ احملكوم به .","document_number":"33458770","case_number":"33603477","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/20","year":"1434","subject":"شركة مضاربة -مطالبة بأرباح وراس املال -تكييف التعامل بن الطرفن بشركة مضاربة -انعقاد شركة املضاربة بكل قول يدل عليها -شرط صحة شركة املضاربة تقدير نصيب العامل من الربح -تعدي العامل يف املضاربة يجعله ضامن ا -اقرار املدعى عليه -الزام املدعى عليه بإعادة رأس املال بشركة املضاربة -احلكم ببطان عقد املضاربة -اثبات ما اصطلح الطرفان عليه يف كيفية سداد املبلغ احملكوم به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/20 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33458770 :‬‬\n                          ‫َر ْق ُم الدعوى‪33603477 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3459598‬تاريخه‪1434/3/10:‬هـ‬\n\n\n       ‫شــركة مضاربــة ‪ -‬مطالبــة بأربــاح وراس املــال ‪ -‬تكييــف التعامــل بــن‬\n       ‫الطرفــن بشــركة مضاربــة ‪ -‬انعقــاد شــركة املضاربــة بــكل قــول يــدل‬\n       ‫عليهــا ‪ -‬شــرط صحــة شــركة املضاربــة تقديــر نصيــب العامــل مــن‬\n       ‫الربــح ‪ -‬تعــدي العامــل يف املضاربــة يجعلــه ضامن ـ ًا ‪ -‬اقــرار املدعــى‬\n       ‫عليــه ‪ -‬الــزام املدعــى عليــه بإعــادة رأس املــال بشــركة املضاربة ‪ -‬احلكم‬\n       ‫ببطــان عقــد املضاربــة ‪ -‬اثبــات مــا اصطلــح الطرفــان عليــه يف كيفيــة‬\n                                                        ‫ســداد املبلــغ احملكــوم بــه ‪.‬‬\n\n\n\n\n       ‫‪ -‬قــال يف كشــاف القنــاع ‪« 542/3‬وتنعقــد املضاربــة مبــا يــؤدى معنــى‬\n       ‫ذلــك أي معنــى املضاربــة والقــراض مــن كل قــول دل عليهــا ألن‬\n       ‫املقصــود املعنــى فجــاز بــكل مــا تــدل عليــه» ا‪.‬ه ـ وقــال أيضـ ًا يف ص ــ‪453‬‬\n       ‫« ومــن شــرط صحتهــا أي املضاربــة تقديــر نصيــب العامــل مــن الربــح‬\n       ‫فــان قــال رب املــال خــذ هــذا مضاربــة ولــم يذكــر ســهم العامــل لــم تصح‬\n       ‫أو قــال خــذ هــذا املــال مضاربــة ولــك جــزء حــظ أو نصيــب مــن الربــح‬\n       ‫فاملضاربــة فاســدة جلهالــة نصيــب العامــل» وقــال أيض ـ ًا ص ـ ‪« 542‬وان‬\n       ‫تعــد العامــل مــا أمــر بــه رب املــال فغصــب يــرد املــال وربحــه وال شــيء لــه‬\n                                                           ‫نظيــر عملــه كالغاصــب)‪.‬‬\n\n\n\n‫‪161‬‬\n\f‫ادعــى املدعيــان أنهمــا ســلما للمدعــى عليــه مبلغ ـ ًا مالي ـ ًا حيــث تعاقــدا‬\n‫معــه علــى أن يقــوم بتشــغيله يف التجــارة ملــدة ســنتني ويعطيهمــا أرباحــا‬\n‫شــهرية محــددة وبعــد انتهــاء املــدة يعيــد لهمــا رأس املــال وقــد انتهــت‬\n‫املــدة ولــم يســلم املدعــى عليــه مــن االربــاح ســوى ثالثــة عشــر ألــف‬\n‫ريــال كمــا حــل علــى املدعــى عليــه مبلغ ـ ًا قــدرة تســعون ألــف ريــال‬\n‫فقــال املدعــى عليــه بأنــه ســوف يشــغل هــذا املبلــغ مــدة خمــس ســنوات‬\n‫ويعطيهمــا أرباحـ ًا شــهرية وانهمــا لــم يتفقــا علــى مقــدار األربــاح الشــهرية‬\n‫وقــد انتهــت مــدة العقــد األول ولــم يســلم املدعــى عليــه للمدعيــن األربــاح‬\n‫وال رأس املــال وطلــب املدعيــان إلــزام املدعــى عليــه بتســليمهما رأس‬\n‫املــال واالربــاح مبلغــا وقــدرة مئتــان وأربعــة وعشــرون ألــف ريــال‪ ،‬صــادق‬\n‫املدعــى عليــه علــى الدعــوى جملــة وتفصيــا وقــرر ان املبلــغ املدعــى بــه‬\n‫يف ذمتــه وانــه عاجــز عــن ســداد املبلــغ كمــا قــرر املدعــى عليــه إن املبالــغ‬\n‫كان يشــغلها يف قطــع الغيــار واألســهم وانــه قــد خســر كامــل املبلــغ‪،‬‬\n‫قــرر املدعيــان ان املدعــى عليــه اخبرهمــا بــان يقــوم بتشــغيل املبالــغ يف‬\n‫قطــع غيــار الســيارات وليــس يف األســهم‪ ،‬صــادق املدعــى عليــه علــى‬\n‫ذلــك وقــرر انــه شــغل املبالــغ يف األســهم وانــه خســر كامــل املبلــغ‪ ،‬قــرر‬\n‫ناظــر القضيــة انــه بنــاء علــى الدعــوى واإلجابــة فقــد كيــف العقــد انــه‬\n‫شــركة مضاربــة وان تقريــر نصيــب العامــل شــرط لصحتهــا وهــو هنــا‬\n‫غيــر متحقــق وألن املــال قــد خســر بســبب تعــدى املدعــى عليــه ألنــه تعــد‬\n‫اذن املدعيــن ولألســباب املرصــودة يف نــص احلكــم فقــد صــدر حكــم‬\n‫ناظــر القضيــة بثبــوت بطــان العقــد بــن املدعيــن واملدعــى عليــه وإلــزام‬\n\n                                                                                        ‫‪162‬‬\n\f      ‫املدعــى عليــه بإعــادة رأس املــال للمدعيــن بعــد خصــم ما اســتلماه‪ ،‬قرر‬\n      ‫املدعيــان عــدم القناعــة وقــرر املدعــى عليــه القناعــة‪ ،‬صــدق احلكــم مــن‬\n      ‫محكمــة االســتئناف ‪ -‬عــادت املعاملــة مــن جهــة التنفيــذ‪ ،‬مت اثبــات مــا‬\n                                     ‫اصطلــح عليــه الطرفــان يف كيفيــة الســداد ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بع ــده ‪ ،‬أمــا بعــد ‪:‬‬\n      ‫فلــدي أنــا‪ .....‬القاضــي يف احملكمــة العامــة مبحافظــة القطيــف بنــاء‬\n      ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n      ‫القطيــف برقــم ‪ 33603477‬وتاريــخ ‪1433/10/15‬ه ـ واملقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331812019‬وتاريــخ ‪1433/10/15‬ه ـ ‪ ،‬حضــر‬\n      ‫املدعيــان ‪ .....‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ .....‬وزوجتــه ‪.....‬‬\n      ‫ســعودية بالســجل املدنــي رقــم‪ .....‬وحضــر حلضورهمــا املدعــى عليــه ‪.....‬‬\n      ‫ا‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وادعــى املدعــي قائـ ً‬\n      ‫‪ :‬إننــي ســبق أن تعاقــدت مــع املدعــى عليــه علــى أن أعطيــه أربعــن ألــف‬\n      ‫ـداء مــن‬\n             ‫ريــ( ‪ ) 40.000‬ــال ويقــوم بتشــغيلها يف التجــارة ملــدة ســنتني ابتـ ً‬\n      ‫‪ 2010/04/01‬م ويعطينــي أرباح ـ ًا شــهرية مقدارهــا أربعــة آآلف ريــ(‬\n      ‫‪ ) 4.000‬ــال ثــم بعــد انتهــاء املــدة يعيــد لــي رأس املــال كمــا أن زوجتــي‬\n      ‫هــذه احلاضــرة أيضـ ًا ‪ -‬تعاقــدت مــع املدعــى عليــه علــى أن تعطيــه أربعــن‬\n      ‫ألــف ريــ( ‪ ) 40.000‬ــال ويقــوم بتشــغيل املبلــغ يف التجــارة ملــدة ســنتني‬\n      ‫ـداء مــن ‪ 2010/09/01‬م ويعطيهــا أرباح ـ ًا شــهرية مقدارهــا ألفــان‬      ‫ابتـ ً‬\n      ‫وخمســمائة ري ـ ( ‪ ) 2.500‬ــال وبعــد انتهــاء املــدة يعيــد لهــا رأس املــال‬\n      ‫وقــد انتهــت املــدة ولــم يســلمنا املدعــى عليــه مــن األربــاح ســوى ثالثــة‬\n\n‫‪163‬‬\n\f‫عشــر ألــف ريــ( ‪ ) 13.000‬ــال وهــي أربــاح أول شــهرين فقــط منهــا ثمانيــة‬\n‫آآلف ريــ( ‪ ) 8.000‬ــال لــي و خمســة آآلف ريــ( ‪ ) 5.000‬ــال لزوجتــي ‪،‬‬\n‫وخــال تلــك املــدة وبعــد أن مضــى مــن العقــد ســنة وعــدة أشــهر حــلَّ علــى‬\n‫املدعــى عليــه مــن األربــاح تســعون ألــف ري ـ ( ‪ ) 90.000‬ــال لــي ولزوجتــي‬\n‫مناصفــة فطالبتــه بهــا فقــال لــي ولزوجتــي بأنــه ســيقوم بتشــغيلها لنــا‬\n‫مــدة خمــس ســنوات بعــد انتهــاء مــدة العقــد األول وســيعطينا أرباح ـ ًا‬\n‫شــهرية ولــم نتفــق علــى مقــدار األربــاح الشــهرية فوافقنــا علــى ذلــك ‪،‬‬\n‫وقــد انتهــت مــدة العقــد األول معــي يف ‪ 2012/04/01‬م ومــع زوجتــي‬\n‫يف ‪ 2012/09/01‬م ولــم يســلمنا املدعــى عليــه رأس املــال وال األربــاح‬\n‫‪ ،‬نطلــب إلزامــه بدفــع رأس املــال واألربــاح لنــا حــا ًال ومقدارهــا إجمــا ًال‬\n‫مئتــان وأربعــة وعشــرون ألــف ريــ( ‪ ) 224.000‬ــال منهــا ثمانــون ألــف ريــ(‬\n‫‪ ) 80.000‬ــال رأس مــال ومائــة وأربــع وأربعــون ألــف ريــ( ‪ ) 144.000‬ــال‬\n‫ا وبعرض‬     ‫أربــاح هكــذا ادعــى ووافقتــه علــى ذلــك زوجتــه جملة وتفصيـ ً‬\n‫ا ‪ :‬جميــع مــاورد يف دعــوى املدعــي‬       ‫ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n‫ا ولــه يف ذمتــي مئتــان وأربعــة وعشــرون ألــف‬           ‫صحيــح جملــة وتفصي ـ ً‬\n‫ريــ( ‪ ) 224.000‬ــال مقابــل مــا ذكــر ‪ ،‬وأنــا حاليـ ًا غيــر مســتعد بدفــع‬\n‫املبلــغ لعجــزي عــن ذلــك ومتــى مــا توفــر عنــدي املبلــغ فســأقوم بدفعــه ‪،‬‬\n‫ولكنــي أطلــب مــن املدعــي أن يعتــذر لــي وألمــي وإلخوانــي فأنــا أخــوه‬\n‫الشــقيق ومــا كان ينبغــي لــه أن يخاصمنــي أمــام القضــاء ألنــي أخــوه‬\n‫ومقــر لــه باملبلــغ وأنــا أطالبــه باالعتــذار ليصلــح خطــأه هكــذا أجــاب ‪.‬‬\n‫ويف جلســة ُأخــرى حضــر جميــع االطــراف فســألت املدعــى عليــه ‪ :‬أيــن‬\n‫ا ‪ :‬إننــي كنــت أشــغل املبلــغ يف قطــع الغيــار‬      ‫ذهــب املــال ؟ فأجــاب قائ ـ ً‬\n‫ويف األســهم وقــد خســرت كامــل املبالــغ التــي أخذتهــا مــن املدعيــن‬\n\n\n                                                                                          ‫‪164‬‬\n\f      ‫هكــذا أجــاب فاعتــرض علــى ذلــك املدعيــان قائلــن ‪ :‬أوالً‪ :‬نحــن دفعنــا‬\n      ‫لــك املــال بعــد االنهيــار املعــروف لســوق األســهم وثاني ـ ًا ‪ :‬أنــت قلــت لنــا‬\n      ‫بأنــك ســتقوم بتشــغيلها يف جتــارة قطــع غيــار الســيارات ولــم تقــل لنــا يف‬\n      ‫ا ‪ :‬صحيــح أنــي‬    ‫األســهم هكــذا اعترضــا فأجابهمــا املدعــى عليــه قائـ ً‬\n      ‫قلــت لكمــا بأنــي سأشــغلها يف قطــع الغيــار لكنــي يف احلقيقــة شــغلتها‬\n      ‫يف األســهم فيمــا بعــد وقــد خســرتها كاملــة أمــا أنكمــا أعطيتمانــي‬\n      ‫املبلــغ بعــد انهيــار الســوق فأجيــب عليــه بــأن الســوق حتــى اآلن ال يــزال‬\n      ‫فيــه مضاربــات وكنــت أنــا أحــد املضاربــن يف قطــاع التأمــن وقــد‬\n      ‫خســرت أمــا االنهيــار الــذي تذكرانــه فهــو االنهيــار املشــهور عــام ‪2006‬‬\n                                                        ‫م وقــد تكــرر بعــد ذلــك نــزول‬\n      ‫الســوق عــدة مــرات هكــذا أجــاب فســألت املدعــى عليــه ‪ :‬متــى أدخلــت‬\n      ‫ا ‪ :‬إننــي أدخلتــه تقريب ـ ًا‬ ‫مــال املدعيــن يف ســوق األســهم ؟ فأجــاب قائ ـ ً‬\n      ‫يف الشــهر العاشــر عــام ‪ 2011‬م وكان مقــدار املــال ثمانــون ألــف ري ـ‬\n      ‫( ‪ ) 80.000‬ــال ولــم يكــن زائــد ًا وال ناقص ـ ًا أي لــم يخســر ولــم يربــح‬\n      ‫قبــل هــذا التاريــخ هكــذا أجــاب وبعرضــه جوابــه علــى املدعيــن أفــادا‬\n      ‫قائلــن ‪ :‬نحــن ال نعلــم عــن مالنــا شــيئ ًا ســوى أنــه كان يريــد تشــغيله‬\n      ‫يف جتــارة قطــع الغيــار ولــو قــال لنــا إنــه يريــد تشــغيله يف األســهم ملــا‬\n      ‫ـاء علــى‬‫أعطينــاه شــيئ ًا هكــذا أفــادا ثــم جــرى قفــل بــاب املرافعــة فبنـ ً‬\n      ‫مــا تقــدم مــن الدعــوى احملــرر واإلجابــة املقــررة لصحــة الدعــوى وحيــث‬\n      ‫أقــر الطرفــان بوقــوع العقــد علــى الصفــة املذكــورة ‪ ،‬وقــد كيفنــا ذلــك‬\n      ‫شــركة مضاربــة كمــا قــال يف الكشــاف ج ‪ 3‬ص ‪ ( : 542‬وتنعقــد‬\n      ‫املضاربــة مبــا يــؤدي معنــى ذلــك أي معنــى املضاربــة والقــراض مــن كل‬\n      ‫قــول دل عليهــا ألن املقصــود املعنــى فجــاز بــكل مــا يــدل عليــه ) ا‪.‬ه ـ ‪.‬‬\n\n\n‫‪165‬‬\n\f‫ـف هنــا قــال‬  ‫وتقديــر نصيــب العامــل مــن الربــح شــرط لصحتهــا وهــو منتـ ٍ‬\n‫يف الكشــاف ج ‪ 2‬ص ‪ ( : 543‬ومــن شــرط صحتهــا أي املضاربــة تقديــر‬\n‫نصيــب العامــل مــن الربــح فــإن قــال رب املــال خــذ هــذا مضاربــة ولــم‬\n‫يذكــر ســهم العامــل لــم تصــح أو قــال خــذ هــذا املــال مضاربــة ولــك جــزء‬\n‫أو حــظ أو نصيــب مــن الربــح فاملضاربــة فاســدة جلهالــة نصيــب العامــل‬\n‫) وألن املــال قــد خســر بســبب تعــدي املدعــى عليــه ملــا أذن لــه فيــه مــن‬\n‫العمــل مــن قبــل رب املــال وهمــا املدعيــان وحينئــذٍ يكــون غاصبـ ًا كمــا‬\n‫قــال يف الكشــاف ج ‪ 3‬ص ‪ ( : 542‬وإن تعــدى العامــل مــا أمــر بــه رب‬\n‫املــال فغصــب يــرد املــال وربحــه وال شــيء لــه يف نظيــر عملــه كالغاصــب‬\n‫) ا‪.‬ه ـ وملــا ورد يف وقائــع املرافعــة ولغيــره فقــد حكمــت مبــا يلــي ‪ :‬أو ًال‬\n‫ثبــت لــدي بطــان العقــد الواقــع بــن املدعيــن وبــن املدعــى عليــه ‪ .‬ثانيـ ًا‬\n‫‪ :‬ألزمــت املدعــى عليــه بإعــادة رأس مــال الشــركة حــا ًال للمدعيــن بعــد‬\n‫خصــم مــا اســتلماه ســابق ًا ‪ ،‬للمدعــي إثنــن وثالثــن ألــف ري ـ ( ‪32.000‬‬\n‫) ــال وللمدعيــة خمســه وثالثــن ألــف ري ـ ( ‪ ) 35.000‬ــال هــذا مــا ظهــر‬\n‫لــي وبــه حكمــت وجــرى نطقــه علنـ ًا مبجلــس احلكــم الشــرعي الســاعة‬\n‫الثانيــة فقــررا املدعيــان عــدم القناعــة وقــرر املدعــي عليــه القناعــة‬\n‫واســتعدا بتقــدمي الئحــة اعتراضيــة فأفهمــا بتعليمــات االســتئناف وأن‬\n‫عليهمــا املراجعــة يــوم اإلثنــن املوافــق ‪1433/11/08‬ه ـ الســتالم نســخة‬\n‫مــن احلكــم لتقــدمي مالديهمــا مــن اعتــراض يف مدة أقصاهــا ثالثون يوم ًا‬\n‫وإال ســقط حقهمــا يف االعتــراض واكتســب احلكــم القطعيــة ففهمــا‬\n‫ذلــك وبــاهلل التوفيــق وأقفلــت اجللســة الســاعة الثانيــة ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ؛ ففــي يــوم اإلثنــن املوافــق ‪1434/03/23‬ه ـ‬\n\n\n                                                                                      ‫‪166‬‬\n\f      ‫افتتحــت اجللســة الســاعة العاشــرة وقــد وردتنــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية باخلطــاب رقــم ‪ 34223193‬يف‬\n      ‫‪1434/03/16‬ه ـ واملــزودة بالقــرار مــن الدائــرة األولــى ‪ -‬ق ‪ /‬أ برقــم‬\n      ‫‪ 3459598‬يف ‪1434/03/10‬ه ـ املتضمــن مــا نصــه ‪ ( :‬وبدراســة الصــك‬\n      ‫قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه‬ ‫وصــورة ضبطــه وأوراق املعاملــة ّ‬\n      ‫حـ ّـرر يف ‪ ، 1434/03/10‬واهلل ولــي التوفيــق ‪ .‬قاضــي اســتئناف ختمــه‬\n      ‫وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة) انتهــى‬\n      ‫نصــه وأقفلــت اجللســة الســاعة العاشــرة وخمــس دقائــق ‪ ،‬حـ ّـرر يف‬           ‫ّ‬\n                                                                      ‫‪1434/03/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد‪ :‬ففــي يــوم األحــد املوافــق ‪1434/05/05‬ه ـ‬\n      ‫وردتنــا املعاملــة مــن شــرطة محافظــة القطيــف مبوجــب خطابهــم رقــم‬\n      ‫‪ 4371/8/21‬يف ‪1434/4/27‬هـ يتضمن بعد املقدمة ما نصه‪( :‬وحيث‬\n      ‫انــه مت تطبيــق املــادة (‪ )230‬مــن نظــام املرافعــات الشــرعية بحــق الســجني‬\n      ‫املذكــور لــذا نبعــث لفضيلتكــم املذكــور بأمــل إجــراء اإليجــاب‬\n      ‫الشــرعي ويف حــال ارتأيتــم ســجن املذكــور تزويدنــا بكتــاب مســتقل‬\n      ‫يتضمــن األمــر بســجنه ومــدة الســجن ليتســنى لنــا علــى ضــوء ذلــك بعثــه‬\n      ‫للســجن العــام وإعــادة لنــا كامــل املعاملــة فــور االنتهــاء منهــا) انتهــى‬\n      ‫نــص احلاجــة منــه ‪ ،‬وقــد حضــر لدينــا الطرفــان ‪ ،‬وقــررا اصطالحهمــا‬\n      ‫علــى أن يكــون الدفــع وفــق مــا يلــي‪ )1( :‬أن يتــم دفــع املبلــغ علــى أقســاط‬\n      ‫شــهرية قيمــة كل قســط ثالثــة آالف ريـ(‪ )3000‬ــال ويكــون القســط‬\n      ‫األول بتاريــخ ‪2013/03/20‬م (‪ )2‬بقيــة األقســاط بتاريــخ ‪ 7‬مــن كل‬\n      ‫شــهر ميــادي هكــذا اصطلحــا ‪ ،‬وحيــث األمــر مــا ذكــر فقــد ثبــت‬\n      ‫لــدي اصطــاح الطرفــن علــى مــا ذكــر بعاليــه وألزمتهمــا بــه وأمــرت‬\n\n\n‫‪167‬‬\n\f‫بالتهميــش علــى الصــك مبضمــون ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/05/05‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد و آلــه‬\n‫وصحبــه أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى‬\n‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبحافظة القطيف برقــم ‪331812019‬‬\n‫وتاريــخ ‪1434/1/ 3‬ه ـ واملقيــدة لــدى احملكمــة برقــم ‪34223193‬‬\n‫وتاريــخ ‪1434/1/26‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلة القاضي‬\n‫باحملكمــة الشــيخ‪ ...../‬املسـ ّـجل برقــم‪ .....‬وتاريــخ ‪1433/11/20‬ه ـ‬\n‫اخلــاص بدعــوى‪ ...../‬وزوجتــه ضــد‪ ...../‬يف قضيــة حقوقيــة وقــد تضمــن‬\n‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه‬\n                             ‫حــرر يف ‪1434/3/10‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                          ‫‪168‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":161,"source_page_end":168,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0d7610b3265777968c25461b355d2ca5d376b4ca4599352efb35e74b052a9671","normalized_text_hash":"8881396662e5e3a0d7b9f042f5820fdb4894e804411c9f320d131d2aef395766","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p161-33458770"},{"id":"6142523f-e5f4-5aa9-af94-d5f984f527fa","document_type":"judgment","category":"judicial","subcategory":"general","title":"شركة مضاربة -طلب اعادة رأس املال -سماع الدعوى غيابي ا لتعذر تبليغ املدعى عليه -احلكم بشاهد عدل ومين -طلب مين االستظهار -الشريعة جاءت برفع الضرر -للحاكم والية على مال الغائب -يجوز احلكم على الغائب و املستتر و املمتنع -احلكم بدفع املبلغ املدعى به لقيام البينه -الغائب على حجته متى حضر .1مارواه ابن عباس رضي اهلل عنهما أن رسول اهلل ( قضى بيمن وشاهد ) رواه مسلم.","document_number":"33461365","case_number":"33606126","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة ففي هذا اليوم االثنني1433/11/1ه ويف متام الساعة الثامنة والنصف فتحت","circuit":"الدائرة احلقوقية السابعة مبوجب قرارهم ذي الرقم 33461365يف","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/21","year":"1434","subject":"شركة مضاربة -طلب اعادة رأس املال -سماع الدعوى غيابي ا لتعذر تبليغ املدعى عليه -احلكم بشاهد عدل ومين -طلب مين االستظهار -الشريعة جاءت برفع الضرر -للحاكم والية على مال الغائب -يجوز احلكم على الغائب و املستتر و املمتنع -احلكم بدفع املبلغ املدعى به لقيام البينه -الغائب على حجته متى حضر .1مارواه ابن عباس رضي اهلل عنهما أن رسول اهلل ( قضى بيمن وشاهد ) رواه مسلم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫تاريخه‪1434/11/21 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33461365 :‬‬\n                        ‫َر ْق ُم الدعوى‪33606126 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪33461365 :‬‬\n                        ‫تاريخه‪1434/11/21 :‬هـ‬\n\n\n       ‫شــركة مضاربــة ‪ -‬طلــب اعــادة رأس املــال ‪ -‬ســماع الدعــوى غيابي ـ ًا‬\n       ‫لتعــذر تبليــغ املدعــى عليــه ‪ -‬احلكــم بشــاهد عــدل وميــن ‪ -‬طلــب ميــن‬\n       ‫االســتظهار ‪ -‬الشــريعة جــاءت برفــع الضــرر ‪ -‬للحاكــم واليــة علــى‬\n       ‫مــال الغائــب ‪ -‬يجــوز احلكــم علــى الغائــب و املســتتر و املمتنــع ‪ -‬احلكــم‬\n       ‫بدفــع املبلــغ املدعــى بــه لقيــام البينــه ‪ -‬الغائــب علــى حجتــه متــى حضر‬\n\n\n\n\n       ‫‪ .1‬مــارواه ابــن عبــاس رضــي اهلل عنهمــا أن رســول اهلل ( قضــى بيمــن‬\n                                                              ‫وشــاهد ) رواه مســلم‪.‬‬\n                                                 ‫‪ .2‬حديث (( ال ضرر وال ضرار ))‬\n                                ‫‪ .3‬املادتان ‪ 13‬و ‪ 55‬من نظام املرافعات الشرعية‪.‬‬\n       ‫‪ .4‬للحاكــم واليــة علــى مــال الغائــب ‪ ،‬ويجــوز لــه احلكــم عليــه وعلــى‬\n       ‫املســتتر و املمتنــع ولــو كان يف البلــد ‪ ،‬كمــا صــرح بذلــك أهــل العلــم‬\n                                      ‫منهــم صاحــب املبــدع و الكشــاف وغيرهمــا ‪.‬‬\n\n\n\n\n       ‫دعــوى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم الــذي‬\n       ‫تعــذر تبليغــه باملوعــد وتقــرر ســماع الدعــوى غيابي ـ ًا ومضمــون الدعــوى‬\n       ‫ان املدعــي ســلم املدعــى عليــه مبلغ ـ ًا قــدره خمســون ألــف ريــال حيــث‬\n\n‫‪169‬‬\n\f‫اتفقا على إنشــاء مشــروع تربية دواجن شــراكة وراس املال من املدعي‬\n‫وعلــى املدعــى عليــه العمــل ومتابعــة املشــروع وأن املبلــغ الــذي مت تســليمه‬\n‫دفعــة مقدمــه ولكــن املدعــى عليــه لــم يقــم مبــا مت اإلتفــاق عليــه وانــه‬\n‫حصــل خــاف ومت االتفــاق علــى اعــادة راس املــال علــى دفعتــن االولــى‬\n‫قدرهــا خمســة وثالثــون الــف ريــال تســلم يف ‪1433/6/29‬ه ـ والباقــي‬\n‫يســلم يف ‪1433/7/29‬ه ـ ولكــن املدعــى عليــه لــم يلتــزم بتســليم املبالــغ‬\n‫يف املوعــد احملــدد وطلــب احلكــم بتســليم املبلــغ املدعــى بــه وقــدره‬\n‫خمســون الــف ريــال‪ ،‬احضــر املدعــي شــاهد ًا علــى صحــة دعــواه ومت‬\n‫تعديــل الشــاهد شــرعاً‪ ،‬حلــف املدعــي تكملــه لبينتــه ‪ -‬صــدر احلكــم‬\n‫بالــزام املدعــى عليــه بتســليم املدعــي املبلــغ املدعــى بــه وهــو علــى حجتــه‬\n‫اذا حضــر‪ ،‬مت تزويــد املدعــى عليــه بصــورة مــن الصــك‪ ،‬صــدر قــرار‬\n       ‫محكمــة االســتئناف مبكــة املكرمــة باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا‪ ...‬القاضــي باحملكمــة العامــة باملدينــة املنــورة ففــي هــذا اليــوم‬\n‫االثنني‪1433/11/1‬ه ـ ويف متــام الســاعة الثامنــة والنصــف فتحــت‬\n‫ـاء علــى املعاملــة املقيــدة يف هــذه احملكمــة برقــم‬   ‫اجللســة األولــى بنـ ً‬\n‫‪331822590‬يف ‪1433/10/16‬ه ـ واحملالــة إلينــا مــن قبــل فضيلــة‬\n‫الرئيــس برقــم ‪33606126‬يف ‪1433/10/16‬ه ـ مبوجبــه حضــر املواطن‬\n‫‪ ...‬يحمــل الهويــة الوطنيــة رقــم ‪ ......‬ولــم يحضــر املدعى عليه وال من ينوب‬\n‫عنــه هــذا وقــد وردنــا مــن قســم محضــري اخلصــوم يف هــذه احملكمــة‬\n‫مايفيــد علــى أنــه مت الذهــاب إلــى عنوانــه عــدة مــرات ولــم يجــدوا أحــد ًا‬\n\n                                                                                       ‫‪170‬‬\n\f      ‫وأنــه قــد مت تســليم التبليــغ إلــى عمــدة احلــي ولــم يــرد مايفيــد تبلغــه‬\n      ‫وعليــه فقــد أمــرت برفــع اجللســة إلــى يــوم األربعــاء ‪1433/11/17‬ه ـ‬\n      ‫الســاعة الثامنــة صباح ـ ًا هــذا ويف يــوم األربعــاء ‪1433/11/17‬ه ـ ويف‬\n      ‫متــام الســاعة الثامنــة والنصــف فتحــت اجللســة الثانيــة وفيهــا حضــر‬\n      ‫املدعــي ولــم يحضــر املدعــى عليــه وقــد جــرى محاولــة تبليغــه عــن طريــق‬\n      ‫عمــدة احلــي (حــي ‪ )........‬وقــد وردنــا إفــادة عمــدة احلــي شــرح ًا علــى‬\n      ‫ورقــة التبليــغ املؤرخــة يف ‪1433/11/1‬ه ـ واملتضمنــه انــه مت الذهــاب‬\n      ‫الــى منــزل املذكــور عــدة مــرات ولــم يجــده أحــد ًا يف املنــزل ولــم يتــم‬\n      ‫فتــح البــاب نهائي ـ ًا وعليــه قــررت ســماع الدعــوى عليــه غيابي ـ ًا وادعــى‬\n      ‫ا انــه بتاريــخ‬\n                     ‫املدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم قائـ ً‬\n      ‫‪1433/5/15‬ه ـ اتفقــت اتفاق ـ ًا مبدئي ـ ًا مــع املدعــى عليــه الغائــب عــن‬\n      ‫مجلــس احلكــم علــى أن نقــوم بإنشــاء مشــروع تربيــة دواجــن شــراكة‬\n      ‫بيننــا منــي رأس املــال ومنــه العمــل ومتابعــة املشــروع وســلمته مبلــغ وقــدره‬\n      ‫خمســون ألــف ريــال دفعــة مقدمــة علــى أن يقــوم املدعــى عليــه بعــد يومــن‬\n      ‫بكتابــة صيغــة عقــد الشــراكة الــذي بيننــا ويبــن فيــه نســبة األربــاح‬\n      ‫التــي بيننــا إال أن املدعــى عليــه لــم يأتنــي بعقــد وال بغيــره حتــى أول شــهر‬\n      ‫جمــاد اآلخــرة فذهبــت إليــه وقلــت لــه ملــا لــم تأتينــي بالعقــد حتــى نقيــم‬\n      ‫الشــراكة بيننــا فحصــل خــاف بيننــا علــى إثــره قــال لــي املدعــى عليــه‬\n      ‫أنــا أحتمــل املشــروع لوحــدي وأنــت مالــك إال رأس مالــك وســوف أعيــده‬\n      ‫لــك واتفقــت أنــا وإيــاه علــى إعــادة رأس مالــي املبلــغ املدعــى بــه وقــدره‬\n      ‫خمســون ألــف ريــال علــى دفعتــن الدفعــة األولــى قدرهــا خمســة وثالثــون‬\n      ‫ألــف ريــال يف ‪1433/6/29‬ه ـ والدفعــة الثانيــة قدرها خمســة عشــر ألف‬\n      ‫ريــال يف ‪1433/7/29‬ه ـ ولــم يلتــزم املدعــى عليــه بدفــع املبلــغ لــي بهــذه‬\n\n\n‫‪171‬‬\n\f‫التواريــخ ولــم يدفــع لــي حتــى تاريــخ هــذا اليــوم ريــا ًال واحــد ًا واملدعــى‬\n‫عليــه الغائــب قــد ماطلنــي كثيــر ًا يف دفــع هــذا املبلــغ وقــد تضــررت‬\n‫مــن مماطلتــه وتهربــه عــن دفــع هــذا املبلــغ لــي أطلــب إثبــات ذلــك وإلــزام‬\n‫املدعــى عليــه الغائــب عــن مجلــس احلكــم بدفــع املبلــغ املدعــى بــه وقــدره‬\n‫خمســون ألــف ريــال حــا ًال هــذه دعــواي ثــم جــرى منــا ســؤال املدعــي هــل‬\n‫ا نعــم لــدي بينــة علــى هــذه الدعــوى‬     ‫لديــه بينــة علــى دعــواه فأجــاب قائـ ً‬\n‫هــذا وقــد أحضــر معــه املواطــن يحمــل الهويــة الوطنيــة رقــم وطلــب ســماع‬\n‫ا أشــهد هلل تعالــى بأنــه قبــل‬    ‫مــا لديــه وبســؤاله عمــا لديــه شــهد قائ ـ ً‬\n‫حوالــي أربعــة أشــهر ونصــف يف شــهر جمــادى اآلخــرة طلــب منــي املدعــى‬\n‫عليــه أن آتــي إليــه يف منــزل املدعــي ‪........‬هــذا احلاضــر الكائــن يف حــي‬\n‫‪........‬فذهبــت إلــى منــزل املدعــي ووجــدت املدعــى عليــه عنــده وقــال لــي‬\n‫املدعــى عليــه باحلــرف الواحــد يــا ‪ ........‬اشــهد بــأن يف ذمتــي مبلــغ وقــدره‬\n‫خمســون ألــف ريــال لـ‪........‬أســدده لــه خــال شــهر نصف املبلــغ أو أكثره‬\n‫والباقــي خــال شــهرين مــن تاريــخ هــذا اليــوم ولكنــه لــم يــوف ثــم جــاء‬\n                                                      ‫إلــي املدعــى عليــه مــرة أخــرى‪.‬‬\n‫وطلــب منــي أن أشــفع لــه عنــد املدعــي لكــي يعطيــه مهلــة أخــرى‬\n‫لتســديد هــذا املبلــغ املدعــى بــه وقــدره خمســون ألــف ريــال فذهبــت إلــى‬\n‫املدعــي وطلبــت منــه أن يعطيــه مهلــة أخيــرة يف ‪1433/10/15‬ه ـ ولكــن‬\n‫لــم يســدده حتــى تاريــخ هــذا اليــوم ريــا ًال واحــد ًا هــذا مــا لــدي وبــه أشــهد‬\n‫هكــذا شــهد ثــم جــرى منــا ســؤال املدعــي عــن معدلــن لهــذا الشــاهد‬\n‫ا ســوف أحضــر املزكيــن يف اجللســة القادمــة هكــذا‬                    ‫فأجــاب قائ ـ ً‬\n‫ا‬\n‫أجــاب ثــم جــرى منــا ســؤال املدعــي هــل لديــه زيــادة بينــة فأجــاب قائـ ً‬\n‫نعــم ولكــن أطلــب إعطائــي مهلــة هكــذا أجــاب وعليــه فقــد أمــرت‬\n\n\n                                                                                             ‫‪172‬‬\n\f      ‫برفــع اجللســة إلــى يــوم األحــد ‪1433/11/21‬ه ـ الســاعة الثامنــة صباحـ ًا‬\n      ‫هــذا ويف يــوم األحــد ‪1433/11/21‬ه ـ ويف متــام الســاعة الثامنــة صباحـ ًا‬\n      ‫فتحــت اجللســة الثالثــة وفيهــا حضــر املدعــي ويرافقــه الشــاهد املدونــه‬\n      ‫هويتــه بعاليــه ســابق ًا ثــم جــرى منــا ســؤال املدعــي عــن املعدلــن لبينتــه‬\n      ‫ا نعــم لقــد أحضرتهــم هــذا وقــد احضــر معه‬       ‫املدونــه بعاليــه فأجــاب قائـ ً‬\n      ‫ال من املواطن ‪ .....‬يحمل الهوية الوطنية رقم ‪ .....‬واملواطن ‪ .....‬يحمل‬            ‫ك ً‬\n      ‫الهويــة الوطنيــة رقــم ‪ .....‬وبســؤالهما عمــا لديهما شــهدا قائلني نشــهد هلل‬\n      ‫تعالــى بــأن هــذا الشــاهد عــدل ثقــة مرضــي الشــهادة لنــا وعلينــا هكــذا‬\n      ‫ا‬ ‫شــهدا ثــم جــرى منــا ســؤال املدعــي هــل لديــه زيــادة بينــة فأجــاب قائـ ً‬\n      ‫ليــس لــدي زيــادة بينــة علــى هــذه الدعــوى هكــذا أجــاب ثــم جــرى منــا‬\n      ‫عــرض ميــن االســتظهار علــى املدعــي يف إثبــات دعــواه فاســتعد بآدائهــا‬\n      ‫وقــد جــرى منــا تخويفــه بــاهلل ســبحانه وتعالــى مــن اليمــن الغمــوس‬\n      ‫ا واهلل العظيــم‬   ‫فاســتعد بآدائهــا ثــم أذنــت لــه بــآداء اليمــن فحلــف قائ ـ ً‬\n      ‫الــذي ال الــه اال هــو احلــي القيــوم عالــم الغيــب والشــهادة فاطــر الســموات‬\n      ‫واالرض بــأن لــي يف ذمــة املدعــى عليــه الغائــب عــن مجلــس احلكــم ‪.....‬‬\n      ‫يحمــل الســجل املدنــي رقــم ‪ .....‬مبلغ ـ ًا وقــدره خمســون ألــف ريــال لــم‬\n      ‫يســلمني منهــا ريــا ًال واحــد ًا وأننــي أعطيتــه مهلــة أخيــرة يف تســديد هــذا‬\n      ‫املبلــغ بتاريــخ ‪1433/10/15‬ه ـ ولــم يســددني شــيئ ًا مــن هــذا املبلــغ واهلل‬\n      ‫ـاء علــى ماتقــدم مــن الدعــوى‬    ‫علــى مــا أقــول شــهيد هكــذا حلــف فبنـ ً‬\n      ‫واالطــاع علــى اوراق املعاملــة ونظــر ًا ملــا جــاء يف شــهادة الشــاهد املعدلــة‬\n      ‫شــرع ًا املتضمنــة ان املدعــى عليــه أقــر وأســتعد بدفــع املبلــغ املدعــى بــه‬\n      ‫وقــدره خمســون ألــف ريــال يف مهلــة أقصاهــا ‪1433/10/15‬ه ـ ولــم‬\n      ‫يســدد املدعــي شــيئا مــن هــذا املبلــغ حتــى تاريــخ هــذا اليــوم ومبــا أن‬\n\n\n‫‪173‬‬\n\f‫املدعــي قــد أدى ميــن االســتظهار املقويــة لبينتــه املدونــة بعاليــه وملــا روي‬\n‫عــن ابــن عبــاس رضــي اهلل عنــه ( ان رســول اهلل صلــى اهلل عليــه وســلم‬\n                                             ‫قضــى بيمــن وشــاهد ) رواه مســلم‬\n‫ومبــا أن املدعــى عليــه قــد تعــذر تبليغــه عــن طريــق محضــر اخلصــوم يف‬\n‫هــذه احملكمــة وعــن طريــق عمــدة احلــي ومبــا أن الشــريعة جــاءت برفــع‬\n‫الضــرر حلديــث ال ضــرر وال ضــرار ومبــا أن للحاكــم واليــة علــى مــال‬\n‫الغائــب ويجــوز لــه احلكــم عليــه وعلــى املســتتر واملمتنــع ولــو كان يف‬\n‫البلــد كمــا صــرح بذلــك أهــل العلــم ومنهــم صاحــب املبــدع والكشــاف‬\n‫وغيرهــم ونظــر ًا ملــا نصــت عليــه املادتــن (‪18‬و‪ )55‬مــن نظــام املرافعــات‬\n‫الشــرعية جلميــع مــا ذكــر فقــد ألزمــت املدعــى عليــه بدفــع مبلغـ ًا وقــدره‬\n‫خمســون ألــف ريــال حــا ًال للمدعــي هــذا مــا ظهــر لــي وبــه حكمــت هــذا‬\n‫وقــررت ببعــث نســخة مــن صــك احلكــم بعــد تســجيله للمدعــى عليــه‬\n‫لتبليغــه باحلكــم وأفهامــه بأنــه لــه مهلــة ثالثــن يوم ـ ًا مــن تاريــخ تبليغــه‬\n‫لتقــدمي الئحتــه االعتراضيــه فــإذا لــم يتقــدم بالئحتــه االعتراضيــة خــال‬\n‫هــذه املــدة فــإن حقــه يســقط يف تقــدمي االعتــراض ويكتســب احلكــم‬\n‫القطعيــة وهــذا احلكــم يعــد يف حــق املدعــى عليــه غيابيــا وهــو علــى‬\n‫حجتــه متــى ماحضــر وبــه اختتمــت اجللســة يف متــام الســاعة التاســعة‬\n‫إالربــع وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/11/21‬ه ـ‬\n\n\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي هــذا‬\n‫اليــوم الثالثــاء ‪1434/3/3‬ه ـ عــادت لنــا املعاملــة مــن محكمــة‬\n‫اإلســتئناف مبكــة املكرمــة مبوجــب خطابهــم ذي الرقــم ‪331822590‬‬\n‫يف ‪1434/1/25‬ه ـ وقــد جــرى تدقيــق احلكــم واملصادقــة عليــه مــن قبــل‬\n\n\n                                                                                         ‫‪174‬‬\n\f      ‫الدائــرة احلقوقيــة الســابعة مبوجــب قرارهــم ذي الرقــم ‪ 33461365‬يف‬\n      ‫‪1434/11/21‬ه ـ قاضــي اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫ختمــه وتوقيعــه ورئيــس الدائــرة ختمــه وتوقيعه وللمعلوميــة جرى حتريره‬\n      ‫حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر‬\n                                                                    ‫يف ‪1434/3/3‬هــ‪.‬‬\n      ‫احلمد هلل وحده‪ ،‬والصالة والسالم على من ال نبي بعده ‪ ،‬وبعد ‪ :‬ـ فقد‬\n      ‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــا ُع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 331822590‬وتاريــخ ‪25‬‬\n      ‫‪ 1434/1/‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ /‬القاضــي‬\n      ‫باحملكمــة العامــة باملدينــة املنــورة املســجل برقــم ‪ 33461365‬وتاريــخ‬\n      ‫‪1433/11/21‬ه ـ املتضمــن دعــوى‪ /‬ضــد‪ /‬وبدراســة الصــك وص ــورة‬\n      ‫ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم‪ .‬واهلل املوفــق وصل ــى اهلل عل ــى‬\n                                           ‫نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪175‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":169,"source_page_end":175,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"797e365d318e109c67aae44f102b0eecc3a7ca14514c26ad16ba7251ac9b9854","normalized_text_hash":"754da0e8b03d60ea46f6c2a0f4fa2ab987361916cdbd975b1d3f6318618ede07","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p169-33461365"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"04f3bc31-bd8c-535f-840c-7b8c4b7aaf80","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -عقد مضاربة -مطالبة بفسخ عقد املضاربة وإعادة رأس املال لعدم تسليم األرباح -حتديد ربح املضاربة بنسبة ثابتة من رأس املال غير جائز -فسخ العقد -عدم قبول الرجوع عن اإلقرار بحق آلدمي -مين اقوى املتداعين.","document_number":"3410654","case_number":"32595757","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة وبتكليف من فضيلته لي بالنظر يف هذه املعاملة احملالة إليه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/13","year":"1434","subject":"شراكة -عقد مضاربة -مطالبة بفسخ عقد املضاربة وإعادة رأس املال لعدم تسليم األرباح -حتديد ربح املضاربة بنسبة ثابتة من رأس املال غير جائز -فسخ العقد -عدم قبول الرجوع عن اإلقرار بحق آلدمي -مين اقوى املتداعين.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/1/13 :‬هـ َر ْق ُم‬\n                         ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3410654 :‬‬\n                              ‫الدعوى‪32595757 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 34246456‬تاريخه‪1434/6/20:‬هـ‬\n\n\n   ‫شــراكة ‪ -‬عقــد مضاربــة ‪ -‬مطالبــة بفســخ عقــد املضاربــة وإعــادة رأس‬\n   ‫املــال لعــدم تســليم األربــاح‪ -‬حتديــد ربــح املضاربــة بنســبة ثابتــة مــن‬\n   ‫رأس املــال غيــر جائــز‪ -‬فســخ العقــد‪ -‬عــدم قبــول الرجــوع عــن اإلقــرار‬\n                                     ‫بحــق آلدمــي ‪ -‬ميــن اقــوى املتداعيــن‪.‬‬\n\n\n\n\n   ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                               ‫علــى مــن أنكــر)‪.‬‬\n   ‫‪ -2‬قــرار مجمــع الفقــه اإلســامي املتضمــن مــا يلــي‪( :‬وقد وقــع اإلجماع‬\n   ‫مــن الفقهــاء علــى مــدى القــرون ويف جميــع املذاهــب بأنــه ال يجــوز‬\n   ‫حتديــد ربــح اإلســتثمار يف املضاربــة وســائر الشــركات مببلــغ مقطــوع‬\n                                             ‫أو نســبة مــن املبلــغ املســتثمر) ‪.‬‬\n   ‫‪ -3‬قــول ابــن قدامــة يف املغنــي (‪( :)96/5‬فأمــا حقــوق اآلدميــن وحقــوق‬\n   ‫اهلل التــي ال تــدرأ بالشــبهات كالــزكاة و الكفــارات فــا يقبــل رجوعــه‬\n                                            ‫عنهــا وال نعلــم يف هــذا خالفـ ًا) ‪.‬‬\n\n\n\n\n                                                                                     ‫‪118‬‬\n\f      ‫ادعــى وكيــل املدعــن بــأن املدعــى عليهــا اســتلمت مــن موكليــه مبالــغ‬\n      ‫ماليــة (محــددة يف دعــواه) للمضاربــة بهــا مقابــل ربــح معــن ومحــدد‬\n      ‫مــن رأس املــال؛ إال أن موكليــه ال يعلمــون أيــن صرفــت هــذه األمــوال‬\n      ‫وهــل متــت املضاربــة بهــا أم ال ولــم تســلمهم املدعــى عليهــا أي أربــاح‪،‬‬\n      ‫لــذا طلــب احلكــم عليهــا بإعــادة املبالــغ التــي اســتلمتها‪ ،‬أقــرت املدعــى‬\n      ‫عليهــا بوجــود تعامــل مالــي بينهــا وبــن املدعــن يفــوق املبلــغ املدعــى بــه‬\n      ‫وثبــوت جــزء مــن املبلــغ يف ذمتهــا ودفعــت بأنهــا ســلمتهم مبالــغ ماليــة‬\n      ‫إال أنهــا ال تعــرف حتديــد ًا مــا الــذي ســلمته لهــم مــن األربــاح ومــا الــذي‬\n      ‫أعادتــه مــن رأس املــال‪ ،‬طلبــت احملكمــة مــن املدعــى عليهــا إثبــات‬\n      ‫مــا دفعــت بــه فعجــزت عــن ذلــك ســوى جــزء مــن املبلــغ وافــق وكيــل‬\n      ‫املدعــن علــى خصمــه مــن املبلــغ املدعــى بــه كمــا أنهــا لــم تقبــل ميــن‬\n      ‫املدعــن علــى نفــي مــا دفعــت بــه‪ ،‬التعامــل اجلــاري بــن موكلــي املدعــي‬\n      ‫واملدعــى عليهــا تعامــل محــرم ألنــه مــن املقــرر شــرع ًا عــدم جــواز حتديــد‬\n      ‫ربــح االســتثمار يف املضاربــة بنســبة مــن رأس املــال‪ ،‬قضــت احملكمــة‬\n      ‫بإلــزام املدعــى عليهــا بإعــادة املبلــغ املدعــى بــه بعــد خصــم املبلــغ الــذي‬\n      ‫أثبتــت تســليمه للمدعــن ووافــق وكيلهــم علــى خصمــه‪ ،‬قنــع املدعــن‬\n      ‫باحلكــم وعارضــت عليــه املدعــى عليهــا‪ ،‬قــررت محكمــة االســتئناف‬\n                                              ‫باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫‪119‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ .....‬املــازم القضائــي لــدى فضيلــة الشــيخ ‪ .....‬مســاعد رئيــس احملكمــة‬\n‫العامــة ببريــدة وبتكليــف مــن فضيلتــه لــي بالنظــر يف هــذه املعاملــة‬\n‫احملالــة إليــه مــن فضيلــة الرئيس برقــم ‪ 32595757‬يف ‪1432/12/23‬هـ‬\n‫واملقيــدة باحملكمــة برقــم ‪ 321584817‬يف ‪1432/12/18‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافــق ‪1433/ 11/ 30‬ه ـ يف متــام احلاديــة عشــرة صباحــا‬\n‫فتحــت اجللســة األولــى لهــذه الدعــوى وفيهــا حضــر ‪ .....‬ســعودي اجلنســية‬\n‫حامــل الســجل املدنــي رقــم الســجل ي ‪ .....‬الوكيــل الشــرعي عــن ‪..... .....‬‬\n‫‪ ..... .....‬أوالد ‪ .....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫ببريدة ‪ 33429641‬يف ‪1433/11/28‬هـ وحضرت حلضوره‪ .....‬ســودانية‬\n‫اجلنســية مبوجــب اإلقامــة الصــادرة مــن بريــدة برقــم ‪ .....‬فقــال املدعــي‬\n‫وكالــة يف تقريــر دعــواه علــى املدعيــة ‪ : ...‬إن هــذه احلاضــرة اســتلمت‬\n‫مــن موكلــي مبالــغ ماليــة قدرهــا خمســمائة وثمانيــة وأربعــون ألــف ريــال‬\n‫علــى دفعــات للمضاربــة بهــا إال أن موكلــي ال يعلمــون أيــن صرفــت هــذه‬\n‫األموال وهل متت املضاربة بها أم ال وإذا ســئلت تغضب وتقول ســر املهنة‬\n‫ولــم تســلمهم املدعــى عليهــا أي أربــاح علمــا بــأن الربــح معــن ومحــدد‬\n‫مــن رأس املــال لــذا أطلــب احلكــم عليهــا بإعــادة املبالــغ التــي اســتلمتها‬\n‫هــذه دعــواي وبينتــي األوراق املكتوبــة بخــط يدهــا ‪ .‬وهــي مرفقــة يف‬\n‫املعاملــة وبســؤال املدعــى عليهــا عــن الدعــوى أجابــت‪ :‬مــا ذكــره املدعــي‬\n‫وكالــة يف دعــواه بعــض صحيــح وبعضــه غيــر صحيــح أمــا الصحيــح‬\n‫فهــو تعاملــي املالــي مــع موكليــه فصحيــح وكذلــك اخلــط املكتــوب يف‬\n\n                                                                                     ‫‪120‬‬\n\f      ‫األوراق املرفقــة وأمــا غيــر الصحيــح فهــو القيمــة املدعــى بهــا فالتعامــل‬\n      ‫املالــي أكثــر مــن املبلــغ املدعــى بــه وأصــل املضاربــة كان مببلــغ قــدره‬\n      ‫مائــة وعشــرة أالف ريــال ثــم تضاعــف بعــد ذلــك واختلطــت األوراق وال‬\n      ‫أعــرف بالضبــط الــذي ســلمته لهــم مــن قيمــة األربــاح ومــا الــذي أعدتــه‬\n      ‫مــن رأس املــال لكــن الــذي أذكــره أنــي ســلمتهم مــا مجموعــه أربعمائــة‬\n      ‫وتســعة وثالثــون ألفــا وخمســمائة ريــال ســعودي بعضهــا ســلمته نقـ ًـدا‬\n      ‫ألخــت املدعــي وكالــة ‪ ...‬وبعضهــا حوالــة بنكيــة ملــوكل املدعــي ‪.....‬‬\n      ‫هــذه إجابتــي وبســؤالها عمــا يف ذمتهــا مــن مبالــغ لــم تعدهــا ملوكلــي‬\n      ‫املدعــي أجابــت قائلــة يف ذمتــي لهــم مبلــغ قــدره مائتــان وســبعة عشــر ألف‬\n      ‫ريــال لــم أســددها أطلــب حتديــد موعــد جللســة قادمــة أحضــر فيهــا بينتــي‬\n      ‫هكــذا أجابــت ونظــرا النتهــاء وقــت اجللســة مت رفــع اجللســة ‪ .‬ويف يــوم‬\n      ‫األربعــاء ‪1433/12/1‬ه ـ فتحــت اجللســة متــام الســاعة التاســعة صباحــا‬\n      ‫وفيهــا حضــر الطرفــان وبســؤال املدعــى عليهــا عــن البينــة التــي وعــدت‬\n      ‫بإحضارهــا أجابــت قائلــة‪ :‬نظــرا لضيــق الوقــت لــم أمتكــن مــن طلبهــا‬\n      ‫مــن البنــك‪ .‬أطلــب حتديــد موعــد قــادم ألمتكــن مــن إحضارهــا‪ .‬وحيــث‬\n      ‫األمــر مــا ذكــر جــرى رفــع اجللســة إلــى يــوم االثنــن ‪1433/12/20‬ه ـ‬\n      ‫صباحــا وعليــه جــرى التوقيــع ‪ .‬ويف يــوم‬   ‫ً‬     ‫الســاعة الثامنــة والنصــف‬\n      ‫االثنــن ‪1433/12/20‬ه ـ فتحــت اجللســة الثالثــة وفيهــا حضــر املدعــي‬\n      ‫وكالــة ‪ .....‬وحضــرت أختــه ‪ .....‬وحضــر حلضورهمــا املدعــى عليهــا ‪.....‬‬\n      ‫و ‪ .....‬الوكيــل الشــرعي عــن املدعــى عليهــا مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة ببريــدة برقــم ‪ 48716‬يف ‪1433/9/19‬ه ـ‬\n      ‫وجــرى منــي ســؤال املدعــي وكالــة عــن بينتــه يف املبالــغ املتبقيــة حيــث‬\n      ‫إن بينتــه تثبــت اســتالم املدعــى عليهــا مبل ًغــا قــدره خمســمائة واثنــان‬\n\n\n‫‪121‬‬\n\f‫وعشــرون ألــف ريــال؟ فأجــاب قائــا‪ :‬هــذا املبلــغ الثابــت بهــذه األوراق‬\n‫وقــدره خمســمائة واثنــان وعشــرون ألــف ريــال هــو مــا أطالــب بــه‪ .‬وجــرى‬\n‫ســؤال املدعــى عليهــا عمــا وعــدت بــه مــن إحضــار البينــة؟ فقدمــت ورقــة‬\n‫مــن مطبوعــات بنــك ‪ ...‬وفيهــا حوالــة مــن ‪ .....‬إلــى حســاب‪ .....‬مببلــغ‬\n‫قــدره عشــرون ألــف ريــال وأحضــرت نســخة مــن احلكــم الصــادر مــن‬\n‫فضيلــة الشــيخ ‪ .....‬جتــاه احلــق العــام الصــادر مــن احملكمــة اجلزائيــة‬\n‫برقــم ‪ 6/107‬يف ‪1433/3/15‬ه ـ ضدهــا وفيــه إقــرار موكلــة املدعــي‬\n‫‪ .....‬باســتالم مبلــغ قــدره ثالثــة أالف ريــال‪ .‬وبســؤال املدعــي وكالــة‬\n‫عــن بينــة املدعــى عليهــا قــال ال مانــع لــدي مــن خصــم املبلــغ الــوارد يف‬\n‫بينتــه وقــدره ثالثــة وعشــرون ألــف ريــال هكــذا أجــاب‪ .‬وبســؤال املدعــى‬\n‫عليهــا هــل حضــر معهــا أحــد وقــت الســداد؟ فأجابــت قائلــة‪ :‬لــم يحضــر‬\n‫معــي أحــد وقــت الســداد‪ .‬وقــد جــرى منــي ســؤال املدعيــة أصالــة ‪:.....‬‬\n‫هــل ســلمت إليــك املدعــى عليهــا أي مبلــغ مــن املبالــغ املدعــى بهــا يف هــذه‬\n‫القضيــة ســوى مــا أحضــرت مــن بينــة؟ فأجابــت‪ :‬لــم تســلم لــي املدعــى‬\n‫عليهــا ‪ .....‬وال أحــد مــن طرفهــا أي مبلــغ‪ .‬فســألت املدعــى عليهــا ‪.....‬‬\n‫هــل تطلبــن ميــن املدعيــة أصالــة ‪ .....‬علــى نفــي اســتالم املبالــغ؟ فأجابــت‬\n‫قائلــة‪ :‬ال أطلــب ميينهــا ‪ .‬فبنــاء علــى مــا ســبق مــن ســماع الدعــوى واإلجابــة‬\n‫واالطــاع علــى أوراق املعاملــة وبينــة املدعــي وكالــة وإلقــرار املدعــى‬\n‫عليهــا بصحــة التعامــل وأن يف ذمتهــا املبلــغ املذكــور وقــدره خمســمائة‬\n‫واثنــان وعشــرون ألــف ريــال منــه مبلــغ قــدره مائتــان وســبعة عشــر ألــف‬\n‫ريــال لــم تســددها ولــم تســتثمرها وأمــا الباقــي وقــدره ثالثمائــة وواحــد‬\n‫وثالثــون ألــف ريــال فقــد ســددتها ولــم حتضــر مــا يثبــت ســدادها للمبلــغ‬\n‫املتبقــي إال مببلــغ قــدره ثالثــة وعشــرون ألــف ريــال وملصادقــة املدعــي‬\n\n\n                                                                                         ‫‪122‬‬\n\f      ‫وكالــة للســداد‪ .‬ولقــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى‬\n      ‫املدعــي واليمــن علــى مــن أنكــر) ولعــدم وجــود البينــة املثبتــة لســداد‬\n      ‫املبلــغ املتبقــي وقــدره ثالثمائــة وثمانيــة أالف ريــال ولرفــض املدعى عليها‬\n      ‫ميــن املدعيــة أصالــة ‪ .....‬علــى نفــي اســتالم املبالــغ املتبقيــة وملــا جــرى مني‬\n      ‫مــن االطــاع علــى احلكــم الصــادر مــن فضيلــة الشــيخ ‪ .....‬جتــاه احلــق‬\n      ‫العــام الصــادر مــن احملكمــة اجلزئيــة برقــم ‪ 6/107‬يف ‪1433/3/15‬ه ـ‬\n      ‫والــوارد فيــه مصادقــة املدعــى عليهــا علــى املبلــغ املذكــور ‪ .....‬وإقــرار‬\n      ‫موكلــة املدعــي ‪ .....‬باســتالم ثالثــة أالف ريــال‪ ،‬لهــذا كلــه وملــا جــاء‬\n      ‫يف قــرار مجلــس املجمــع الفقــه اإلســامي يف دورتــه الرابعــة عشــرة يف‬\n      ‫شــهر ذي القعــدة مــن عــام ‪1432‬ه ـ مــا يلــي‪ »:‬وقــد وقــع اإلجمــاع مــن‬\n      ‫الفقهــاء علــى مــدى القــرون‪ ،‬ويف جميــع املذاهــب‪ :‬بأنــه ال يجــوز حتديــد‬\n      ‫ربــح االســتثمار يف املضاربــة وســائر الشــركات مببلــغ مقطــوع‪ ،‬أو‬\n      ‫بنســبة مــن املبلــغ املســتثمر ‪-‬رأس املــال‪-‬؛ ألن يف ذلــك ضمانــا لألصــل‬\n      ‫وهــو مخالــف لألدلــة الشــرعية الصحيحــة ويــؤدي إلــى قطــع املشــاركة‬\n      ‫يف الربــح واخلســارة التــي هــي مقتضــى الشــركة واملضاربــة‪ ،‬وهــذا‬\n      ‫اإلجمــاع ثابــت مقــرر إذ لــم تنقــل أي مخالفــة لــه‪ ،‬ويف ذلــك يقــول ابــن‬\n      ‫قدامــة يف املغنــي «(‪ )34/3‬أجمــع مــن يحفــظ عنــه مــن أهــل العلــم علــى‬\n      ‫إبطــال القــراض (املضاربــة) إذا شــرط أحدهمــا أو كالهمــا لنفســه‬\n      ‫دراهــم معــدودة‪ ،‬واإلجمــاع دليــل قائــم بنفســه»أ‪.‬هـ وحيــث إن التعامــل‬\n      ‫اجلــاري بــن موكلــي املدعــي واملدعــى عليهــا تعامــل محــرم وهــو مضاربة‬\n      ‫بربــح محــدد مــن رأس املــال لهــذا كلــه فقــد حكمــت علــى املدعــى‬\n      ‫عليهــا ‪ ...‬بإعــادة املبلــغ املتبقــي وقــدره أربعمائــة وتســع وتســعون ألــف‬\n      ‫ريــال ســعودي وبعــرض احلكــم علــى املدعــي وكالــة ‪ .....‬وأختــه ‪.....‬‬\n\n\n‫‪123‬‬\n\f‫قــررا القناعــة والرضــا بــه وأمــا املدعــى عليهــا فقــررت االعتــراض علــى‬\n‫احلكــم وطلبــت رفعــة حملكمــة االســتئناف مبنطقــة القصيــم بالئحــة‬\n‫اعتراضيــة فأجيــب طلبهــا وأفهمــت بتعليمــات االســتئناف ففهمــت ذلــك‬\n‫وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                             ‫وصحبــه أجمعــن‪ .‬حــرر يف ‪1433/12/20‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫يــوم الســبت املوافــق‪1434/ 5/4‬ه ـ الســاعة التاســعة صباحــا فتحــت‬\n‫اجللســة و جــرى فيهــا االطــاع علــى املعاملــة الــواردة مــن محكمــة‬\n‫االســتئناف مبنطقــة القصيــم برقــم‪ 34780381‬وتاريــخ ‪4 / 15‬‬\n‫‪1434/‬ه ـ واملالحــظ عليهــا مــن قبــل أصحــاب الفضيلــة قضــاة الدائــرة‬\n‫احلقوقيــة الثانيــة بالقــرار رقــم ‪ 34185310‬وتاريــخ ‪ 1434/ 4 / 10‬ه ـ‬\n‫علــى الصــك الصــادر منــا برقــم ‪ 3410654‬يف ‪1434/1/13‬ه ـ و نــص‬\n‫احلاجــة منــه بعــد املقدمــة (لوحــظ مــا يلــي‪ :‬أوال‪ :‬لــم يذكــر فضيلتــه‬\n‫مســتنده علــى ثبــوت املبلــغ املدعــى بــه يف ذمــة املدعــى عليهــا ولعــل‬\n‫ذلــك اعترافهــا بــه عنــد محاكمتهــا يف احلــق العــام كمــا هــو موجــود‬\n‫يف القــرار املرفــق باملعاملــة فالبــد مــن تدوينــه وعرضــه علــى املدعــى‬\n‫ثانيــا‪ :‬ادعــت املدعــى عليهــا تســديد بعــض املبلــغ علــى دفعــات‬  ‫عليهــا‪ً .‬‬\n‫كمــا جــاء يف الئحتهــا االعتراضيــة وكمــا جــاء يف صــك احلكــم باحلــق‬\n‫العــام‪ ،‬ولــم ُي ْجـ ِـر فضيلتــه شــيئًا نحــو ذلــك‪ .‬فعلــى فضيلتــه مالحظــة مــا‬\n‫ذكــر‪ ،‬وإجــراء مــا يلــزم نحــوه‪ ،‬ثــم إعــادة املعاملــة إلكمــال الزمهــا‪.‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬قاضــي‬\n‫اســتئناف د‪ ..... .‬ختمــه و توقيعــه قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه‬\n‫رئيــس الدائــرة ‪ .....‬ختمــه وتوقيعــه) وعليــه أجيــب أصحــاب الفضيلــة‬\n\n\n                                                                                        ‫‪124‬‬\n\f      ‫‪-‬وفقهــم اهلل‪ -‬مبــا يلــي‪ :‬بخصــوص املالحظــة األولــى فمســتندي هــو مــا‬\n      ‫بينتــه يف تســبيب احلكــم وهــو مــا ورد يف إقرارهــا أثنــاء نظــر القضيــة‬\n      ‫بصحــة هــذا املبلــغ بقولهــا (وأمــا غيــر الصحيــح فهــو القيمــة املدعــى بهــا‬\n      ‫فالتعامــل املالــي أكثــر مــن املبلــغ املدعــى بــه) فهــي لــم تنفــي ثبــوت املبلــغ‬\n      ‫وأن التعامــل املالــي بينهمــا أكثــر مــن املبلــغ املدعــى بــه‪.‬‬‫إمنــا نفــت قــدره‪ّ ،‬‬\n      ‫وإجابــة لطلــب أصحــاب الفضيلــة فقــد حضــر الطرفــان املدعــي أصالــة‬\n      ‫ووكالــة واملدعــى عليهــا أصالــة ووكيلهــا‪ .....‬ومت ســؤال املدعــى عليهــا‬\n      ‫عــن إقرارهــا املــدون يف القــرار رقــم ‪ 6/107‬يف ‪1433/3/15‬ه ـ ونصــه‬\n      ‫(مــا ذكــره املدعــي العــام يف دعــواه ضــدي فصحيــح ومقــدار املبالــغ‬\n      ‫خمســمائة وثمانيــة وأربعــون ألــف ريــال ســددت منهــا مائتــن وثمانــون‬\n      ‫ألــف ومســتعدة بتســليم أصحــاب احلقــوق اخلاصــة حقوقهــم الباقيــة عنــد‬\n      ‫طلبهــا) فأجابــت قائلــة‪ :‬إن اإلقــرار املوجــود يف القــرار رقــم ‪6/107‬‬\n      ‫الصــادر مــن احملكمــة اجلزئيــة ببريــدة ضــدي غيــر صحيــح ألنــي أقــر‬\n      ‫بالتعامــل املالــي فقــط‪ .‬هكــذا أجابــت‪ .‬وبخصــوص املالحظــة الثانيــة‪:‬‬\n      ‫فقــد ادعــت املدعــى عليهــا ‪ .....‬ســداد بعــض املبالــغ بقولهــا (لكــن‬\n      ‫الــذي أذكــره أنــي ســلمتهم مــا مجموعــه أربعمائــة وتســعة وثالثــون‬\n      ‫ألفــا وخمســمائة ريــال ســعودي بعضهــا ســلمته نقـ ًـدا ألخــت املدعــي‬\n      ‫وكالــة ‪ ...‬وبعضهــا حوالــة بنكيــة ملــوكل املدعــي ‪ .....‬هــذه إجابتــي)‬\n      ‫وجــرى مناقشــتها عــن ذلــك علــى النحــو املبــن يف الصــك وإجابــة‬\n      ‫ألصحــاب الفضيلــة فقــد ســألت املدعــى عليهــا أصالــة عــن بينتهــا علــى‬\n      ‫ـاهدا علــى‬\n                ‫مــا ذكرتــه يف الالئحــة االعتراضيــة فقالــت‪ :‬أحضــرت شـ ً‬\n      ‫تســليم أخــت املدعــي وكالــة ‪ .....‬وهــو ب‪ .....‬ســوادني اجلنســية مبوجــب‬\n      ‫اإلقامــة الصــادرة مــن جــوازات بريــدة برقــم ‪ .....‬وبســؤاله عمــا لديــه مــن‬\n\n\n‫‪125‬‬\n\f‫شــهادة قــال أشــهد هلل تعالــى علــى ثــاث وقائــع األولــى‪ :‬أنــي ذهبــت‬\n‫باملدعــى عليهــا ‪ ...‬إلــى حــي الشــقة وكان مــع املدعــى عليهــا ‪ .....‬مبلــغ‬\n‫بعدهــا ثــم تســليمها للمدعــى عليهــا‬  ‫قــدره ســبعة وســتون ألــف ريــال قمــت ّ‬\n‫فنزلــت مــن ســيارتي ثــم ذهبــت إلــى ســيارة متوقفــة عنــد صــراف بنــك‬\n‫الريــاض فيهــا رجــل وامــرأة فنــزل منهــا الســائق وركبــت املدعــى عليهــا‬\n‫‪ .....‬ثــم نزلــت منهــا وعــادت إلــى ســيارتي فســألتها عــن تســليم املبلــغ‬\n‫فقالــت نعــم ســلمته‪ .‬هكــذا شــهد وبســؤاله هــل تعــرف نــوع الســيارة‬\n‫أو مــن فيهــا؟ أجــاب قائــا‪ :‬ال أذكــر نــوع الســيارة وال أعــرف مــن فيهــا‪.‬‬\n‫هكــذا أجــاب‪ .‬والواقعــة الثانيــة التــي أشــهد هلل تعالــى فيهــا أنــه يف يــوم‬\n‫ال أذكــر تاريخــه ســلمتني املدعــى عليهــا ‪ ..... .....‬ظرفــا مغلفــا وقالــت‬\n‫لــي هــذا الظــرف فيــه مبالــغ ماليــة ســلمها إلــى رجــل جالــس يف محــل ‪.....‬‬\n‫الواقــع قــرب إشــارة ‪ ...‬يف شــارع ‪ ...‬وال أعــرف قيمــة املبالــغ املاليــة وال‬\n‫موضوعهــا‪ .‬والواقعــة الثالثــة التــي أشــهد هلل تعالــى فيهــا أنــي ذهبــت مــع‬\n‫‪ .....‬الســاعة ‪ 12‬ليــا إلــى منــزل ‪ .....‬وكان معهــا مبلغــا ال أعــرف قــدره‬\n‫لتســليمه لهــم ثــم عنــد وصولنــا وقفــت مــع أبــي ‪ .....‬ودخلــت ‪ .....‬بيتــه ثــم‬\n‫خرجــت ولــم أر يف يدهــا أي مبلــغ‪ .‬هكــذا شــهد وبســؤال املدعــى عليهــا‬\n‫أصالــة هــل لديــك بينــة أخــرى أجابــت قائلــة‪ :‬إن املســتندات املرفقــة يف‬\n‫املعاملــة تثبــت اســتالم األربــاح‪ .‬وعنــدي شــاهد آخــر لــم يحضــر هــو الــذي‬\n‫ســلم ‪ .....‬مبالــغ ماليــة عبــارة عــن قيمــة ســيارة‪ .‬هكــذا أجابــت‪ .‬فســألت‬\n‫املدعــى عليهــا هــل مت تســليم مبالــغ ماليــة ألحــد غيــر ‪ ...‬يـ ًـدا بيــد؟ أجابــت‬\n‫قائلــة‪ :‬نعــم ســلمت أخــت املدعــي وكالــة ‪ ...... .....‬وليــس لــدي بينــة علــى‬\n‫تســليمهم وأطلــب ميينهــم‪ .‬وبطلــب اليمــن مــن ‪ .....‬حاملــة الســجل رقــم‬\n‫‪ .....‬واملعــرف بهــا مــن قبــل أخويهــا ‪ .....‬ســعودي بالســجل املدنــي رقــم ‪.....‬‬\n\n\n                                                                                           ‫‪126‬‬\n\f      ‫و‪ .....‬ســعودي بالســجل املدنــي رقــم ‪ .....‬واملدعــى عليهــا اســتعدت قائلــة‬\n      ‫واهلل الــذي ال إلــه إال هــو أنــي لــم اســتلم مــن هــذه احلاضــرة ‪ .....‬أي مبلــغ‬\n      ‫مالــي‪ .‬هكــذا حلفــت‪ .‬وبالســؤال عــن ‪ .....‬أفــاد املدعــي وكالــة بأنهــا‬\n      ‫ليســت مــن املدعــن ولــم نطالــب بنصيبهــا‪ .‬ثــم ســألتها هــل تطلبــن ميــن‬\n      ‫‪ ...‬فأجابــت قالــت ال أطلــب ميينهــا‪ .‬فبنــاء علــى مــا ســبق وألن اإلقــرار‬\n      ‫الصــادر مــن املدعــى عليهــا مــدون يف صــك مصــدق مــن اســتئناف منطقــة‬\n      ‫القصيــم والرجــوع عنــه ال يقبــل ألنــه إقــرار يف حــق اآلدميــن‪ .‬قــال ابــن‬\n      ‫قدامــة ‪-‬رحمــه اهلل‪ -‬يف املغنــي (‪« :)96/5‬فأمــا حقــوق اآلدميــن‪،‬‬\n      ‫وحقــوق اهلل التــي ال تــدرأ بالشــبهات‪-‬كالزكاة والكفــارات‪ -‬فــا‬\n      ‫يقبــل رجوعــه عنهــا وال نعلــم يف هــذا خالفــا»‪ .‬وأمــا الشــهادة فهــي غيــر‬\n      ‫موصلــة جلهــل الشــاهد بقــدر املبالــغ فضــا عــن كــون التســليم ملبلــغ لــم‬\n      ‫يــدع بــه‪ ،‬وأمــا الشــاهد الغائــب فشــهادته كمــا أفــادت املدعــى عليهــا‬\n      ‫ـاء علــى ذلــك فــا زلــت علــى مــا حكمــت بــه‬     ‫علــى أمــر لــم يــدع بــه‪ .‬فبنـ ً‬\n      ‫وبعــرض احلكــم علــى املدعــى عليهــا أجابــت أنهــا باقيــة علــى اعتراضهــا‬\n      ‫وأمــا املدعــي وكالــة فقــرر قناعتــه واهلل أعلــم وقــررت إعــادة املعاملــة‬\n      ‫ألصحــاب الفضيلــة قضــاة االســتئناف التخــاذ مــا يرونــه وصلــى اهلل علــى‬\n                                              ‫نبينــا محمــد حــرر يف ‪1434/ 5 / 4‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n      ‫ـاء‬\n      ‫هــذا اليــوم الســبت املوافــق ‪1434/8/6‬ه ـ فتحــت هــذه اجللســة بنـ ً‬\n      ‫علــى ورود املعاملــة املتعلقــة بدعــوى ‪ .....‬بالوكالــة عــن ‪..... ..... ..... .....‬‬\n      ‫‪ .....‬أوالد ‪ .....‬ضــد ‪ ..... .....‬ســودانية اجلنســية مــن محكمــة االســتئناف‬\n      ‫بالقصيــم مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم ‪34/1239478‬‬\n      ‫يف ‪1434/7/8‬ه ـ املرفــق بــه القــرار الصــادر مــن أصحــاب الفضيلــة‬\n\n\n‫‪127‬‬\n\f‫قضــاة الدائــرة الثانيــة لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n‫بالقصيــم رقــم ‪ 34246456‬يف ‪1434/6/20‬ه ـ املتضمــن املصادقــة علــى‬\n‫هــذا احلكــم وللبيــان جــرى تدوينــه وعليــه حصــل التوقيــع وصلــى اهلل‬\n       ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/8/6‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                ‫‪128‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":118,"source_page_end":128,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ccc35a32d4a17b36cc6d822a4ec30ec3e10ed6ba471bb4de3e993f0ecc050b4c","normalized_text_hash":"b5661ef2fc13f084a8bf462ae67f8f739119bb5f34a8d439f7dbcb8e67436c21","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p118-3410654"},{"id":"e2fad480-9af7-5696-bcc0-3484397cdef4","document_type":"judgment","category":"judicial","subcategory":"general","title":"شركة مضاربة -املطالبة باألرباح يف شركة مضاربة -دعوى خسارة شركة مضاربة -عدم ثبوت الربح يف شركة املضاربة - صرف النظر عن املطالبة بأرباح شركة املضاربة لعدم ثبوتها - املضارب مؤمتن واألمن يقبل قوله بيمنه- ( اتفاق أهل العلم أن املضارب مؤمتن ال ضمان عليه فيما يتلفه من املال من غير جناية فيه وال استهالك له وال تصحيح هذه سبيل األمانة وهذا سبيل االمناء) االستذكار البن عبد البر - 124/121","document_number":"34298408","case_number":"33185453","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/16","year":"1434","subject":"شركة مضاربة -املطالبة باألرباح يف شركة مضاربة -دعوى خسارة شركة مضاربة -عدم ثبوت الربح يف شركة املضاربة - صرف النظر عن املطالبة بأرباح شركة املضاربة لعدم ثبوتها - املضارب مؤمتن واألمن يقبل قوله بيمنه- ( اتفاق أهل العلم أن املضارب مؤمتن ال ضمان عليه فيما يتلفه من املال من غير جناية فيه وال استهالك له وال تصحيح هذه سبيل األمانة وهذا سبيل االمناء) االستذكار البن عبد البر - 124/121","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/16 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34298408 :‬‬\n                         ‫َر ْق ُم الدعوى‪33185453 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34343374‬تاريخه‪1434/10/28:‬هـ‬\n\n\n      ‫شــركة مضاربــة ‪ -‬املطالبــة باألربــاح يف شــركة مضاربــة ‪ -‬دعــوى‬\n      ‫خســارة شــركة مضاربــة ‪ -‬عــدم ثبــوت الربــح يف شــركة املضاربــة ‪-‬‬\n      ‫صــرف النظــر عــن املطالبــة بأربــاح شــركة املضاربــة لعــدم ثبوتهــا ‪-‬‬\n                               ‫املضــارب مؤمتــن واألمــن يقبــل قولــه بيمنــه‪-‬‬\n\n\n\n\n      ‫( اتفــاق أهــل العلــم أن املضــارب مؤمتــن ال ضمــان عليــه فيمــا يتلفــه مــن‬\n      ‫املــال مــن غيــر جنايــة فيــه وال اســتهالك لــه وال تصحيــح هــذه ســبيل‬\n      ‫األمانــة وهــذا ســبيل االمنــاء) االســتذكار البــن عبــد البــر ‪- 124/121‬‬\n         ‫بدايــة املجتهــد البــن رشــد ‪ - 178/2‬كشــاف القنــاع للبهوتــي ‪524/8‬‬\n\n\n\n\n      ‫دعــوى املدعــي وكالــة ضــد املدعــى عليــه ان موكلــه ســلم للمدعــى‬\n      ‫عليــه مبلغــا مــن املــال لغــرض املتاجــرة بــه وتقســيطه علــى النــاس واتفــق‬\n      ‫معــه علــى ان يكــون الربــح محــددا شــهريا وأن املدعــى عليــه لــم يلتــزم‬\n      ‫بتســليم موكلــه أي شــيء ممــا مت االتفــاق عليــه وطلــب الــزام املدعــى‬\n      ‫عليــه بتســليم االربــاح املتفــق عليهــا‪ ،‬اجــاب املدعــى عليــه باملصادقــة على‬\n      ‫الدعــوى وقــرر انــه اســتلم مــن املدعــي اصالــة واخوتــه مبلغــا مــن املــال وملــا‬\n      ‫علــم بفســاد هــذا العقــد فقــد اثبــت لهــم يف ذمتــه هــذا املبلغ الذى اســتلمه‬\n\n‫‪129‬‬\n\f‫مبوجــب صكــوك شــرعية‪ ،‬صــادق املدعــي وكالــة علــى اجابــة املدعــى‬\n‫عليــه وطالــب باألربــاح‪ ،‬اجــاب املدعــى عليــه بــأن الشــركة خســرت وال‬\n‫اربــاح فيهــا‪ ،‬قــرر املدعــي وكالــة أن الشــركة ربحــت حســب اخبــار‬\n‫املدعــى عليــه ملوكلــه ‪ -‬احضــر املدعــي وكالــة بينــة غيــر موصلــة تثبــت‬\n‫ربــح الشــركة افهــم ناظــر القضيــة املدعــي وكالــة بــأن لــه ميــن املدعــى‬\n‫عليــه علــى خســارة الشــركة فطلبهــا ‪،‬حلــف املدعــى عليــه علــى خســارة‬\n‫الشــركة‪ ،‬صــدر احلكــم بصــرف النظــر عــن مطالبــة املدعــى وكالــة‬\n‫باألربــاح‪ ،‬قــرر املدعــى وكالــة عــدم القناعــة‪ ،‬صــدق احلكــم مــن‬\n                                                         ‫محكمــة االســتئناف‬\n\n\n\n\n‫احلمد هلل وحده والصالة والســام على من ال نبي بعده وبعد‪ :‬ففي هذا‬\n‫اليــوم االثنــن املوافــق ‪1433/6/9‬ه ـ ويف متــام الســاعة الثامنــة والنصــف‬\n‫لــدي أنــا القاضــي‪ ...‬يف احملكمــة العامــة بالطائــف بنــاء علــى املعاملــة‬\n‫احملالــة مــن فضيلــة الرئيــس برقــم ‪ 33185453‬وتاريــخ ‪1433/3/14‬ه ـ‬\n‫واملقيــدة يف هــذه احملكمــة برقــم ‪ 33489250‬وتاريخ‪1433/3/14‬ه ـ‬\n‫افتتحــت اجللســة احملــددة لســماع دعــوى ‪ ...‬مينــي اجلنســية باإلقامــة رقــم‬\n‫‪ ...‬ضــد ‪ ...‬والتــي يطالبــه فيهــا مببلــغ وقــدره ســتة وســبعون ألــف وســتمائة‬\n‫ا‬‫ريــال ســعودي وهــي قــرض حســن وحيــث لــم يحضــر املدعــي وال وكيـ ً‬\n‫عنــه ولــم يقــدم عــذر ًا تقبلــه احملكمــة لــذا جــرى شــطب هــذه الدعــوى‬\n‫للمــرة األولــى بنــاء علــى املــادة الثالثــة واخلمســن مــن نظــام املرافعــات‬\n‫الشــرعية ولوائحــه التنفيذيــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                          ‫نبينــا محمــد حــرر يف ‪1433/6/9‬ه ـ‬\n\n                                                                                      ‫‪130‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n      ‫هــذا اليــوم االثنــن املوافــق ‪1433/10/23‬ه ـ ويف متــام الســاعة الثانيــة‬\n      ‫عشــرة ظهــر ًا لــدي أنــا‪ ...‬القاضــي يف احملكمــة العامــة بالطائــف بنــاء‬\n      ‫علــى املعاملــة احملالــة مــن فضيلــة الرئيــس برقــم ‪ 33185453‬وتاريــخ‬\n      ‫‪1433/3/14‬ه ـ واملقيــدة يف هــذه احملكمــة برقــم ‪ 33489250‬وتاريــخ‬\n      ‫‪1433/3/14‬ه ـ افتتحــت اجللســة وفيهــا حضــر‪ ...‬مينــي اجلنســية باإلقامــة‬\n      ‫رقــم ‪ .....‬ولــم يحضــر املدعــى عليــه وال وكيــل عنــه وباالطــاع علــى‬\n      ‫املعاملــة تبــن أن إفــادة محضــري اخلصــوم لــم تــرد رغــم مخاطبتهــم‬\n      ‫بخطابنــا رقــم ‪ 331272102‬وتاريــخ ‪1433/7/7‬ه ـ لتبليــغ املدعــى عليــه‬\n      ‫وحيــث اقتضــى النظــر إعــادة االستفســار عــن خطابنــا املشــار إليــه لــذا‬\n      ‫رفعــت اجللســة يف متــام الســاعة الثانيــة عشــر والربــع ظهــر ًا وحــددت‬\n      ‫موعــد ًا لنظــر هــذه القضيــة يف يــوم االثنــن املوافــق ‪1434/2/4‬ه ـ يف‬\n      ‫متــام الســاعة الثامنــة صباحـ ًا وأفهمــت املدعــي مبراجعــة قســم محضــري‬\n      ‫اخلصــوم يف هــذه احملكمــة لتزويدهــم مبــا يلــزم كــي يتمكنــوا مــن‬\n      ‫تبليــغ املدعــى عليــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                          ‫حــرر يف ‪1433/10/23‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n      ‫هــذا اليــوم االثنــن املوافــق ‪1434/2/4‬ه ـ ويف متــام الســاعة الثامنــة‬\n      ‫صباح ـ ًا افتتحــت اجللســة وفيهــا حضــر ‪ ...‬مينــي اجلنســية باإلقامــة‬\n      ‫رقــم‪ .....‬ولــم يحضــر املدعــى عليــه رغــم تبلغــه لشــخصه حســب إفــادة‬\n      ‫محضــري اخلصــوم رقــم ‪ 331880023‬يف ‪1433/10/24‬ه ـ وبســؤال‬\n      ‫املدعــي عــن إثبــات هويتــه أبــرز صــورة مــن إقامتــه وذكــر أن األصــل‬\n      ‫لــدى اجلــوازات بغــرض التجديــد هكــذا أفــاد ولعــدم االكتفــاء بذلــك‬\n\n\n‫‪131‬‬\n\f‫قــررت رفــع اجللســة يف متــام الســاعة الثامنــة والنصــف صباح ـ ًا وأفهمــت‬\n‫املدعــي بإحضــار أصــل إثباتاتــه الرســمية وبينتــه علــى دعــواه يف اجللســة‬\n‫القادمــة ففهــم ذلــك واســتعد بــه وعليــه حــددت للطرفــن موعــد ًا يف يــوم‬\n‫الثالثــاء املوافــق ‪1434/4/23‬ه ـ يف متــام الســاعة التاســعة والنصــف‬\n‫صباح ـ ًا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                 ‫‪1434/2/4‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n‫هــذا اليــوم الثالثــاء املوافــق ‪1434/4/23‬ه ـ ويف متــام الســاعة التاســعة‬\n‫والنصــف صباحـ ًا لــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة بالطائــف‬\n‫والقائــم بعمــل املكتــب القضائــي الســابع افتتحــت اجللســة وفيهــا حضــر‬\n‫‪ ...‬مينــي اجلنســية باإلقامــة رقــم‪ .....‬ولــم يحضــر املدعــى عليــه وال وكيــل‬\n‫عنــه ولــم يقــدم عــذر ًا تقبلــه احملكمــة رغــم تبلغــه لشــخصه حســب‬\n‫خطــاب محضــري اخلصــوم رقــم ‪ 331880023‬يف ‪1434/10/24‬ه ـ‬\n‫واخلطــاب رقــم ‪ 33587837‬يف ‪1433/3/28‬ه ـ وتبلــغ ابنه حســب خطاب‬\n‫محضــري اخلصــوم برقــم ‪ 34288166‬يف ‪1434/2/4‬ه ـ لــذا قــررت‬\n‫الســير يف نظــر هــذه القضيــة بنــاء علــى املــادة ‪ 1/55‬مــن نظــام املرافعــات‬\n‫الشــرعية ولوائحــه التنفيذيــة وبســؤال املدعــي عــن دعــواه ادعــى قائـاً‪:‬‬\n‫ادعــي علــى املدعــى عليــه بــأن لــي يف ذمتــه ســتة وســبعني ألفـ ًا وســتمائة‬\n‫ريــال لــم يدفــع لــي منهــا شــيء مقابــل قــرض حســن وذلــك مبوجــب ورقــة‬\n‫وصــل أمانــة و بينتــي هــم الشــهود املذكوريــن يف وصــل األمانــة هــذه‬\n‫دعــواي وبطلــب البينــة منــه قــال ســوف أحضرهــم يف اجللســة القادمــة‬\n‫وعليــه قــررت رفــع اجللســة يف متــام الســاعة العاشــرة وحــددت للطرفــن‬\n‫موعــدا يف يــوم األربعــاء املوافــق ‪1434/6/14‬ه ـ يف متام الســاعة العاشــرة‬\n\n\n                                                                                     ‫‪132‬‬\n\f      ‫صباح ـ ًا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                          ‫‪1434/4/23‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة العامــة بالطائــف‬\n      ‫والقائــم بعمــل املكتــب القضائــي الســابع ففــي هــذا اليــوم االربعــاء‬\n      ‫املوافق ‪1434/6/14‬هـ ويف متام الســاعة العاشــرة صباح ًا فتحت اجللســة‬\n      ‫وفيهــا حضــر املدعــي املنــوه عــن صفتــه وهويتــه يف اجللســات املاضيــة‬\n      ‫وحضــر حلضــوره املدعــى عليــه ‪ ...‬نيجيــري اجلنســية مبوجــب رخصــة‬\n      ‫اإلقامــة رقــم الصــادره مــن الطائــف وبســؤال املدعــي وكالــة عــن حتريــر‬\n      ‫ا ســبق ان اقتــرض املدعــى عليــه مــن موكلــي مبلغ ـ ًا‬       ‫دعــواه اجــاب قائ ـ ً‬\n      ‫مــن املــال وقــدره ســتة وســبعون ألفـ ًا وســتمائة ريــال يف ‪1432/11/30‬ه ـ‬\n      ‫وهــي قــرض حســن يســدد املبلــغ متــى مــا طلــب منــه مــن قبــل موكلــي‬\n      ‫وحتــى اآلن لــم يســدد أي شــيء أطلــب ســؤاله واحلكــم عليــه بســداد‬\n      ‫املبلــغ حــا ًال ملوكلــي وبســؤال املدعــى عليــه عــن دعــوى املدعــي وكالــة‬\n      ‫ا مــا ذكــره املدعــي وكالــة يف دعــواه غيــر صحيــح جملــة‬            ‫أجــاب قائ ـ ً‬\n      ‫ا فأنــا لــم أقتــرض مــن املدعــى عليــه بــل وال أعرفــه وهــذا‬            ‫وتفصي ـ ً‬\n      ‫املبلــغ الــذي يدعــى بــه هــو بســبب شــراكه بيننــا حيــث أحضــر املبلــغ‬\n      ‫لــي بقصــد املتأجــرة باملبلــغ الــذي أحضــروه وقــدرة مائــة وخمســون ألــف‬\n      ‫ريــال وقــد خســرت هــذه الشــركة وقــد اثبــت حقهــم بصــك شــرعي مــن‬\n      ‫املكتــب القضائــي العاشــر واملكتــب القضائــي الســابع عشــر وقــد‬\n      ‫حكــم علــي مببلــغ وقــدره مائــة وخمســون ألــف ريــال واملبلــغ الــذي دفعــه‬\n      ‫ومــن معــه عــن طريــق املذكــور أعــاه وهــذا املبلــغ الــذي يدعــي بــه هــو‬\n      ‫األربــاح التــي حســبوها وحقيقــة األمــر أن الشــركة قــد خســرت فليــس‬\n      ‫يف ذمتــي للمدعــي مــن هــذا املبلــغ املدعــي بــه شــيئ ًا هــذه أجابتــي ولضيــق‬\n\n\n‫‪133‬‬\n\f‫الوقــت رفعــت اجللســة إلــى يــوم االثنــن املوافــق ‪1434/8/15‬ه ـ الســاعة‬\n‫التاســعة والنصــف صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/14‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n‫هــذا اليــوم االثنــن املوافــق ‪1434/8/15‬ه ـ ويف متــام الســاعة التاســعة‬\n‫والنصــف صباح ـ ًا لــدي أنــا القاضــي يف احملكمــة العامــة بالطائــف‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة مينــي جلنســية باإلقامــة‬\n‫رقــم بالوكالــة عــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بالطائــف رقــم ‪ 34504686‬وتاريــخ ‪1434/4/23‬ه ـ وحضــر‬\n‫حلضــوره املدعــي عليــه نيجيــري اجلنســية مبوجــب اإلقامــة رقــم وبتــاوة‬\n‫مــا مت ضبطــه ســابق ًا صــادق عليــه الطرفــان وبســؤال املدعــي عــن دعــواه‬\n‫ا أننــي ادعــي علــى هــذا احلاضــر معــي حيــث أنــه بتاريــخ‬    ‫أجــاب قائ ـ ً‬\n‫‪1432/11/30‬ه ـ دفــع موكلــي للحاضــر معــي مبلــغ وقــدره خمســون‬\n‫ألــف ريــال لغــرض املتاجــرة بهــا وتقســيطها علــى النــاس واتفقــت معــه‬\n‫علــى أن يكــون الربــح مبلغ ـ ًا قــدره ســتة وعشــرون ألــف وســتمائة‬\n‫ريــال منجم ـ ًا علــى أشــهر بواقــع كل شــهر مبلغ ـ ًا وقــدره ســبعة آالف‬\n‫وخمســمائة ريــال إال إن هــذا املدعــى عليــه لــم يقــم بســداد أي شــيء‬\n‫منهــا أطلــب إلزامــه بســداد هــذا املبلــغ ملوكلــي حــا ًال وإنــي أســأله‬\n‫ا مــا ذكــره‬  ‫اجلــواب هــذه دعــواي وبســؤال املدعــى عليــه أجــاب قائ ـ ً‬\n‫ا إال إنــي قــد اســتلمت‬  ‫املدعــي وكالــة فكلــه صحيــح جملــة وتفصي ـ ً‬\n‫مــن املدعــي وكالــة وأخوتــه مبلــغ إجمالــي قــدره مائــة وخمســون ألــف‬\n‫ريــال وملــا علمــت بفســاد هــذا العقــد أثبــت لهــم يف ذمتــي املائــة واخلمســن‬\n‫ألــف ريــال مبوجــب صكــوك شــرعية هــذه إجابتي وعليهــا أوقع وبعرض‬\n\n\n                                                                                       ‫‪134‬‬\n\f      ‫ذلــك علــى املدعــي وكالــة قــرر بقولــه ماذكــره فصحيــح وموكلــي‬\n      ‫وزوجتــي ســبق أن صــدرت صكــوك بهــذه املبالــغ لــدي احملكمــة وعليــه‬\n      ‫إنــي أطالبــه بأربــاح هــذه الشــركة وقدرهــا ســتة وعشــرون ألــف ريــال‬\n      ‫يدفعهــا ملوكلــي حــا ًال هــذه دعــواي وبســؤال املدعــي عليــه عــن أربــاح‬\n      ‫هــذه الشــركة قــال إن هــذه الشــركة قــد خســرت وال أربــاح فيهــا‬\n      ‫وأنــا غيــر مســتعد بدفــع أي شــيء للمدعــي هكــذا قــرر وبعرضــه علــى‬\n      ‫ا إن هــذه الشــركة فيهــا أربــاح بحســب مــا‬    ‫املدعــي وكالــة أجــاب قائـ ً‬\n      ‫أخبرنــا بــه املدعــي عليــه هكــذا قــرر وعليــه طلبــت مــن املدعــي وكالــة‬\n      ‫البينــة علــى وجــود أربــاح فأبــرز لنــا ورقــة محــررة تتضمــن جــدول ســداد‬\n      ‫وأقســاط الســيارات لألســتاذ مبلــغ الشــراء للســيارات خمســون ألــف‬\n      ‫ريــال فقــط ال غيــر تســدد بالتقســيط مبلــغ قــدره ســبعة آالف ريــال علــى‬\n      ‫النحــو التالــي يف ‪1432/11/30‬ه ـ مبلــغ ســبعة آالف ريــال ويف تاريــخ‬\n      ‫‪1432/12/30‬ه ـ مبلــغ ســبعة آالف ريــال ويف تاريــخ ‪1433/1/30‬ه ـ‬\n      ‫مبلــغ ســبعة آالف ريــال يف تاريــخ ‪1433/2/30‬ه ـ مبلــغ ســبعة آالف‬\n      ‫ريــال يف تاريــخ ‪1433/2/30‬ه ـ مبلــغ ســبعة آالف ريــال يف تاريــخ‬\n      ‫‪1433/3/30‬ه ـ مبلــغ ســبعة آالف ريــال يف تاريــخ ‪1433/4/30‬ه ـ مبلــغ‬\n      ‫ســبعة آالف ريــال يف تاريــخ ‪1433/5/30‬ه ـ مبلــغ ســبعة آالف ريــال يف‬\n      ‫تاريــخ ‪1433/6/30‬ه ـ مبلــغ ســبعة آالف ريــال يف تاريــخ ‪1433/7/30‬ه ـ‬\n      ‫مبلــغ ســبعة آالف ريــال يف تاريــخ ‪1433/8/30‬ه ـ وبســؤاله هــل لديــك‬\n      ‫ا ليــس لــدي مزيــد بينــة هكــذا قــرر وعليــه‬      ‫مزيــد بينــة؟ اجــاب قائ ـ ً‬\n      ‫أفهمتــه إن لــه ميــن املدعــي عليــه فطلبهــا وبعرضــه علــى املدعــي عليــه‬\n      ‫ا واهلل العظيــم الــذي ال الــه‬\n                                     ‫قــال ال مانــع لــدي واســتعد بهــا وحلــف قائ ـ ً‬\n      ‫إال هــو الــذي يعلــم الســر والعالنيــة ويعلــم اجلهــر ومــا يخفــى إن الشــركة‬\n\n\n‫‪135‬‬\n\f‫املوصوفــة يف دعــوى املدعــي قــد خســرت ولــم آخــذ منهــا أي أربــاح وحتــى‬\n‫ـاء‬\n‫بعــض رأس املــال قــد خســرته واهلل واهلل واهلل هكــذا حلــف فبنـ ً‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه حلــف‬\n‫اليمــن التــي طلبــت منــه ومبــا أن حكــم القــراض الفاســد كصحيحــة‬\n‫مــن حيــث الضمــان وعدمــه ومبــا أن املدعــي وكالــة أقــر باحلكــم لــه‬\n‫بــرأس املــال وانحصــرت دعــواه يف املطالبــة باألربــاح والتفــاق أهــل العلــم‬\n‫أن املضــارب مؤمتــن ال ضمــان عليــه يف مــا يتلفــه مــن املــال مــن غيــر جنايــة‬\n‫فيــه وال اســتهالك لــه وال تصحيــح هــذه ســبيل األمانــة وهــذا ســبيل‬\n‫األمنــاء حــكاه بــن عبدالبــر يف االســتذكار ‪ 124/121‬وابــن رشــد يف‬\n‫بدايــة املجتهــد ‪ 178/2‬والبهوتــي يف كشــاف القنــاع ‪ 524/8‬ولعجــز‬\n‫املدعــي وكالــة عــن إثبــات مــا ادعــي بــه مــن ربــح الشــركة لذلــك كلــه‬\n‫فقــد صرفــت النظــر عــن دعــوي املدعــي هــذا مــا ظهــر لــي وبــه حكمــت‬\n‫واهلل تعالــي أعلــم وبعــرض ذلــك علــى املدعــي وكالــة قــرر اعتراضــه‬\n‫علــى احلكــم وطلــب اســتئناف احلكــم بــدون الئحــة وعليــه قــررت بعــث‬\n‫كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪ 1434/8/15‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بالطائف‬\n‫فقــد أعيــدت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫بخطــاب فضيلــة رئيســها برقــم ‪ 33489250‬يف ‪1434/11/3‬ه ـ واملرفــق‬\n‫معهــا قــرار الدائــرة احلقوقيــة األولــى بالقــرار الصــادر برقــم ‪34343374‬‬\n‫يف ‪1434/10/28‬ه ـ املــدون علــى ظهــر الصــك واملتضمــن مــا نصــه‬\n‫بعــد املقدمــة ( وبدراســة احلكــم وصــورة ضبطــه تقــرر باألكثريــة‬\n‫املوافقــة علــى احلكــم واهلل املوفــق قاضــي اســتئناف لــي وجهــة نظــر‬\n\n\n                                                                                        ‫‪136‬‬\n\f      ‫ختمــه وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه‬\n      ‫وتوقيعــه ) أ‪.‬ه ـ وعليــه فقــد أمــرت بإحلاقــه علــى ســجله وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                  ‫‪ 1434/11/12‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪ 33489250‬وتاريــخ‬\n      ‫‪1434/10/19‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪...../‬‬\n      ‫القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد ‪34298408‬‬\n      ‫وتاريــخ ‪ 1434/8/16‬هـ ـ واملتضمــن دعــوى‪ ...../‬مينــي اجلنســية ضــد‪...../‬‬\n      ‫واحملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه‬\n      ‫تقــرر باألكثريــة املوافقــة علــى احلكــم واهلل املوفق‪.‬وصلــى اهلل علــى‬\n                                            ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪137‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":129,"source_page_end":137,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f88d43166c5fa1a4b9c5dce4e615a333726c9ebcc347553df318fe54383b7174","normalized_text_hash":"a53c39f21e3475317afc3abf387fb4fe16adcb32b27bdf642e2c81dd8a98d0f9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p129-34298408"},{"id":"29053c42-890e-521e-a956-475146ff71b0","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -عقد مضاربة -تدافع اختصاص حسمة املجلس األعلى للقضاء -صور فواتير شراء وعدم وجود أصولها -مطالبة بإعادة رأس املال مع األرباح -عجز عن إثبات الدفع بعدم االستحقاق -نكول املدعى عليه عن اليمن -ثبوت الدعوى مع التنازل عن","document_number":"346305","case_number":"33258094","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/7","year":"1434","subject":"شراكة -عقد مضاربة -تدافع اختصاص حسمة املجلس األعلى للقضاء -صور فواتير شراء وعدم وجود أصولها -مطالبة بإعادة رأس املال مع األرباح -عجز عن إثبات الدفع بعدم االستحقاق -نكول املدعى عليه عن اليمن -ثبوت الدعوى مع التنازل عن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫تاريخه‪1434/1/7 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪346305 :‬‬\n                   ‫َر ْق ُم الدعوى‪33258094 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34178269‬تاريخه‪1434/4/3:‬هـ‬\n\n\n‫شــراكة ‪ -‬عقــد مضاربــة ‪ -‬تدافــع اختصــاص حســمة املجلــس األعلــى‬\n‫للقضــاء ‪ -‬صــور فواتيــر شــراء وعــدم وجــود أصولهــا ‪ -‬مطالبــة بإعــادة‬\n‫رأس املــال مــع األربــاح ‪ -‬عجــز عــن إثبــات الدفــع بعــدم االســتحقاق‬\n‫‪ -‬نكــول املدعــى عليــه عــن اليمــن ‪ -‬ثبــوت الدعــوى مــع التنــازل عــن‬\n                                                                   ‫األربــاح‪.‬‬\n\n\n\n\n‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                           ‫علــى مــن أنكــر)‪.‬‬\n‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬علــى اليــد مــا أخــذت حتــى‬\n                                                                     ‫تؤديــه)‪.‬‬\n\n\n\n\n‫ادعــى وكيــل املدعــي أن موكلــه اتفــق مــع املدعــى عليــه علــى الدخــول‬\n‫معــه يف مســاهمة لغــرض املتاجــرة بأجهــزة حاســب آلــي وســلمه نصيبــه‬\n‫مــن رأس املــال علــى أن تصــرف األربــاح يف نهايــة كل شــهر دون أن‬\n‫يتفقــا علــى نســبة محــددة مــن الربــح‪ ،‬إال أن املدعــى عليــه لــم يقــم بإعــادة‬\n‫رأس املــال واألربــاح ملوكلــه‪ ،‬لــذا طلــب إلــزام املدعــى عليــه بدفــع رأس‬\n‫املــال مــع األربــاح ملوكلــه‪ ،‬أنكــر املدعــى عليــه مــا جــاء يف الدعــوى‬\n\n                                                                                        ‫‪138‬‬\n\f      ‫ا ســوى أنــه اســتلم مــن املدعــي جــزء مــن املبلــغ املدعــى‬   ‫جملــة وتفصي ـ ً‬\n      ‫بــه نظيــر قيمــة أجهــزة حاســب آلــي اشــتراها منــه‪ ،‬طلبــت احملكمــة‬\n      ‫مــن املدعــى عليــه إثبــات مــا دفــع بــه فقــدم صــور ًا لفواتيــر تتضمــن بيــع‬\n      ‫أجهــزة للمدعــي وعجــز عــن إحضــار أصولهــا وقــرر عــدم رغبتــه يف ميــن‬\n      ‫خصمــه علــى نفــي دفعــه‪ ،‬طلبــت احملكمــة مــن املدعــي البينــة علــى‬\n      ‫باقــي املبلــغ الــذي لــم يقــر املدعــى عليــه باســتالمه فقــرر أنــه ال بينــة‬\n      ‫لديــه وطلــب ميــن املدعــى عليــه علــى نفيــه فنــكل عــن أدائهــا وامتنــع عــن‬\n      ‫بذلهــا رغــم إنــذاره بأنــه ســيقضى عليــه بالنكــول‪ ،‬املدعــي قــرر تنازلــه‬\n      ‫عــن املطالبــة باألربــاح‪ ،‬قضــت احملكمــة بثبــوت تنــازل املدعــي عــن‬\n      ‫املطالبــة باألربــاح وحكمــت علــى املدعــى عليــه بدفــع املبلــغ املدعــى بــه‬\n      ‫بعــد خصــم األربــاح للمدعــي وأفهمــت املدعــى عليــه أن لــه ميــن املدعــي‬\n      ‫أصالــة متــى مــا طلبهــا‪ ،‬قنــع املدعــي باحلكــم وعــارض املدعــى عليــه‪،‬‬\n                             ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة اخلــرج بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة باخلــرج ‪ /‬املســاعد برقــم ‪ 33258094‬وتاريــخ‬\n      ‫‪1433/04/13‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33694420‬وتاريــخ‬\n      ‫‪ 1433/04/13‬ه ـ ففــي يــوم الســبت املوافــق ‪1433/05/29‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 30‬صباحـ ًا بنــاء علــى خطــاب معالي رئيس املجلس‬\n      ‫األعلــى للقضــاء رقــم ‪ 2648‬وتاريــخ ‪1433/3/6‬ه ـ واملرفــق بــه قــرار جلنــة‬\n      ‫الفصــل يف تنــازع االختصــاص رقــم ‪/17‬ت وتاريــخ ‪1433/2/22‬ه ـ‬\n\n‫‪139‬‬\n\f‫واملتضمــن أن القضيــة مــن اختصــاص القضــاء العــام‪ ،‬وفيهــا حضــر ‪.....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬الوكيــل عــن ‪.....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وذلــك مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة عــدل محافظــة اخلــرج برقــم‬\n‫‪ 310503014356‬وتاريــخ ‪1427/2/26‬ه ـ واملجعــول فيهــا للوكيــل حق‬\n‫املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح وادعــى علــى احلاضــر‬\n‫معــه يف املجلــس الشــرعي ‪ .....‬فلســطيني اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم ‪ .....‬قائــا يف حتريــر دعــواه عليــه لقــد قــام موكلــي بتاريــخ‬\n‫‪2005/3/24‬م باالتفــاق مــع املدعــى عليــه هــذا احلاضــر علــى الدخــول‬\n‫معــه يف مســاهمة لغــرض املتاجــرة بأجهــزة احلاســب اآللــي‪ ،‬علــى أن‬\n‫تصــرف األربــاح يف نهايــة كل شــهر ميــادي ولــم يتفقــا علــى نســبة‬\n‫محــددة مــن الربــح‪ ،‬وكانــت قيمــة الســهم الواحــد عشــرة آالف‬\n‫ريالــ‪ 10000‬فســلمه موكلــي مجموعــة مــن املبالــغ علــى فتــرات متفاوتــة‬\n‫بلــغ مجموعهــا مليونــان وثمامنائــة وألــف وســبعمائة وعشــرين ريــاال‬\n‫‪ 2801720‬وقــد ربحــت هــذه املســاهمة مبلغــا قــدره ثمانيــة وخمســون‬\n‫ألفــا ومائتــان وثمانــون ريــاال‪ 58280‬وعليــه فيكــون مجمــوع املبلــغ قــدره‬\n‫مليونــان وثمامنائــة وســتون ألــف ريالــ‪ 2860000‬وقــد مضــت مــدة طويلــة‬\n‫ولــم يقــم املدعــى عليــه بإعــادة رأس املــال واألربــاح ملوكلــي‪ ،‬وقــد أقــام‬\n‫موكلــي عليــه دعــوى لــدى فضيلــة ســلفكم وصــدر بهــا الصــك رقــم‬\n‫‪ 48/4/99‬وتاريــخ ‪1427/12/4‬ه ـ املتضمــن إلزامــه بســداد مبلــغ قــدره‬\n‫مليونــان واثنــان وثالثــون ألفــا وثمانــون ريــاال ثــم رجــع فضيلتــه عــن‬\n‫احلكــم لعــدم االختصــاص وصــدق احلكــم مــن التمييز ثــم أقام موكلي‬\n‫دعــوى لــدى ديــوان املظالــم وصــدر لــه حكــم مــن الديــوان باملبلــغ‬\n\n\n                                                                                      ‫‪140‬‬\n\f      ‫الســابق‪ ،‬وذلــك مبوجــب القــرار رقــم ‪/193‬د‪/‬جت لعــام ‪1429‬ه ـ ثــم نقــض‬\n      ‫مــن التدقيــق ثــم صــدر احلكــم رقــم ‪/157‬د‪/‬جت لعــام ‪1427‬ه ـ املتضمــن‬\n      ‫عــدم اختصــاص الديــوان والئيــا يف هــذه القضيــة ثــم رفعــت للجنــة‬\n      ‫الفصل يف تنازع االختصاص والتي رأت أن هذه القضية من اختصاص‬\n      ‫احملكمــة لــذا أطلــب إلــزام املدعــى عليــه هــذا احلاضــر بدفــع رأس املــال‬\n      ‫مــع األربــاح وقــدره مليونــان وثمامنائــة وســتون ألــف ريالــ‪ 2860000‬هــذه‬\n      ‫دعــواي وأســأل املدعــى عليــه احلاضــر اجلــواب وبســؤال املدعــى عليــه عــن‬\n      ‫دعــوى املدعــي وكالــة أجــاب قائــا إن مــا ذكــره املدعــي وكالــة يف‬\n      ‫دعــواه مــن أن موكلــه قــد اتفــق معــي علــى الدخــول يف مســاهمة بتاريــخ‬\n      ‫‪2005/3/24‬م بغــرض املتاجــرة يف أجهــزة احلاســب اآللــي وأن األربــاح‬\n      ‫غيــر محــددة النســبة‪ ،‬ويكــون صرفهــا يف نهايــة كل شــهر ميــادي‬\n      ‫فهــذا غيــر صحيــح فلــم أدخــل معــه يف مســاهمة إطالقــا وأمــا مــا ذكــره‬\n      ‫مــن تســليم موكلــه إيــاي مبلغــا قــدره مليونــان وثمامنائــة وســتون ألــف‬\n      ‫ريالــ‪ 2860000‬فهــذا غيــر صحيــح‪ ،‬وإمنــا املبلــغ الــذي اســتلمته مــن‬\n      ‫املدعــي أصالــة هــو فقــط مليونــان واثنــان وثالثــون ألفــا وثمانــون‬\n      ‫ريــاال‪ 2032080‬وهــو عبــارة عــن قيمــة بضاعــة وليــس كمــا ذكــر‬\n      ‫املدعــي وكالــة‪ ،‬ومســتعد بإثبــات ذلــك‪ ،‬وبالتالــي فلســت مســتعدا‬\n      ‫باملبلــغ الــذي طلبــه املدعــي وكالــة هــذا مــا لــدي وبعــرض ذلــك علــى‬\n      ‫املدعــي وكالــة قــال الصحيــح مــا ذكرتــه ومــا ذكــره املدعــى عليــه‬\n      ‫ليــس بصحيــح‪ ،‬هــذا مــا لــدي فجــرى ســؤال املدعــى عليــه عــن بينتــه‬\n      ‫علــى مــا دفــع بــه فقــال بينتــي عبــارة عــن فواتيــر تثبــت مــا ذكرتــه ولــم‬\n      ‫أحضرهــا يف هــذه اجللســة ومســتعد بإحضارهــا يف اجللســة القادمــة‬\n      ‫ورفعــت اجللســة مــن أجــل ذلــك ومــن أجــل االطــاع علــى أوراق املعاملــة‬\n\n\n‫‪141‬‬\n\f‫ويف جلســة أخــرى حضــر الطرفــان ثــم أبــرز املدعــي وكالــة وكالــة‬\n‫جديــدة صــادرة مــن كتابــة عــدل محافظــة اخلــرج برقــم ‪33325397‬‬\n‫وتاريــخ ‪1433/7/2‬ه ـ وباالطــاع عليهــا وجــد أنهــا تتضمــن توكيــل‬\n‫املدعــي أصالــة للمدعــي وكالــة وجعــل فيهــا للوكيــل حــق املرافعــة‬\n‫واملدافعــة واإلقــرار واإلنــكار والصلــح ثــم جــرى ســؤال املدعــى عليــه‬\n‫عــن البينــة التــي وعــد بإحضارهــا فقــال لقــد أحضــرت صــور ثــاث‬\n‫فواتيــر صــادرة مــن مجموعــة ‪ ...‬للحاســب والتقنيــة وهــذه املؤسســة‬\n‫عائــدة لكفيلــي الســابق الــذي كنــت أعمــل لديه تثبــت تعاملي التجاري‬\n‫مــع املدعــي أصالــة وليــس كمــا ذكــر وكيلــه‪ ،‬وباالطــاع علــى صــور‬\n‫الفواتيــر املذكــورة تبــن أنهــا صــادرة مــن مجموعــة ‪ ....‬للحاســب‬\n‫والتقنيــة تتضمــن بيــع أجهــزة علــى العميــل ‪ .....‬األولــى برقــم ‪1732‬‬\n‫وتاريــخ ‪2005/12/7‬م مببلــغ قــدره ثالثمائــة وثمانيــة وســبعون ألفــا‬\n‫ومائتــا ريالــ‪ 378200‬والثانيــة برقــم‪ 1489‬وتاريــخ ‪2005/7/14‬م مببلــغ‬\n‫قــدره ثالثمائــة وخمســة وثمانــون ألفــا وخمســمائة ريالــ‪ 385500‬والثالثــة‬\n‫برقــم ‪ 1490‬وتاريــخ ‪2005/7/14‬م مببلــغ قــدره أربعمائة وثالثة وأربعون‬\n‫ألفــا وأربعــون ريــاال‪ 443040‬ومجمــوع قيمــة صــور الفواتيــر الثــاث‬\n‫مبلغــا قــدره مليــون ومائتــان وســتة آالف وســبعمائة وأربعــون‬\n‫ريــاال‪ 1206740‬ثــم أردف املدعــى عليــه قائــا وهــذه الفواتيــر مت أخــذ‬\n‫توقيــع املدعــي أصالــة عليهــا ألنهــا كانــت باآلجــل ثــم ســددها الحقــا‬\n‫وهنــاك فواتيــر أخــرى لــم آخــذ توقيعــه عليهــا ألنــه كان يدفــع ثمنهــا‬\n‫مباشــرة وبالتالــي فــا حاجــة ألخــذ توقيعــه عليهــا وبعرضهــا على املدعي‬\n‫وكالــة قــال إن هــذه الصــور ســبق أن اطلعــت عليهــا وهــي مــزورة وغيــر‬\n‫صحيحــة وإن كان صادقــا فليحضــر أصلهــا‪ ،‬كمــا أن التوقيــع‬\n\n\n                                                                                ‫‪142‬‬\n\f      ‫املنســوب ملوكلــي ليــس توقيعــه‪ ،‬إضافــة إلــى أن كميــات األجهــزة‬\n      ‫املوجــودة يف الفواتيــر ضخمــة جــدا وموكلــي ليــس لديــه محــات لبيــع‬\n      ‫هــذه األجهــزة وال يتعامــل بهــا‪ ،‬كمــا أنــه يف دعوانــا لــدى ديــوان املظالــم‬\n      ‫طالبنــا املدعــى عليــه بإثبــات أن مؤسســة كفيلــة ‪ ...‬متتلــك هــذه الكميــة‬\n      ‫مــن األجهــزة ولــم يســتطع إثبــات ذلــك إذ أن احملــل الــذي يعمــل فيــه محــل‬\n      ‫جتزئــة وليــس محــل جملــة‪ ،‬كمــا أن قيمــة الفواتيــر تختلــف عــن قيمــة‬\n      ‫الشــيكات املســلمة لــه هــذا مــا لــدي وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫قــال بالنســبة ألصــل الفواتيــر فــا يوجــد لــدي وذلــك ألنهــا ســرقت منــي‬\n      ‫بتاريــخ ‪1427/3/18‬ه ـ وقــد عممــت عنهــا لــدى الشــرطة مبوجــب‬\n      ‫التعميــم رقــم ‪/945/19‬ب وتاريخ‪1427/3/18‬ه ـ وبالنســبة ملــا ذكــره‬\n      ‫مــن أن موكلــه ليــس لديــه محــا لبيــع األجهــزة وال يتعامــل بهــا فأنــا ال‬\n      ‫عالقــة لــي بذلــك واملهــم عنــدي أن يشــتري مــن محلــي فقــط‪ ،‬ومــا ذكره‬\n      ‫مــن مطالبتــه إيــاي لــدى الديــوان بإثبــات هــذه الكميــة فأنــا ال علــم لــي‬\n      ‫بذلــك إذ أن وكيلــي هــو الــذي كان يحضــر لــدى الديــوان ولســت أنــا‪،‬‬\n      ‫وبالنســبة لعــدم مطابقــة مبالــغ الشــيكات مــع الفواتيــر فذلــك يعــود ألن‬\n      ‫املدعــي أصالــة كان يســدد القيمــة علــى دفعــات وبالتالــي فطبيعــي أال‬\n      ‫تتطابــق القيــم مــع بعضهــا‪ ،‬ثــم جــرى ســؤال املدعــى عليــه هــل لديــه زيادة‬\n      ‫بينــة علــى مــا دفــع بــه فقــال ال بينــة لــي ســوى هــذه الفواتيــر هــذا مــا لــدي‬\n      ‫وبســؤال املدعــي وكالــة عــن بينتــه قــال بينتــي هــي كالتالــي ‪ :‬أوال ‪/‬‬\n      ‫إقــراره لديكــم باســتالم مبلــغ قــدره مليونــان واثنــان وثالثــون ألفــا‬\n      ‫وثمانــون ريــاال ‪ . 2032080‬ثانيــا ‪ /‬أربــع شــيكات مســحوبة علــى‬\n      ‫مصــرف ‪ .....‬باســم املدعــى عليــه اثنــان منهــا ذكــر فيهــا أنهــا مقابــل‬\n      ‫مســاهمة يف مؤسســة ‪ ...‬التجاريــة‪ ،‬ثــم أبــرز صــور الشــيكات املذكورة‬\n\n\n‫‪143‬‬\n\f‫وباالطــاع عليهــا تبــن أنهــا مســحوبة علــى مصــرف ‪ .....‬صــادرة مــن‬\n‫املدعــي أصالــة ‪ .....‬األول برقــم ‪ 3‬وتاريــخ ‪1426/5/27‬ه ـ مببلــغ قــدره‬\n‫ســتمائة واثنــان وثالثــون ألــف ريالــ‪ 632000‬ألمــر ‪ .....‬وذلــك مقابــل‬\n‫املساهمة يف مؤسسة ‪ .....‬التجارية والثاني برقم ‪ 5‬وتاريخ ‪2005/9/6‬م‬\n‫مببلــغ قــدره مائتــان وســبعون ألــف ريالــ‪ 270000‬ألمــر ‪ .....‬والثالــث برقــم‬\n‫‪ 10‬وتاريــخ ‪2005/1/5‬م مببلــغ قــدره مائتــان وســبعة وســتون ألــف‬\n‫ريالــ‪ 267000‬مقابــل شــراء ‪ 47‬ســهم يف مؤسســة ‪ .....‬التجاريــة والرابــع‬\n‫برقــم ‪ 11‬وتاريــخ ‪2005/11/12‬م مببلــغ قــدره خمســمائة وثالثــة‬\n‫وخمســون ألفــا وثمانــون ريــاال‪ 553080‬ومجمــوع قيمــة الشــيكات مبلغا‬\n‫قــدره مليــون وســبعمائة واثنــان وعشــرون ألفــا وثمانــون ريــاال‪1722080‬‬\n‫وبعرضهــا علــى املدعــى عليــه صــادق عليهــا وقــال لقــد اســتلمت قيمــة‬\n‫هــذه الشــيكات مــن املدعــي أصالــة وبســؤاله عمــا كتــب علــى‬\n‫الشــيكني مــن أنهمــا مســاهمة يف مؤسســة ‪ .....‬التجاريــة قــال إننــي ال‬\n‫أذكــر ذلــك لطــول املــدة ثالثــا‪ /‬حــواالت بنكيــة مــن موكلــي للمدعــى‬\n‫عليــه علــى حســابه يف مصــرف ‪ .....‬وعددهــا أربــع حــواالت ســأحضرها‬\n‫يف اجللســة القادمــة ‪ .‬رابعــا ‪ /‬صــور لثالثــة عقــود بــن موكلــي وبــن‬\n‫املدعــى عليــه وقــد طعــن فيهــا املدعــى عليــه بالتزويــر وأنكرهــا ســابقا‬\n‫ونظــرا ألن املدعــى عليــه قــد ســحب أصلهــا مــن موكلــي حجــة حتويــل‬\n‫املؤسســة إلــى شــركة فإننــي أســتغني عــن ذكرهــا مــن ضمــن البينــات‬\n‫‪ .‬خامســا‪ /‬صــدور حكمــن األول مــن هــذه احملكمــة والثانــي حكــم‬\n‫مــن الديــوان بإلــزام املدعــى عليــه بدفــع مبلــغ قــدره مليونــان واثنــان‬\n‫وثالثــون ألفــا وثمانــون ريــاال ‪ .‬هــذا مــا لــدي مــن بينــات وبعــرض ذلــك‬\n‫علــى املدعــى عليــه قــال بالنســبة للعقــود التــي أشــار لهــا املدعــي وكالــة‬\n\n\n                                                                                      ‫‪144‬‬\n\f      ‫فهــي غيــر صحيحــة ولــم أوقــع مــع موكلــه علــى أي عقــد‪ ،‬وبالنســبة‬\n      ‫للحكمــن اللــذان أشــار إليهمــا املدعــي وكالــة فإنهمــا قــد نقضــا مــن‬\n      ‫االســتئناف ورفعــت اجللســة مــن أجــل إحضــار املدعــي وكالــة للحــواالت‬\n      ‫التــي حولهــا موكلــه للمدعــى عليــه ويف جلســة أخــرى حضــر الطرفــان‬\n      ‫ثــم جــرى ســؤال املدعــي وكالــة عــن احلــواالت التــي وعــد بإحضارهــا يف‬\n      ‫اجللســة املاضيــة فقــال نعــم لقــد أحضرتهــا ثــم أبــرز أربــع ورقــات‬\n      ‫وباالطــاع عليهــا وجــد أنهــا صــورة حلــواالت صــادرة مــن مصــرف ‪ .....‬مــن‬\n      ‫حســاب املدعــي أصالــة إلــى حســاب املدعــى عليــه وهــي علــى النحــو‬\n      ‫التالــي األولــى مببلــغ قــدره عشــرون ألــف ريالــ‪ 20000‬بتاريــخ‬\n      ‫‪2005/3/24‬م والثانيــة مببلــغ قــدره مائتــان وتســعون ألــف ريالــ‪290000‬‬\n      ‫بتاريــخ ‪2005/5/30‬م والثالثــة مببلــغ قــدره تســعة آالف وســبعمائة‬\n      ‫ريالــ‪ 9700‬بتاريــخ ‪2005/10/7‬م والرابعــة مببلــغ قــدره عشــرون ألــف‬\n      ‫ريالــ‪ 20000‬بتاريــخ ‪2005/10/7‬م ومجموعهــا مبلغــا قــدره ثالثمائــة‬\n      ‫وتســعة وثالثــون ألفــا وســبعمائة ريالــ‪ 339700‬وبعرضهــا علــى املدعــى‬\n      ‫عليــه قــال إن هــذه احلــواالت صحيحــة وعليــه فيكــون مجمــوع املبلــغ‬\n      ‫الــذي اســتلمته مــن املدعــي أصالــة قــدره مليونــان وواحــد وســتون ألفــا‬\n      ‫وســبعمائة وثمانــون ريــاال ‪2061780‬ولكــن هــذا املبلــغ كمــا ذكــرت‬\n      ‫ســابقا هــو عبــارة عــن قيمــة بضاعــة وليــس كما ذكر املدعــي وكالة‪،‬‬\n      ‫هــذا مــا لــدي ثــم جــرى ســؤال املدعــي وكالــة عــن رأس مــال موكلــه يف‬\n      ‫املســاهمة التــي يدعــي فقــال إن رأس موكلــي الــذي ســلمه للمدعــى‬\n      ‫عليــه قــدره مليونــان ومائــة وثالثــة وســتون ألفــا وثمانــون ريــاال‪2163080‬‬\n      ‫وهــو علــى النحــو التالــي ‪ -1‬مليــون وســبعمائة واثنــان وعشــرون ألفــا‬\n      ‫وثمانــون ريــاال‪ 1722080‬مبوجــب شــيكات مت ذكرهــا ســابقا ‪-2‬‬\n\n\n‫‪145‬‬\n\f‫ثالثمائــة وتســعة وثالثــون ألفــا وســبعمائة ريالــ‪ 339700‬مبوجب حواالت‬\n‫مصرفيــة مت ذكرهــا ســابقا ‪ -3 .‬مائــة وألفــا ريالــ‪ 102000‬وهــي عبــارة‬\n‫عــن مبلــغ نقــدي ســلمه موكلــي بيــد املدعــى عليــه وبذلك يصبــح مجموع‬\n‫املبلــغ قــدره مليونــان ومائــة وثالثــة وســتون ألفــا وثمانــون ريــاال‪2163080‬‬\n‫هــذا مــا لــدي ثــم جــرى ســؤال الطرفــن هــل لديهمــا مــا يضيفانــه فقــال‬\n‫املدعــى عليــه إننــي أريــد أن أضيــف أن شــاهدي ‪ .....‬مصــري اجلنســية‬\n‫قــد ســافر إلــى مصــر ســفرا نهائيا وال أســتطيع إحضــاره وأطلب االطالع‬\n‫علــى شــهادته املدونــة يف الصــك الصــادر مــن هــذه احملكمــة برقــم‬\n‫‪ 48/4/99‬وتاريــخ ‪1427/12/4‬ه ـ عليــه فقــد قــررت رفــع اجللســة مــن‬\n‫أجــل ذلــك والنتهــاء وقتهــا ويف جلســة أخــرى حضــر الطرفــان كمــا‬\n‫حضــر املدعــي أصالــة ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقم‬\n‫‪ .....‬ثــم جــرى منــا االطــاع علــى شــهادة املدعــو ‪ .....‬املدونــة علــى الصــك‬\n‫الصــادر مــن فضيلــة ســلفنا برقــم ‪ 48/4/99‬وتاريــخ ‪1427/12/4‬ه ـ‬\n‫وهــذا نصهــا « ثــم حضــر الشــاهد ‪ .....‬مبوجــب إقامــة رقــم ‪ .....‬بتاريــخ‬\n‫‪1425/9/12‬ه ـ وبســؤاله عــن شــهادته قــال إننــي حضــرت مــع ‪ .....‬واألخ‬\n‫‪ .....‬وقــد طلــب مــن ‪ .....‬تصويــر ثــاث فواتيــر بيــع بضاعــة مــن‬\n‫الكمبيوتــرات مببلــغ مليــون ومائتــن وســتة آالف وســبعمائة وأربعــن‬\n‫ريــاال وقمــت بتصويرهــا وإعطــاء ‪ .....‬صــورة منهــا وبســؤاله هــل حضــر‬\n‫عقــد البيــع أو تســليم البضاعــة فقــال إننــي لــم أحضــر عقــد البيــع وال‬\n‫تســليم البضاعــة وأنــي ســمعتهم يتكلمــون يف البضاعــة وبســؤاله عــن‬\n‫عالقتــه باملدعــو ‪ .....‬قــال إنــه مديــر املؤسســة وأعمــل حتــت إدارتــه‬\n‫لصالــح صاحــب املؤسســة كفيلــي ‪ ...‬هكــذا شــهد « وبعــرض ذلــك‬\n‫علــى املدعــي أصالــة قــال إن الشــاهد املذكــور أعرفــه وهــو يعمــل يف‬\n\n\n                                                                                      ‫‪146‬‬\n\f      ‫املؤسســة مــع املدعــى عليــه وهــو يكــذب يف شــهادته فلــم يحصــل شــيء‬\n      ‫مــن الــذي ذكــره إطالقــا هــذا مــا لــدي‪ ،‬ثــم جــرى ســؤال املدعــي أصالــة‬\n      ‫هــل لديــه زيــادة بينــة علــى دعــواه فقــال ليــس لــدي زيــادة بينــة ســوى مــا‬\n      ‫قدمــه وكيلــي فجــرى ســؤاله عــن املبلــغ النقــدي الــذي يدعــي أنــه ســلمه‬\n      ‫للمدعــى عليــه بيــده وقــدره مائــة وألفــا ريالــ‪ 102000‬هــل لديــه بينــة عليــه‬\n      ‫فقــال ال بينــة لــدي علــى ذلــك وأطلــب ميــن املدعــى عليــه علــى نفــي ذلــك‬\n      ‫وعلــى نفــي وجــود املســاهمة التــي ذكرتهــا يف دعــواي ووجــود أربــاح‬\n      ‫فيهــا هــذا مــا لــدي وبعــرض ذلــك علــى املدعــى عليــه قــال ال مانــع لــدي‬\n      ‫مــن أداء اليمــن الشــرعية علــى نفــي اســتالمي ملبلــغ املائــة وألفــي‬\n      ‫ريالــ‪ 102000‬وعلــى عــدم وجــود مســاهمة بينــي وبــن املدعــي أصالــة‬\n      ‫ولكــن أوراق القضيــة موجــودة بالكامــل لــدى احملامــي وأطلــب إمهالي‬\n      ‫للجلســة القادمــة حتــى أمتكــن مــن االطــاع عليهــا وأســتطيع أداء اليمــن‬\n      ‫علــى يقــن هــذا مــا لــدي عليــه فقــد قــررت رفــع اجللســة مــن أجــل ذلــك‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان كمــا حضــر املدعــي أصالــة ‪.....‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وبعــرض مــا مت ضبطه‬\n      ‫ســابقا علــى املدعــي أصالــة صــادق عليــه وقــال إننــي أقــرر تنازلــي عــن‬\n      ‫املطالبــة باألربــاح وأحصــر دعــواي يف املبلــغ األخيــر ومجموعــه مليونــان‬\n      ‫ومائــة وثالثــة وســتون ألفــا وســبعمائة وثمانــون ريــاال‪ 2163780‬وهــو‬\n      ‫عبــارة عــن املبلــغ الــذي أقــر بــه لديكــم وقــدره مليونــان وواحــد وســتون‬\n      ‫ألفــا وســبعمائة وثمانــون ريــاال ‪ 2061780‬إضافــة إلــى املبلــغ اآلخــر‬\n      ‫وقــدره مائــة وألفــا ريالــ‪ 102000‬فقــط علمــا بــأن قيمــة الشــيكات‬\n      ‫واحلــواالت داخلــة يف املبلــغ الــذي أقــر بــه املدعــى عليــه لديكــم عــدا‬\n      ‫املائــة وألفــي ريالــ‪ ،102000‬وبســؤال املدعــى عليــه هــل راجــع حســاباته‬\n\n\n‫‪147‬‬\n\f‫فقــال نعــم لقــد راجعتهــا ولــم أجــد أن املدعــي أصالــة ســلمني مبلــغ املائــة‬\n‫وألفــي ريالــ‪ 102000‬وبعــرض اليمــن التالــي نصهــا علــى املدعــى عليــه «‬\n‫واهلل العظيــم أن املدعــي أصالــة ‪ .....‬لــم يســلمني مبلــغ املائــة وألفــي‬\n‫ريالــ‪ 102000‬التــي يدعــي بهــا واهلل العظيــم « قــال إننــي غيــر مســتعد‬\n‫ببــذل اليمــن الشــرعية‪ ،‬وذلــك ألننــي غيــر متأكــد مــن ذلــك‪ ،‬فجــرى‬\n‫إنــذاره ثالثــا بأنــه إذا لــم يحلــف اليمــن الشــرعية فســيقضى عليــه‬\n‫بالنكــول إال أنــه امتنــع عــن أدائهــا‪ ،‬ثــم جــرى ســؤال املدعــى عليــه عــن‬\n‫دفعــه بــأن املبالــغ التــي اســتلمتها مــن املدعــي أصالــة كانــت عبــارة عــن‬\n‫قيمــة بضاعــة اشــتراها األخيــر منــه‪ ،‬هــل لديــه زيــادة بينــة علــى ذلــك‬\n‫فقــال ليــس لــدي زيــادة بينــة فجــرى إفهامــه بأنــه ليــس لــه إال ميــن املدعــي‬\n‫أصالــة علــى نفــي ذلــك فقــال ال أريــد مينيــه‪ ،‬ثــم جــرى االطــاع علــى‬\n‫احلكــم الصــادر مــن فضيلــة ســلفنا برقــم ‪ 48/4/99‬وتاريــخ‬\n‫‪1427/11/4‬ه ـ واملتضمــن إفهــام املدعــي بــأن دعــواه مــن اختصــاص‬\n‫ديــوان املظالــم واملصــدق مــن محكمــة االســتئناف برقــم ‪/122‬ق‪/5‬أ‬\n‫وتاريــخ ‪1428/3/26‬ه ـ كمــا جــرى االطــاع علــى احلكــم الصــادر مــن‬\n‫ديــوان املظالــم برقــم ‪/157‬د‪/‬ت ج‪ 7‬لعــام ‪1427‬ه ـ واملتضمــن عــدم‬\n‫اختصــاص الديــوان والئيــا بنظــر هــذه الدعــوى كمــا جــرى االطــاع‬\n‫علــى خطــاب معالــي رئيــس املجلــس األعلــى للقضــاء رقــم ‪ 2648‬وتاريــخ‬\n‫‪1433/3/6‬ه ـ واملرفــق بــه قــرار جلنــة الفصــل يف تنــازع االختصــاص رقــم‬\n‫‪/17‬ت وتاريــخ ‪1433/2/22‬ه ـ واملتضمــن قــرار اللجنــة بــأن القضيــة مــن‬\n‫اختصــاص القضــاء العــام ثــم جــرى ســؤال الطرفــن هــل لديهمــا مــا‬\n‫يضيفانــه فقــاال ليــس لدينــا مــا نضيفــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ونظــرا إلقــرار املدعــى عليــه باســتالمه مبلغــا قــدره مليونــان‬\n\n\n                                                                                         ‫‪148‬‬\n\f      ‫وواحــد وســتون ألفــا وســبعمائة وثمانــون ريــاال‪ 2061780‬مــن املدعــي‬\n      ‫أصالــة ودفــع بأنهــا قيمــة بضاعــة اشــتراها منــه‪ ،‬وأنكــر املدعــي ذلــك‬\n      ‫وعجــز املدعــى عليــه عــن إحضــار البينــة املوصــل علــى دفعــه ذلــك‪ ،‬وقــرر‬\n      ‫عــدم رغبتــه يف ميــن خصمــه علــى نفــي دفعــه ذلــك‪ ،‬ونظــرا إلنــكار‬\n      ‫املدعــى عليــه مبلــغ املائــة وألفــي ريالــ‪ 102000‬التــي ادعاهــا املدعــي‬\n      ‫وحيــث قــرر املدعــي عــدم وجــود بينــة لــه علــى ذلــك وطلــب ميــن املدعــى‬\n      ‫عليــه علــى نفــي ذلــك‪ ،‬ونظــرا المتنــاع املدعــى عليــه عــن بــذل اليمــن‬\n      ‫الشــرعية وحيــث جــرى إفهامــه ثالثــا بأنــه إذا لــم يحلــف فســيقضى عليه‬\n      ‫بالنكــول‪ ،‬وبنــاء علــى مــا قــرره أهــل العلــم مــن مشــروعية القضــاء‬\n      ‫بالنكــول‪ ،،‬ولقولــه صلــى اهلل عليــه وســلم ‪»:‬البينــة علــى املدعــي‬\n      ‫واليمــن علــى مــن أنكــر « وقولــه صلــى اهلل عليــه وســلم ‪»:‬علــى اليــد مــا‬\n      ‫أخــذت حتــى تؤديــه « ونظــرا لتقريــر املدعــي أصالــة تنازلــه عــن املطالبــة‬\n      ‫باألربــاح لــكل مــا تقــدم فقــد ثبــت لــدي تنــازل املدعــي أصالــة عــن‬\n      ‫املطالبــة باألربــاح وحكمــت علــى املدعــى عليــه ‪ .....‬بدفــع مبلــغ قــدره‬\n      ‫مليونــان ومائــة وثالثــة وســتون ألفــا وســبعمائة وثمانــون ريــاال ‪2163780‬‬\n      ‫للمدعــي أصالــة ‪ .....‬وأفهمــت املدعــى عليــه أن لــه ميــن املدعــي أصالــة‬\n      ‫متــى مــا طلبهــا‪ ،‬وبعرضــه علــى الطرفــن قــرر املدعــي أصالــة القناعــة‬\n      ‫بــه وقــرر املدعــى عليــه عدمهــا فجــرى إفهامــه بأنــه ســيجري تســليمه‬\n      ‫نســخة مــن احلكــم بتاريــخ ‪1434/1/7‬ه ـ لتقــدمي اعتراضــه عليــه يف مدة‬\n      ‫أقصاهــا ثالثــون يومــا مــن ذلــك التاريــخ ففهــم ذلــك وكان ختــام اجللســة‬\n      ‫يف الســاعة ‪ 11 : 00‬صباح ـ ًا وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                      ‫محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/01/05‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق‪ 1434/05/06‬ه ـ‬\n\n\n‫‪149‬‬\n\f‫فتحــت اجللســة الســاعة ‪ 12 : 30‬وفيهــا كانــت قــد عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف برقــم ‪ 34653461‬وتاريــخ ‪1434/4/9‬ه ـ بشــرح‬\n‫فضيلــة رئيــس احملكمــة رقــم ‪ 34/653461‬وتاريــخ ‪1434/4/14‬ه ـ‬\n‫وبرفقهــا القــرار الصــادر مــن الدائــرة اخلامســة لتمييــز القضايــا احلقوقيــة‬\n‫مبحكمــة االســتئناف بالرياض رقــم ‪ 34178269‬وتاريخ ‪1434/4/3‬هـ‬\n‫املتضمــن املصادقــة علــى احلكــم وقــد ظهــر الصــك مبــا نصــه ( احلمــد‬\n‫هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك برقــم ‪ 346305‬وتاريــخ‬\n‫‪1434/1/7‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة العامــة باخلــرج‬\n‫الشــيخ ‪ .....‬وأصدرنــا القــرار رقــم ‪ 34178269‬وتاريــخ ‪1434/4/3‬ه ـ‬\n‫املتضمــن أنــه لــم يظهــر مــا يوجــب االعتــراض علــى احلكــم واهلل املوفــق‬\n‫قاضي اســتئناف ‪ .....‬توقيعه وختمه قاضي اســتئناف ‪ .....‬توقيعه وختمه‬\n‫رئيــس الدائــرة ‪ .....‬توقيعــه وختمــه) أ‪.‬ه ـ لــذا جــرى احلاقــه والتهميــش‬\n‫مبوجبــه وكان ختــام اجللســة الســاعة (‪ )1:00‬وبــاهلل التوفيــق‪ ،‬وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه وســلم ‪ .‬حرر يف ‪1434/5/6‬هـ‪.‬‬\n\n\n\n\n                                                                                     ‫‪150‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":138,"source_page_end":150,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0b6c0b0deed2033ce4a6d7a64c5d2715799c96615e2c3afd4f343aab61bcf34f","normalized_text_hash":"d4505046b802c1a2ac198efc3f76bb7e048a1cbbe2cea8023e6f9267d1f8982b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p138-346305"},{"id":"14b33022-ec33-5784-9828-a446123a422d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة مالية -إعادة مبلغ -إدعاء املدعي أن املبلغ سلفة -دفع املدعى عليه أن املبلغ مضاربة -كمبيالة ال تتضمن سبب املبلغ -شهادة شهود غير موصلة -بينة املدعى عليه وميينه -إحضار شاهد بعد احلكم -القول قول املضارب يف الربح واخلسارة -صرف نظر عن الدعوى.","document_number":"34176551","case_number":"33311796","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/1","year":"1434","subject":"مطالبة مالية -إعادة مبلغ -إدعاء املدعي أن املبلغ سلفة -دفع املدعى عليه أن املبلغ مضاربة -كمبيالة ال تتضمن سبب املبلغ -شهادة شهود غير موصلة -بينة املدعى عليه وميينه -إحضار شاهد بعد احلكم -القول قول املضارب يف الربح واخلسارة -صرف نظر عن الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/4/1 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34176551 :‬‬\n                         ‫َر ْق ُم الدعوى‪33311796 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34275764‬تاريخه‪1434/7/23:‬هـ‬\n\n\n      ‫مطالبــة ماليــة ‪ -‬إعــادة مبلــغ ‪ -‬إدعــاء املدعــي أن املبلــغ ســلفة ‪ -‬دفــع‬\n      ‫املدعــى عليــه أن املبلــغ مضاربــة ‪ -‬كمبيالــة ال تتضمــن ســبب املبلــغ‬\n      ‫‪ -‬شــهادة شــهود غيــر موصلــة ‪ -‬بينــة املدعــى عليــه وميينــه ‪ -‬إحضــار‬\n      ‫شــاهد بعــد احلكــم‪ -‬القــول قــول املضــارب يف الربــح واخلســارة ‪ -‬صــرف‬\n                                                                 ‫نظــر عــن الدعــوى‪.‬‬\n\n\n\n\n      ‫مــا قــرره الفقهــاء مــن أن القــول يف الربــح واخلســارة هــو قــول املضــارب‬\n                                                                        ‫مــع ميينــه‪.‬‬\n\n\n\n\n      ‫أقــام املدعــي وكالــة دعــواه ضــد املدعــى عليــه بأنــه أخــذ مــن موكلــه‬\n      ‫مبلــغ أربعمائــة وثالثــة وخمســن ألــف ريــال ألجــل أن يشــتري لــه بيت ـ ًا‬\n      ‫ويزوجــه ولكنــه لــم يفعــل وعنــد مطالبتــة باملبلــغ دفــع مائــة ألــف ريــال‬\n      ‫ولــم يدفــع الباقــي وطالــب إلزامــه بســدادها وقــد دفــع املدعــى عليــه أن‬\n      ‫املبلــغ أخــذه ليضــارب بــه يف األســهم وقــد خســرها ولــم يبــق إال خمســة‬\n      ‫وثمانــن ألــف ريــال أكملهــا عمــه إلــى مائــة ألــف واعطاهــا للمدعــي‬\n      ‫وأستشــهد بشــاهد علــى ذلــك وجــرى حتليفــه اليمــن وحكمــت‬\n      ‫احملكمــة بــرد دعــوى املدعــي وإخــاء ســبيل املدعــى عليــه‪ ،‬اعتــرض‬\n\n‫‪151‬‬\n\f‫املدعــي بالئحــة وأحضــر شــاهد ًا وقــررت احملكمــة عــدم تأثيــر ذلــك‬\n             ‫علــى احلكــم وجــرى التصديــق مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33311796‬وتاريــخ‬\n‫‪ 1433/05/04‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33781349‬وتاريــخ‬\n‫‪ 1433/05/04‬ه ـ ويف يــوم األربعــاء املوافــق‪ 1433/07/09‬ه ـ فتحــت‬\n‫اجللســة وفيهــا حضــر (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )........‬بصفتــه وكيــا عــن (‪ )........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ )........‬مبوجــب الوكلــة رقــم ‪ 17673‬يف‬\n‫‪1432/04/11‬ه ـ الصــادرة مــن كتابــة عــدل الثانيــة بالطائــف واملخــول‬\n‫لــه فيهــا حــق املرافعــة واملدافعــة وحضــور اجللســات واملطالبــة وادعــى‬\n‫علــى احلاضــر معــه يف مجلــس احلكــم (‪ )........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ )........‬بصفتــه وكيــا عــن (‪ )........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬مبوجــب الوكالــة رقــم‬\n‫‪ 3317327‬يف ‪1433/01/10‬ه ـ الصــادرة مــن كتابــة عــدل الثانية غرب‬\n‫مكــة املكرمــة واملخــول لــه فيهــا حــق املدافعــة واملرافعــة وحضــور‬\n‫اجللســات قائــا يف دعــواه إن املدعــى عليــه أصالــة ســبق وأن اســتغل طيبة‬\n‫والــدي موكلــي وجهلــه وكبــر ســنه وأخــذ منــه مبلــغ وقــدره أربعمائــة‬\n‫وثالثــة وخمســون ألــف ريــال مدعيــا أنــه سيشــتري بهــا لوالــدي منــزال‬\n‫وأنــه ســيزوجه منهــا إال أنــه لــم يفعــل ذلــك ولــم يعــد املبلــغ لوالــدي ثــم بعــد‬\n\n                                                                                              ‫‪152‬‬\n\f      ‫مطالبــة والــدي لــه بإعــادة املبلــغ أعــاد منــه مبلــغ وقــدره مائــة ألــف ريــال‬\n      ‫وذلــك عــن طريــق عــم املدعــى عليــه أصالــة (‪ )........‬ولــم يعــد الباقــي حتــى‬\n      ‫تاريخــه أطلــب احلكــم بإلــزام املدعــى عليــه بــأن يعيــد لوالــدي موكلــي‬\n      ‫املبلــغ املتبقــي بذمتــه وقــدره ثالثمائــة وثالثــة وخمســون ألــف ريــال هــذه‬\n      ‫دعــواي وبســؤال املدعــى عليــه وكالــة عــن دعــوى املدعــي قــال ماذكــره‬\n      ‫املدعــي فيــه مغالطــات والواقــع أن موكلــي أخــذ مــن املدعــي أصالــة‬\n      ‫مبلــغ وقــدره أربعمائــة وثالثــة وخمســون ألــف ريــال للمســاهمة فيهــا يف‬\n      ‫ســوق األســهم وكل ذلــك كان بنــاء علــى طلــب املدعــي أصالــة علــى أن‬\n      ‫يكــون ملوكلــي نســبة مــن األربــاح وأمــا ذكــر مــن أن موكلــي أعــاد‬\n      ‫للمدعــي أصالــة مبلــغ مائــة ألــف ريــال ســلمت لــه عــن طريــق عمــه‬\n      ‫املذكــور فأســال فيهــا موكلــي وأفيدكــم يف اجللســة القادمــة هكــذا‬\n      ‫أجــاب عندهــا أضــاف املدعــي وكالــة قائــا ماذكــره املدعــى عليــه‬\n      ‫وكالــة غيــر صحيــح والصحيــح ماذكرتــه ووالــدي كبيــر يف الســن‬\n      ‫وجاهــل واليعــرف ســوق األســهم ويف جلســة أخــرى حضــر املدعــي‬\n      ‫وكالــة كمــا حضــر يف هــذه اجللســة املدعــى عليــه أصالــة (‪)........‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬وبعــرض مــامت‬\n      ‫ضبطــه علــى املدعــى عليــه قــال ماذكــره املدعــي مــن أننــي أخــذت مــن‬\n      ‫والــده مبلــغ أربعمائــة وثالثــة وخمســون ألــف ريــال فهــذا صحيــح وكانت‬\n      ‫بنــاء علــى طلبــه وقــد أمرنــي أن ادخــل باملبلــغ ســوق االســهم وكان ذلــك‬\n      ‫بطلبــه وعلمــه ثــم بعــد خســارة االســهم طلــب منــي بيــع االســهم علــى‬\n      ‫خســارتها ورفــض اإلنتطــار وبعــد بيعهــا خرجــت االســهم مببلــغ خمســة‬\n      ‫وثمانــون ألــف ريــال فدفعتهــا للمدعــي أصالــة وأضــاف عليهــا أحــد‬\n      ‫أعمامــي مبلــغ وقــدره خمســة عشــر ألــف ريــال فهــذه املائــة ألــف التــي‬\n\n\n‫‪153‬‬\n\f‫ذكــر املدعــي وكالــة أنهــا عــادت ملوكلــه هكــذا أجــاب عندهــا‬\n‫أضــاف املدعــي وكالــة قائــا مــا ذكــره املدعــى عليــه غيــر صحيــح‪.‬‬\n‫والصحيــح ماذكرتــه وقــد كان لــدى موكلــي ســند علــى املدعــى عليــه‬\n‫يتضمــن أن ملوكلــي يف ذمــة املدعــى عليــه مبلــغ وقــدره أربعمائــة وســتون‬\n‫ألــف ريــال قــرض حســن إال أن املدعــى عليــه اســتطاع أن يســحب هــذا‬\n‫الســند مــن موكلــي ويدفــع لــه كمبيالــة تتضمــن مبلــغ وقــدره أربعمائــة‬\n‫وثالثــة وخمســون ألــف ريــال وهــي عامــة ولــم يذكــر فيهــا أنهــا مقابــل‬\n‫قــرض حســن وقــد كتبهــا ابــن عمــه املدعــو (‪ )........‬عندهــا أضــاف‬\n‫املدعــى عليــه قائــا هــذا الــكالم غيــر صحيــح فلــم يكــن هنــاك ســند‬\n‫كمــا يذكــر املدعــي وكالــة وأمــا الكمبيالــة التــي يذكرهــا املدعــي‬\n‫وكالــة فأنــا الــذي كتبتهــا وأشــهدت عليهــا عندهــا أضــاف املدعــي‬\n‫وكالــة قائــا إذا حلــف املدعــى عليــه علــى نفــي ماذكرتــه وأنــه لــم‬\n‫يكــن هنــاك ســند علــى املدعــى عليــه بالوصــف الــذي ذكرتــه وأن‬\n‫املدعــى عليــه لــم يســحب ذلــك الســند مــن والــدي بعــد ذلــك وأن املذكور‬\n‫(‪ )........‬لــم يكــن هــو الكاتــب للكمبيالــة التــي ذكرتهــا فــإن موكلي‬\n‫يقبــل ميينــه يف ذلــك ومســتعد ألن يتنــازل عــن هــذه الدعــوى ويف جلســة‬\n‫أخــرى حضــر املدعــي أصالــة (‪ )........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ )........‬وحضــر حلضــوره املدعــى عليــه أصالــة ويف هــذه‬\n‫اجللســة قــرر املدعــي أصالــة قائــا إننــي ال أزال أطالــب املدعــى عليــه‬\n‫أصالــة باملبالــغ التــي ذكرهــا وكيلــي يف اجللســات الســابقة وال أقبــل‬\n‫ميــن املدعــى عليــه أصالــة بخصــوص مــا دون يف اجللســة الســابقة عندهــا‬\n‫جــرى ســؤال املدعــى عليــه أصالــة عــن بينتــه علــى مــا جــاء يف إجابــة‬\n‫وكيلــه وإجابتــه يف اجللســات املاضيــة فقــال لــدي البينــة علــى ذلــك‬\n\n\n                                                                                 ‫‪154‬‬\n\f      ‫وأطلــب إمهالــي إلحضارهــا ويف جلســة أخــرى حضــر املدعــي أصالــة‬\n      ‫واملدعــى عليــه أصالــة وبســؤال املدعــى عليــه أصالــة عــن بينتــه التــي وعــد‬\n      ‫بإحضارهــا فقــال أحضرتهــا يف هــذه اجللســة ويف هــذه اجللســة حضــر‬\n      ‫(‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬وبســؤاله‬\n      ‫عمــا لديــه مــن شــهادة اشــهد هلل بأننــي اجتمعــت يف بيتــي أنــا وأخــي‬\n      ‫فيصــل ووكيــل املدعــي ابنــه (‪ )........‬وكانــت هنــاك مطالبــة ماليــة‬\n      ‫دائــرة بــن املدعــي أصالــة واملدعــى عليــه أصالــة فســمعت (‪ )........‬ابــن‬\n      ‫املدعــي أصالــة يف بيتــي يقــول إن والــدي اتصــل علــي وأخبرنــي قائــا مــا‬\n      ‫رايــك أن نشــغل املبلــغ الــذي لــدي وقــدره أربعمائــة وثالثــة وخمســن ألــف‬\n      ‫ريــال يف ســوق األســهم عــن طريــق (‪ )........‬املدعــى عليــه أصالــة فقلــت لــه‬\n      ‫تــوكل علــى اهلل هــذا مــا أشــهد بــه واهلل علــى مــا أقــول شــهيد هكــذا‬\n      ‫شــهد كمــا حضــر يف هــذه اجللســة (‪ )........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ )........‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد‬\n      ‫هلل أننــا اجتمعنــا أنــا وأخــي (‪ )........‬يف بيتــه مــع (‪ )........‬وكيــل املدعــي‬\n      ‫أصالــة حملاولــة اإلصــاح فيمــا بينهــم وبــن املدعــى عليــه (‪)........‬‬\n      ‫بخصــوص مبالــغ ماليــة فســألنا (‪ )........‬املذكــور عــن املبالــغ املاليــة‬\n      ‫فقــال إن والــدي اتصــل علــى وقــال لــي مــا رأيــك أن نشــغل املبلــغ الــذي‬\n      ‫لــدي وقــدره أربعمائــة وثالثــة وخمســن ألــف ريــال يف ســوق األســهم عــن‬\n      ‫طريــق (‪ )........‬املدعــى عليــه أصالــة فقلــت لــه تــوكل علــى اهلل هــذا مــا‬\n      ‫أشــهد بــه واهلل علــى مــا أقــول شــهيد هكــذا شــهد كمــا أحضــر‬\n      ‫للشــهادة (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)........‬‬\n      ‫وبســؤاله عمــا لديــه مــن شــهادة اشــهد هلل أنــه حضــر لــدي املدعــى عليــه‬\n      ‫أصالــة (‪ )........‬يف اســتراحة مبكــة وكان معــي أخــي (‪ )........‬وشــخص‬\n\n\n‫‪155‬‬\n\f‫يدعــى (‪ )........‬وكان مــع املدعــى عليــه (‪ )........‬كمبيالــة وطلــب منــا‬\n‫الثالثــة جميعــا أن نشــهد علــى تلــك الكمبيالــة وبســؤالنا لــه عــن‬\n‫الكمبيالــة قــال أعطانــي (‪ )........‬مبلــغ مالــي أذكــر اآلن أنــه أربعمائــة‬\n‫وثالثــة وخمســون ألــف ريــال أو أربعمائــة وخمســة وثالثــون ألــف ريــال‬\n‫ألجــل أن أضــارب لــه يف ســوق األســهم وحفظــا حلقــه أريــد حتريــر هــذه‬\n‫الكمبيالــة وأريــد شــهادتكم عليهــا هكــذا شــهد وبعــرض الشــهود‬\n‫وشــهاداتهم علــى املدعــي قــال شــهادتهم غيــر صحيحــة واملبلــغ هــو قــرض‬\n‫حســن أقرضتهــا للمدعــى عليــه وبســؤاله عــن بينتــه علــى أن املبلــغ قــرض‬\n‫حســن قــال بينــي وبــن املدعــى عليــه (‪ )........‬ســند يتضمــن إقــرار منــه أن‬\n‫املبلــغ قــرض حســن إال أنــه ســحب منــي ذلــك الســند وأعطانــي كمبيالــة‬\n‫وليــس لــدي مايثبــت أنــه ســحب منــي الســند وإذا نفــى ذلــك فأطلــب ميينــه‬\n‫علــى ذلــك وبعرضــه علــى املدعــى عليــه قــال لــم اســحب منــه أي ســند‬\n‫وليــس بينــي وبينــه مكاتبــات إال الكمبيالــة التــي ذكــر كمــا أن‬\n‫الكمبيالــة أنــا الــذي كتبتهــا بنفســي ومســتعد علــى احللــف علــى نفــي‬\n‫مــا ذكــره مــن أننــي ســحبت الســند الــذي يذكــره منــه ثــم اســتعد‬\n‫باحللــف فحلــف قائــا واهلل العلــي العظيــم الــذي ال إلــه إال هــو الغالــب‬\n‫الطالــب املــدرك املهلــك أننــي ماســحبت مــن املدعــي أي ســندات تتضمــن‬\n‫أن املبلــغ املدعــى بــه قــرض حســن هكــذا حلــف ثــم أضــاف املدعــي بــأن‬\n‫الســند املثبــت للمبلــغ حاليــا هــو الكمبيالــة املؤرخــة بتاريــخ‬\n‫‪1429/11/05‬ه ـ واملرفــق صــورة منهــا يف املعاملــة كمــا أضــاف املدعــى‬\n‫عليــه قائــا بأننــي مســتعد باحللــف مــع شــهادة الشــاهد الثالــث علــى أن‬\n‫الكمبيالــة محــررة يف املبلــغ املالــي املــدون فيهــا واملتضمــن أربعمائــة‬\n‫وثالثــة وخمســون ألــف ريــال علــى أن ذلــك املبلــغ اســتلمته مــن املدعــي‬\n\n\n                                                                                     ‫‪156‬‬\n\f      ‫ألجــل املضاربــة لــه يف ســوق األســهم عندهــا أذنــت لــه باحللــف علــى ذلــك‬\n      ‫ثــم حلــف قائــا واهلل العلــي الــذي ال إلــه إال هــو الغالــب الطالــب املــدرك‬\n      ‫املهلــك أن املبلــغ الــذي تضمنتــه الكمبيالــة التــي شــهد عليهــا الشــاهد‬\n      ‫الثالــث شــاهر وشــهد عليهــا املدعــو (‪ )........‬واملؤرخــة بتاريــخ‬\n      ‫‪1429/11/05‬ه ـ واملتضمنــة ملبلــغ أربعمائــة وثالثــة وخمســون ألــف ريــال‬\n      ‫هــو مبلــغ للمدعــي ســلمني إيــاه للمضاربــة لــه يف ســوق األســهم وليــس‬\n      ‫قــرض حســن واهلل علــى مــا أقــول شــهيد هكــذا حلــف ويف جلســة أخرى‬\n      ‫وفيهــا حضــر املدعــي أصالــة واملدعــى عليــه أصالــة ويف هــذه اجللســة‬\n      ‫جــرى تأمــل مــا مت ضبطــه ســابقا كمــا جــرى االطــاع علــى أوراق‬\n      ‫املعاملــة ومنهــا الصــك رقــم ‪ 32220243‬يف ‪1432/08/25‬ه ـ والصــادر‬\n      ‫مــن هــذه احملكمــة واملتضمــن احلكــم علــى املدعــى عليــه بتســليم‬\n      ‫املدعــي أصالــة مبلــغ وقــدره ثالثمائــة وثالثــة وخمســون ألــف ريــال‬\n      ‫واملنقــوض مــن محكمــة االســتئناف مبكــة املكرمــة بالقــرار رقــم‬\n      ‫‪ 33191694‬يف ‪1433/04/14‬ه ـ فبنــاء علــى ماتقــدم مــن الدعــوى‬\n      ‫واإلجابــة ومبــا أن املدعــى عليــه أقــر بإســتالمه ملبلــغ وقــدره أربعمائــة‬\n      ‫وثالثــة وخمســون ألــف ريــال ومبــا أنــه دفــع بــأن املبلــغ املدعــى بــه مســلم‬\n      ‫لــه مــن قبــل املدعــي ألجــل املضاربــة لــه بســوق األســهم ومبــا أنــه لــم يقــم‬\n      ‫البينــة املوصولــة علــى مادفــع ومبــا أن املدعــي قــرر بــأن بينتــه علــى دعــواه‬\n      ‫القــرض هــي ســند يتضمــن إقــرار املدعــى عليــه بإقتراضــه للمبلغ املدعى‬\n      ‫بــه ومبــا أنــه قــرر بــأن ذلــك الســند أخــذه منــه املدعــى عليــه ومبــا أن‬\n      ‫املدعــى عليــه نفــى ذلــك ومبــا أن املدعــي طلــب ميــن املدعــى عليــه علــى‬\n      ‫ذلــك النفــي ومبــا أن املدعــى عليــه حلــف بنحــو ماطلــب منــه ومبــا أن‬\n      ‫املدعــي قــرر بعــد ذلــك بــأن املثبــت لدعــواه هــو الكمبيالــة ومبــا أن‬\n\n\n‫‪157‬‬\n\f‫الشــاهد الثــاث املــدون شــهادته أعــاه شــهد بــأن املبلــغ الــذي تضمنتــه‬\n‫الكمبيالــة هــو مضاربــة يف ســوق األســهم وليــس قرضــا ومبــا أن املدعــى‬\n‫عليــه حلــف مــع شــهادة الشــاهد الثالــث علــى أن مبلــغ الكمبيالــة هــو‬\n‫مضاربــة يف ســوق األســهم وليــس قرضــا ولقضــاء النبــي صلــى اهلل عليــه‬\n‫وســلم بالشــاهد واليمني ومبا أن املدعى عليه قرر خســارته يف املضاربة‬\n‫وأنــه لــم يتبــق ســوى مبلــغ خمســة وثمانــن ألــف ريــال ومبــا أن املدعــي‬\n‫وكالــة قــرر باســتالمه مبلــغ مائــة ألــف ريــال وملــا قــرره الفقهــاء مــن أن‬\n‫القــول يف الربــح واخلســارة هــو قــول املضــارب لذلــك كلــه فقــد صرفــت‬\n‫النظــر عــن دعــوى املدعــي وأخليــت ســبيل املدعــى عليــه من هــذه الدعوى‬\n‫وبذلــك كلــه حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n‫عليــه القناعــة بــه وقــرر املدعــي اعتراضــه علــى احلكــم بتقــدمي الئحــة‬\n‫اعتراضيــة وطلــب االســتئناف وأجيــب لطلبــه وأفهــم مبراجعــة احملكمــة‬\n‫يــوم األربعــاء املوافــق ‪1434/04/03‬ه ـ الســتالم صــورة مــن احلكــم‬\n‫لتقــدمي اعتراضــه عليــه يف مــدة أقصاهــا ثالثــون يومــا مــن ذلــك التاريــخ‬\n‫إذا لــم يقــدم اعتراضــه خاللهــا ســقط حقــه يف االعتــراض واكتســب‬\n‫احلكــم القطعيــة حــرر يف ‪1434/04/01‬ه ـ وصلــى اهلل وســلم على نبينا‬\n                                            ‫محمد وعلى آله وصحبه أجمعني ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافــق ‪1434/06/24‬ه ـ فتحــت‬\n‫اجللســة ملناقشــة الئحــة املدعــي بخصــوص مــا ورد فيهــا يف البنــد ثالث ـ ًا‬\n‫واملتضمــن أن لديــه بينــة علــى النحــو الــوارد يف الالئحــة ويف هــذه اجللســة‬\n‫حضــر املدعــي أصالــة واملدعــى عليــه أصالــة كمــا حضــر يف هــذه‬\n‫اجللســة (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)........‬‬\n‫بصفتــه وكيــا عــن (‪ )........‬الوكيــل عــن املدعــي أصالــة بالوكالة رقم‬\n\n\n                                                                                      ‫‪158‬‬\n\f      ‫‪ 34450160‬يف ‪1434/4/13‬ه ـ وبســؤال املدعــي أصالــة عــن بينتــه قــال‬\n      ‫بينتــي أن املدعــى عليــه حضــر لــدى الشــاهدين وهمــا (‪ )........‬و(‪)........‬‬\n      ‫ابنــي (‪ )........‬وأخبرهمــا أن يف ذمتــه لــي مبلــغ وقــدره ثالثمائــة وثالثــة‬\n      ‫وخمســون ألــف ريــال ويف هــذه اجللســة حضــر (‪ )........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )........‬وبســؤاله عمــا لديــه مــن شــهادة‬\n      ‫قــال أشــهد هلل أن املدعــى عليــه هــذا احلاضــر حضــر لــدي يف منزلــي يف‬\n      ‫الهــدا وطلــب منــي أن أكلــم لــه املدعــي لتأجيلــه يف دفــع مبلــغ وقــدره‬\n      ‫ثالثمائــة وثالثــة وخمســون ألــف ريــال مــدة ســنة وثالثــة أشــهر اعتبــارا‬\n      ‫مــن تاريــخ حضــوره لــي وكان ذلــك يف نهايــة شــعبان عــام ‪1430‬ه ـ إال أن‬\n      ‫املدعــى عليــه لــم يفصــح لــي عــن ســبب هــذا املبلــغ وإمنــا قــال للمدعــي يف‬\n      ‫ذمتــي مبلــغ أربعمائــة وثالثــة وخمســون ألــف وصــل لــه مائــة ألــف وبقــي‬\n      ‫ثالثمائــة وثالثــة وخمســون ألــف ريــال هــذا مــا لــدي مــن شــهادة كمــا‬\n      ‫حضــر يف هــذه اجللســة (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ )........‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد أن املدعــى عليــه‬\n      ‫اتصــل بــي وطلــب حضــوري لــدى أخــي الشــاهد األول فاعتــذرت عــن‬\n      ‫احلضــور فقــال جتــد العلــم عنــد أخيــك وبعــد حضــوري عنــد أخــي كان‬\n      ‫املدعــى عليــه قــد غــادر وأخبرنــي بــأن املدعــى عليــه يطلــب منــا التوســط‬\n      ‫لــه لــدى املدعــي يف إمهالــه لســداد مبلــغ ثالثمائــة وثــاث وخمســن ألــف‬\n      ‫ريــال وباالتصــال علــى املدعــي رفــض اإلمهــال فاتصلــت علــى املدعــى‬\n      ‫عليــه وأخبرتــه بالرفــض وال أعلــم ســبب اســتحقاق ذلــك املبلــغ هــذا مــا‬\n      ‫لــدي مــن شــهادة وبعــرض الشــهود وشــهادتهم علــى املدعــى عليــه قــال‬\n      ‫حضــرت لــدى الشــاهد األول إلفادتــه عــن طبيعــة املبلــغ وأنــه كان يف‬\n      ‫األســهم حيــث إن ابــن املدعــي أفادهــم بأنــه قــرض ولــم أطلــب منهــم‬\n\n\n‫‪159‬‬\n\f‫التوســط لدى املدعي يف مهلة ألجل الســداد وأفدتهم أن املتبقي والبالغ‬\n‫ثالثمائــة وثالثــة وخمســون ألــف ريــال يف ســوق األســهم ولكــون ذلــك ال‬\n‫يؤثــر علــى مــا حكمــت بــه أعــاه كمــا أن ســائر الالئحــة ليــس فيهــا‬\n‫مــا يؤثــر علــى مــا حكمــت بــه لــذا أمــرت بإحلــاق ذلــك بالصــك وســجله‬\n‫حــرر يف ‪1434/06/24‬ه ـ ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                                     ‫آلــه وصحبــه أجمعــن ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق ‪1434/08/07‬ه ـ فتحــت‬\n‫اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫برقم ‪ 33781349‬يف ‪1434/07/29‬هـ وبرفقها القرار رقم ‪34275764‬‬\n‫يف ‪1434/07/23‬ه ـ ألصحــاب الفضيلــة قضــاة الدائرة احلقوقية الرابعة‬\n‫مبحكمــة االســتئناف مبكــة املكرمــة واملتضمــن املوافقــة علــى‬\n‫احلكــم أعــاه وللبيــان جــرى إحلاقــه حــرر يف ‪1434/08/07‬ه ـ وصلــى‬\n              ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n\n\n\n\n                                                                                 ‫‪160‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":151,"source_page_end":160,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aab8f90d1bf3be529cf91f8012aed962977a448ce75809e5a3f8a473c11d87f9","normalized_text_hash":"decba803e20e645213e30043c386fdf1ecaff5bbd3954c7561eb1916235083e5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p151-34176551"},{"id":"ace885f3-fc59-5640-a768-27eb66634154","document_type":"judgment","category":"judicial","subcategory":"general","title":"شركة مضاربة -مطالبة بأرباح وراس املال -تكييف التعامل بن الطرفن بشركة مضاربة -انعقاد شركة املضاربة بكل قول يدل عليها -شرط صحة شركة املضاربة تقدير نصيب العامل من الربح -تعدي العامل يف املضاربة يجعله ضامن ا -اقرار املدعى عليه -الزام املدعى عليه بإعادة رأس املال بشركة املضاربة -احلكم ببطان عقد املضاربة -اثبات ما اصطلح الطرفان عليه يف كيفية سداد املبلغ احملكوم به .","document_number":"33458770","case_number":"33603477","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/20","year":"1434","subject":"شركة مضاربة -مطالبة بأرباح وراس املال -تكييف التعامل بن الطرفن بشركة مضاربة -انعقاد شركة املضاربة بكل قول يدل عليها -شرط صحة شركة املضاربة تقدير نصيب العامل من الربح -تعدي العامل يف املضاربة يجعله ضامن ا -اقرار املدعى عليه -الزام املدعى عليه بإعادة رأس املال بشركة املضاربة -احلكم ببطان عقد املضاربة -اثبات ما اصطلح الطرفان عليه يف كيفية سداد املبلغ احملكوم به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/20 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33458770 :‬‬\n                          ‫َر ْق ُم الدعوى‪33603477 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3459598‬تاريخه‪1434/3/10:‬هـ‬\n\n\n       ‫شــركة مضاربــة ‪ -‬مطالبــة بأربــاح وراس املــال ‪ -‬تكييــف التعامــل بــن‬\n       ‫الطرفــن بشــركة مضاربــة ‪ -‬انعقــاد شــركة املضاربــة بــكل قــول يــدل‬\n       ‫عليهــا ‪ -‬شــرط صحــة شــركة املضاربــة تقديــر نصيــب العامــل مــن‬\n       ‫الربــح ‪ -‬تعــدي العامــل يف املضاربــة يجعلــه ضامن ـ ًا ‪ -‬اقــرار املدعــى‬\n       ‫عليــه ‪ -‬الــزام املدعــى عليــه بإعــادة رأس املــال بشــركة املضاربة ‪ -‬احلكم‬\n       ‫ببطــان عقــد املضاربــة ‪ -‬اثبــات مــا اصطلــح الطرفــان عليــه يف كيفيــة‬\n                                                        ‫ســداد املبلــغ احملكــوم بــه ‪.‬‬\n\n\n\n\n       ‫‪ -‬قــال يف كشــاف القنــاع ‪« 542/3‬وتنعقــد املضاربــة مبــا يــؤدى معنــى‬\n       ‫ذلــك أي معنــى املضاربــة والقــراض مــن كل قــول دل عليهــا ألن‬\n       ‫املقصــود املعنــى فجــاز بــكل مــا تــدل عليــه» ا‪.‬ه ـ وقــال أيضـ ًا يف ص ــ‪453‬‬\n       ‫« ومــن شــرط صحتهــا أي املضاربــة تقديــر نصيــب العامــل مــن الربــح‬\n       ‫فــان قــال رب املــال خــذ هــذا مضاربــة ولــم يذكــر ســهم العامــل لــم تصح‬\n       ‫أو قــال خــذ هــذا املــال مضاربــة ولــك جــزء حــظ أو نصيــب مــن الربــح‬\n       ‫فاملضاربــة فاســدة جلهالــة نصيــب العامــل» وقــال أيض ـ ًا ص ـ ‪« 542‬وان‬\n       ‫تعــد العامــل مــا أمــر بــه رب املــال فغصــب يــرد املــال وربحــه وال شــيء لــه‬\n                                                           ‫نظيــر عملــه كالغاصــب)‪.‬‬\n\n\n\n‫‪161‬‬\n\f‫ادعــى املدعيــان أنهمــا ســلما للمدعــى عليــه مبلغ ـ ًا مالي ـ ًا حيــث تعاقــدا‬\n‫معــه علــى أن يقــوم بتشــغيله يف التجــارة ملــدة ســنتني ويعطيهمــا أرباحــا‬\n‫شــهرية محــددة وبعــد انتهــاء املــدة يعيــد لهمــا رأس املــال وقــد انتهــت‬\n‫املــدة ولــم يســلم املدعــى عليــه مــن االربــاح ســوى ثالثــة عشــر ألــف‬\n‫ريــال كمــا حــل علــى املدعــى عليــه مبلغ ـ ًا قــدرة تســعون ألــف ريــال‬\n‫فقــال املدعــى عليــه بأنــه ســوف يشــغل هــذا املبلــغ مــدة خمــس ســنوات‬\n‫ويعطيهمــا أرباحـ ًا شــهرية وانهمــا لــم يتفقــا علــى مقــدار األربــاح الشــهرية‬\n‫وقــد انتهــت مــدة العقــد األول ولــم يســلم املدعــى عليــه للمدعيــن األربــاح‬\n‫وال رأس املــال وطلــب املدعيــان إلــزام املدعــى عليــه بتســليمهما رأس‬\n‫املــال واالربــاح مبلغــا وقــدرة مئتــان وأربعــة وعشــرون ألــف ريــال‪ ،‬صــادق‬\n‫املدعــى عليــه علــى الدعــوى جملــة وتفصيــا وقــرر ان املبلــغ املدعــى بــه‬\n‫يف ذمتــه وانــه عاجــز عــن ســداد املبلــغ كمــا قــرر املدعــى عليــه إن املبالــغ‬\n‫كان يشــغلها يف قطــع الغيــار واألســهم وانــه قــد خســر كامــل املبلــغ‪،‬‬\n‫قــرر املدعيــان ان املدعــى عليــه اخبرهمــا بــان يقــوم بتشــغيل املبالــغ يف‬\n‫قطــع غيــار الســيارات وليــس يف األســهم‪ ،‬صــادق املدعــى عليــه علــى‬\n‫ذلــك وقــرر انــه شــغل املبالــغ يف األســهم وانــه خســر كامــل املبلــغ‪ ،‬قــرر‬\n‫ناظــر القضيــة انــه بنــاء علــى الدعــوى واإلجابــة فقــد كيــف العقــد انــه‬\n‫شــركة مضاربــة وان تقريــر نصيــب العامــل شــرط لصحتهــا وهــو هنــا‬\n‫غيــر متحقــق وألن املــال قــد خســر بســبب تعــدى املدعــى عليــه ألنــه تعــد‬\n‫اذن املدعيــن ولألســباب املرصــودة يف نــص احلكــم فقــد صــدر حكــم‬\n‫ناظــر القضيــة بثبــوت بطــان العقــد بــن املدعيــن واملدعــى عليــه وإلــزام‬\n\n                                                                                        ‫‪162‬‬\n\f      ‫املدعــى عليــه بإعــادة رأس املــال للمدعيــن بعــد خصــم ما اســتلماه‪ ،‬قرر‬\n      ‫املدعيــان عــدم القناعــة وقــرر املدعــى عليــه القناعــة‪ ،‬صــدق احلكــم مــن‬\n      ‫محكمــة االســتئناف ‪ -‬عــادت املعاملــة مــن جهــة التنفيــذ‪ ،‬مت اثبــات مــا‬\n                                     ‫اصطلــح عليــه الطرفــان يف كيفيــة الســداد ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بع ــده ‪ ،‬أمــا بعــد ‪:‬‬\n      ‫فلــدي أنــا‪ .....‬القاضــي يف احملكمــة العامــة مبحافظــة القطيــف بنــاء‬\n      ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n      ‫القطيــف برقــم ‪ 33603477‬وتاريــخ ‪1433/10/15‬ه ـ واملقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331812019‬وتاريــخ ‪1433/10/15‬ه ـ ‪ ،‬حضــر‬\n      ‫املدعيــان ‪ .....‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ .....‬وزوجتــه ‪.....‬‬\n      ‫ســعودية بالســجل املدنــي رقــم‪ .....‬وحضــر حلضورهمــا املدعــى عليــه ‪.....‬‬\n      ‫ا‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وادعــى املدعــي قائـ ً‬\n      ‫‪ :‬إننــي ســبق أن تعاقــدت مــع املدعــى عليــه علــى أن أعطيــه أربعــن ألــف‬\n      ‫ـداء مــن‬\n             ‫ريــ( ‪ ) 40.000‬ــال ويقــوم بتشــغيلها يف التجــارة ملــدة ســنتني ابتـ ً‬\n      ‫‪ 2010/04/01‬م ويعطينــي أرباح ـ ًا شــهرية مقدارهــا أربعــة آآلف ريــ(‬\n      ‫‪ ) 4.000‬ــال ثــم بعــد انتهــاء املــدة يعيــد لــي رأس املــال كمــا أن زوجتــي‬\n      ‫هــذه احلاضــرة أيضـ ًا ‪ -‬تعاقــدت مــع املدعــى عليــه علــى أن تعطيــه أربعــن‬\n      ‫ألــف ريــ( ‪ ) 40.000‬ــال ويقــوم بتشــغيل املبلــغ يف التجــارة ملــدة ســنتني‬\n      ‫ـداء مــن ‪ 2010/09/01‬م ويعطيهــا أرباح ـ ًا شــهرية مقدارهــا ألفــان‬      ‫ابتـ ً‬\n      ‫وخمســمائة ري ـ ( ‪ ) 2.500‬ــال وبعــد انتهــاء املــدة يعيــد لهــا رأس املــال‬\n      ‫وقــد انتهــت املــدة ولــم يســلمنا املدعــى عليــه مــن األربــاح ســوى ثالثــة‬\n\n‫‪163‬‬\n\f‫عشــر ألــف ريــ( ‪ ) 13.000‬ــال وهــي أربــاح أول شــهرين فقــط منهــا ثمانيــة‬\n‫آآلف ريــ( ‪ ) 8.000‬ــال لــي و خمســة آآلف ريــ( ‪ ) 5.000‬ــال لزوجتــي ‪،‬‬\n‫وخــال تلــك املــدة وبعــد أن مضــى مــن العقــد ســنة وعــدة أشــهر حــلَّ علــى‬\n‫املدعــى عليــه مــن األربــاح تســعون ألــف ري ـ ( ‪ ) 90.000‬ــال لــي ولزوجتــي‬\n‫مناصفــة فطالبتــه بهــا فقــال لــي ولزوجتــي بأنــه ســيقوم بتشــغيلها لنــا‬\n‫مــدة خمــس ســنوات بعــد انتهــاء مــدة العقــد األول وســيعطينا أرباح ـ ًا‬\n‫شــهرية ولــم نتفــق علــى مقــدار األربــاح الشــهرية فوافقنــا علــى ذلــك ‪،‬‬\n‫وقــد انتهــت مــدة العقــد األول معــي يف ‪ 2012/04/01‬م ومــع زوجتــي‬\n‫يف ‪ 2012/09/01‬م ولــم يســلمنا املدعــى عليــه رأس املــال وال األربــاح‬\n‫‪ ،‬نطلــب إلزامــه بدفــع رأس املــال واألربــاح لنــا حــا ًال ومقدارهــا إجمــا ًال‬\n‫مئتــان وأربعــة وعشــرون ألــف ريــ( ‪ ) 224.000‬ــال منهــا ثمانــون ألــف ريــ(‬\n‫‪ ) 80.000‬ــال رأس مــال ومائــة وأربــع وأربعــون ألــف ريــ( ‪ ) 144.000‬ــال‬\n‫ا وبعرض‬     ‫أربــاح هكــذا ادعــى ووافقتــه علــى ذلــك زوجتــه جملة وتفصيـ ً‬\n‫ا ‪ :‬جميــع مــاورد يف دعــوى املدعــي‬       ‫ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n‫ا ولــه يف ذمتــي مئتــان وأربعــة وعشــرون ألــف‬           ‫صحيــح جملــة وتفصي ـ ً‬\n‫ريــ( ‪ ) 224.000‬ــال مقابــل مــا ذكــر ‪ ،‬وأنــا حاليـ ًا غيــر مســتعد بدفــع‬\n‫املبلــغ لعجــزي عــن ذلــك ومتــى مــا توفــر عنــدي املبلــغ فســأقوم بدفعــه ‪،‬‬\n‫ولكنــي أطلــب مــن املدعــي أن يعتــذر لــي وألمــي وإلخوانــي فأنــا أخــوه‬\n‫الشــقيق ومــا كان ينبغــي لــه أن يخاصمنــي أمــام القضــاء ألنــي أخــوه‬\n‫ومقــر لــه باملبلــغ وأنــا أطالبــه باالعتــذار ليصلــح خطــأه هكــذا أجــاب ‪.‬‬\n‫ويف جلســة ُأخــرى حضــر جميــع االطــراف فســألت املدعــى عليــه ‪ :‬أيــن‬\n‫ا ‪ :‬إننــي كنــت أشــغل املبلــغ يف قطــع الغيــار‬      ‫ذهــب املــال ؟ فأجــاب قائ ـ ً‬\n‫ويف األســهم وقــد خســرت كامــل املبالــغ التــي أخذتهــا مــن املدعيــن‬\n\n\n                                                                                          ‫‪164‬‬\n\f      ‫هكــذا أجــاب فاعتــرض علــى ذلــك املدعيــان قائلــن ‪ :‬أوالً‪ :‬نحــن دفعنــا‬\n      ‫لــك املــال بعــد االنهيــار املعــروف لســوق األســهم وثاني ـ ًا ‪ :‬أنــت قلــت لنــا‬\n      ‫بأنــك ســتقوم بتشــغيلها يف جتــارة قطــع غيــار الســيارات ولــم تقــل لنــا يف‬\n      ‫ا ‪ :‬صحيــح أنــي‬    ‫األســهم هكــذا اعترضــا فأجابهمــا املدعــى عليــه قائـ ً‬\n      ‫قلــت لكمــا بأنــي سأشــغلها يف قطــع الغيــار لكنــي يف احلقيقــة شــغلتها‬\n      ‫يف األســهم فيمــا بعــد وقــد خســرتها كاملــة أمــا أنكمــا أعطيتمانــي‬\n      ‫املبلــغ بعــد انهيــار الســوق فأجيــب عليــه بــأن الســوق حتــى اآلن ال يــزال‬\n      ‫فيــه مضاربــات وكنــت أنــا أحــد املضاربــن يف قطــاع التأمــن وقــد‬\n      ‫خســرت أمــا االنهيــار الــذي تذكرانــه فهــو االنهيــار املشــهور عــام ‪2006‬‬\n                                                        ‫م وقــد تكــرر بعــد ذلــك نــزول‬\n      ‫الســوق عــدة مــرات هكــذا أجــاب فســألت املدعــى عليــه ‪ :‬متــى أدخلــت‬\n      ‫ا ‪ :‬إننــي أدخلتــه تقريب ـ ًا‬ ‫مــال املدعيــن يف ســوق األســهم ؟ فأجــاب قائ ـ ً‬\n      ‫يف الشــهر العاشــر عــام ‪ 2011‬م وكان مقــدار املــال ثمانــون ألــف ري ـ‬\n      ‫( ‪ ) 80.000‬ــال ولــم يكــن زائــد ًا وال ناقص ـ ًا أي لــم يخســر ولــم يربــح‬\n      ‫قبــل هــذا التاريــخ هكــذا أجــاب وبعرضــه جوابــه علــى املدعيــن أفــادا‬\n      ‫قائلــن ‪ :‬نحــن ال نعلــم عــن مالنــا شــيئ ًا ســوى أنــه كان يريــد تشــغيله‬\n      ‫يف جتــارة قطــع الغيــار ولــو قــال لنــا إنــه يريــد تشــغيله يف األســهم ملــا‬\n      ‫ـاء علــى‬‫أعطينــاه شــيئ ًا هكــذا أفــادا ثــم جــرى قفــل بــاب املرافعــة فبنـ ً‬\n      ‫مــا تقــدم مــن الدعــوى احملــرر واإلجابــة املقــررة لصحــة الدعــوى وحيــث‬\n      ‫أقــر الطرفــان بوقــوع العقــد علــى الصفــة املذكــورة ‪ ،‬وقــد كيفنــا ذلــك‬\n      ‫شــركة مضاربــة كمــا قــال يف الكشــاف ج ‪ 3‬ص ‪ ( : 542‬وتنعقــد‬\n      ‫املضاربــة مبــا يــؤدي معنــى ذلــك أي معنــى املضاربــة والقــراض مــن كل‬\n      ‫قــول دل عليهــا ألن املقصــود املعنــى فجــاز بــكل مــا يــدل عليــه ) ا‪.‬ه ـ ‪.‬‬\n\n\n‫‪165‬‬\n\f‫ـف هنــا قــال‬  ‫وتقديــر نصيــب العامــل مــن الربــح شــرط لصحتهــا وهــو منتـ ٍ‬\n‫يف الكشــاف ج ‪ 2‬ص ‪ ( : 543‬ومــن شــرط صحتهــا أي املضاربــة تقديــر‬\n‫نصيــب العامــل مــن الربــح فــإن قــال رب املــال خــذ هــذا مضاربــة ولــم‬\n‫يذكــر ســهم العامــل لــم تصــح أو قــال خــذ هــذا املــال مضاربــة ولــك جــزء‬\n‫أو حــظ أو نصيــب مــن الربــح فاملضاربــة فاســدة جلهالــة نصيــب العامــل‬\n‫) وألن املــال قــد خســر بســبب تعــدي املدعــى عليــه ملــا أذن لــه فيــه مــن‬\n‫العمــل مــن قبــل رب املــال وهمــا املدعيــان وحينئــذٍ يكــون غاصبـ ًا كمــا‬\n‫قــال يف الكشــاف ج ‪ 3‬ص ‪ ( : 542‬وإن تعــدى العامــل مــا أمــر بــه رب‬\n‫املــال فغصــب يــرد املــال وربحــه وال شــيء لــه يف نظيــر عملــه كالغاصــب‬\n‫) ا‪.‬ه ـ وملــا ورد يف وقائــع املرافعــة ولغيــره فقــد حكمــت مبــا يلــي ‪ :‬أو ًال‬\n‫ثبــت لــدي بطــان العقــد الواقــع بــن املدعيــن وبــن املدعــى عليــه ‪ .‬ثانيـ ًا‬\n‫‪ :‬ألزمــت املدعــى عليــه بإعــادة رأس مــال الشــركة حــا ًال للمدعيــن بعــد‬\n‫خصــم مــا اســتلماه ســابق ًا ‪ ،‬للمدعــي إثنــن وثالثــن ألــف ري ـ ( ‪32.000‬‬\n‫) ــال وللمدعيــة خمســه وثالثــن ألــف ري ـ ( ‪ ) 35.000‬ــال هــذا مــا ظهــر‬\n‫لــي وبــه حكمــت وجــرى نطقــه علنـ ًا مبجلــس احلكــم الشــرعي الســاعة‬\n‫الثانيــة فقــررا املدعيــان عــدم القناعــة وقــرر املدعــي عليــه القناعــة‬\n‫واســتعدا بتقــدمي الئحــة اعتراضيــة فأفهمــا بتعليمــات االســتئناف وأن‬\n‫عليهمــا املراجعــة يــوم اإلثنــن املوافــق ‪1433/11/08‬ه ـ الســتالم نســخة‬\n‫مــن احلكــم لتقــدمي مالديهمــا مــن اعتــراض يف مدة أقصاهــا ثالثون يوم ًا‬\n‫وإال ســقط حقهمــا يف االعتــراض واكتســب احلكــم القطعيــة ففهمــا‬\n‫ذلــك وبــاهلل التوفيــق وأقفلــت اجللســة الســاعة الثانيــة ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ؛ ففــي يــوم اإلثنــن املوافــق ‪1434/03/23‬ه ـ‬\n\n\n                                                                                      ‫‪166‬‬\n\f      ‫افتتحــت اجللســة الســاعة العاشــرة وقــد وردتنــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية باخلطــاب رقــم ‪ 34223193‬يف‬\n      ‫‪1434/03/16‬ه ـ واملــزودة بالقــرار مــن الدائــرة األولــى ‪ -‬ق ‪ /‬أ برقــم‬\n      ‫‪ 3459598‬يف ‪1434/03/10‬ه ـ املتضمــن مــا نصــه ‪ ( :‬وبدراســة الصــك‬\n      ‫قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه‬ ‫وصــورة ضبطــه وأوراق املعاملــة ّ‬\n      ‫حـ ّـرر يف ‪ ، 1434/03/10‬واهلل ولــي التوفيــق ‪ .‬قاضــي اســتئناف ختمــه‬\n      ‫وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة) انتهــى‬\n      ‫نصــه وأقفلــت اجللســة الســاعة العاشــرة وخمــس دقائــق ‪ ،‬حـ ّـرر يف‬           ‫ّ‬\n                                                                      ‫‪1434/03/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد‪ :‬ففــي يــوم األحــد املوافــق ‪1434/05/05‬ه ـ‬\n      ‫وردتنــا املعاملــة مــن شــرطة محافظــة القطيــف مبوجــب خطابهــم رقــم‬\n      ‫‪ 4371/8/21‬يف ‪1434/4/27‬هـ يتضمن بعد املقدمة ما نصه‪( :‬وحيث‬\n      ‫انــه مت تطبيــق املــادة (‪ )230‬مــن نظــام املرافعــات الشــرعية بحــق الســجني‬\n      ‫املذكــور لــذا نبعــث لفضيلتكــم املذكــور بأمــل إجــراء اإليجــاب‬\n      ‫الشــرعي ويف حــال ارتأيتــم ســجن املذكــور تزويدنــا بكتــاب مســتقل‬\n      ‫يتضمــن األمــر بســجنه ومــدة الســجن ليتســنى لنــا علــى ضــوء ذلــك بعثــه‬\n      ‫للســجن العــام وإعــادة لنــا كامــل املعاملــة فــور االنتهــاء منهــا) انتهــى‬\n      ‫نــص احلاجــة منــه ‪ ،‬وقــد حضــر لدينــا الطرفــان ‪ ،‬وقــررا اصطالحهمــا‬\n      ‫علــى أن يكــون الدفــع وفــق مــا يلــي‪ )1( :‬أن يتــم دفــع املبلــغ علــى أقســاط‬\n      ‫شــهرية قيمــة كل قســط ثالثــة آالف ريـ(‪ )3000‬ــال ويكــون القســط‬\n      ‫األول بتاريــخ ‪2013/03/20‬م (‪ )2‬بقيــة األقســاط بتاريــخ ‪ 7‬مــن كل‬\n      ‫شــهر ميــادي هكــذا اصطلحــا ‪ ،‬وحيــث األمــر مــا ذكــر فقــد ثبــت‬\n      ‫لــدي اصطــاح الطرفــن علــى مــا ذكــر بعاليــه وألزمتهمــا بــه وأمــرت‬\n\n\n‫‪167‬‬\n\f‫بالتهميــش علــى الصــك مبضمــون ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/05/05‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد و آلــه‬\n‫وصحبــه أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى‬\n‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبحافظة القطيف برقــم ‪331812019‬‬\n‫وتاريــخ ‪1434/1/ 3‬ه ـ واملقيــدة لــدى احملكمــة برقــم ‪34223193‬‬\n‫وتاريــخ ‪1434/1/26‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلة القاضي‬\n‫باحملكمــة الشــيخ‪ ...../‬املسـ ّـجل برقــم‪ .....‬وتاريــخ ‪1433/11/20‬ه ـ‬\n‫اخلــاص بدعــوى‪ ...../‬وزوجتــه ضــد‪ ...../‬يف قضيــة حقوقيــة وقــد تضمــن‬\n‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه‬\n                             ‫حــرر يف ‪1434/3/10‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                          ‫‪168‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":161,"source_page_end":168,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0d7610b3265777968c25461b355d2ca5d376b4ca4599352efb35e74b052a9671","normalized_text_hash":"8881396662e5e3a0d7b9f042f5820fdb4894e804411c9f320d131d2aef395766","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p161-33458770"},{"id":"6142523f-e5f4-5aa9-af94-d5f984f527fa","document_type":"judgment","category":"judicial","subcategory":"general","title":"شركة مضاربة -طلب اعادة رأس املال -سماع الدعوى غيابي ا لتعذر تبليغ املدعى عليه -احلكم بشاهد عدل ومين -طلب مين االستظهار -الشريعة جاءت برفع الضرر -للحاكم والية على مال الغائب -يجوز احلكم على الغائب و املستتر و املمتنع -احلكم بدفع املبلغ املدعى به لقيام البينه -الغائب على حجته متى حضر .1مارواه ابن عباس رضي اهلل عنهما أن رسول اهلل ( قضى بيمن وشاهد ) رواه مسلم.","document_number":"33461365","case_number":"33606126","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة ففي هذا اليوم االثنني1433/11/1ه ويف متام الساعة الثامنة والنصف فتحت","circuit":"الدائرة احلقوقية السابعة مبوجب قرارهم ذي الرقم 33461365يف","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/21","year":"1434","subject":"شركة مضاربة -طلب اعادة رأس املال -سماع الدعوى غيابي ا لتعذر تبليغ املدعى عليه -احلكم بشاهد عدل ومين -طلب مين االستظهار -الشريعة جاءت برفع الضرر -للحاكم والية على مال الغائب -يجوز احلكم على الغائب و املستتر و املمتنع -احلكم بدفع املبلغ املدعى به لقيام البينه -الغائب على حجته متى حضر .1مارواه ابن عباس رضي اهلل عنهما أن رسول اهلل ( قضى بيمن وشاهد ) رواه مسلم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫تاريخه‪1434/11/21 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33461365 :‬‬\n                        ‫َر ْق ُم الدعوى‪33606126 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪33461365 :‬‬\n                        ‫تاريخه‪1434/11/21 :‬هـ‬\n\n\n       ‫شــركة مضاربــة ‪ -‬طلــب اعــادة رأس املــال ‪ -‬ســماع الدعــوى غيابي ـ ًا‬\n       ‫لتعــذر تبليــغ املدعــى عليــه ‪ -‬احلكــم بشــاهد عــدل وميــن ‪ -‬طلــب ميــن‬\n       ‫االســتظهار ‪ -‬الشــريعة جــاءت برفــع الضــرر ‪ -‬للحاكــم واليــة علــى‬\n       ‫مــال الغائــب ‪ -‬يجــوز احلكــم علــى الغائــب و املســتتر و املمتنــع ‪ -‬احلكــم‬\n       ‫بدفــع املبلــغ املدعــى بــه لقيــام البينــه ‪ -‬الغائــب علــى حجتــه متــى حضر‬\n\n\n\n\n       ‫‪ .1‬مــارواه ابــن عبــاس رضــي اهلل عنهمــا أن رســول اهلل ( قضــى بيمــن‬\n                                                              ‫وشــاهد ) رواه مســلم‪.‬‬\n                                                 ‫‪ .2‬حديث (( ال ضرر وال ضرار ))‬\n                                ‫‪ .3‬املادتان ‪ 13‬و ‪ 55‬من نظام املرافعات الشرعية‪.‬‬\n       ‫‪ .4‬للحاكــم واليــة علــى مــال الغائــب ‪ ،‬ويجــوز لــه احلكــم عليــه وعلــى‬\n       ‫املســتتر و املمتنــع ولــو كان يف البلــد ‪ ،‬كمــا صــرح بذلــك أهــل العلــم‬\n                                      ‫منهــم صاحــب املبــدع و الكشــاف وغيرهمــا ‪.‬‬\n\n\n\n\n       ‫دعــوى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم الــذي‬\n       ‫تعــذر تبليغــه باملوعــد وتقــرر ســماع الدعــوى غيابي ـ ًا ومضمــون الدعــوى‬\n       ‫ان املدعــي ســلم املدعــى عليــه مبلغ ـ ًا قــدره خمســون ألــف ريــال حيــث‬\n\n‫‪169‬‬\n\f‫اتفقا على إنشــاء مشــروع تربية دواجن شــراكة وراس املال من املدعي‬\n‫وعلــى املدعــى عليــه العمــل ومتابعــة املشــروع وأن املبلــغ الــذي مت تســليمه‬\n‫دفعــة مقدمــه ولكــن املدعــى عليــه لــم يقــم مبــا مت اإلتفــاق عليــه وانــه‬\n‫حصــل خــاف ومت االتفــاق علــى اعــادة راس املــال علــى دفعتــن االولــى‬\n‫قدرهــا خمســة وثالثــون الــف ريــال تســلم يف ‪1433/6/29‬ه ـ والباقــي‬\n‫يســلم يف ‪1433/7/29‬ه ـ ولكــن املدعــى عليــه لــم يلتــزم بتســليم املبالــغ‬\n‫يف املوعــد احملــدد وطلــب احلكــم بتســليم املبلــغ املدعــى بــه وقــدره‬\n‫خمســون الــف ريــال‪ ،‬احضــر املدعــي شــاهد ًا علــى صحــة دعــواه ومت‬\n‫تعديــل الشــاهد شــرعاً‪ ،‬حلــف املدعــي تكملــه لبينتــه ‪ -‬صــدر احلكــم‬\n‫بالــزام املدعــى عليــه بتســليم املدعــي املبلــغ املدعــى بــه وهــو علــى حجتــه‬\n‫اذا حضــر‪ ،‬مت تزويــد املدعــى عليــه بصــورة مــن الصــك‪ ،‬صــدر قــرار‬\n       ‫محكمــة االســتئناف مبكــة املكرمــة باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا‪ ...‬القاضــي باحملكمــة العامــة باملدينــة املنــورة ففــي هــذا اليــوم‬\n‫االثنني‪1433/11/1‬ه ـ ويف متــام الســاعة الثامنــة والنصــف فتحــت‬\n‫ـاء علــى املعاملــة املقيــدة يف هــذه احملكمــة برقــم‬   ‫اجللســة األولــى بنـ ً‬\n‫‪331822590‬يف ‪1433/10/16‬ه ـ واحملالــة إلينــا مــن قبــل فضيلــة‬\n‫الرئيــس برقــم ‪33606126‬يف ‪1433/10/16‬ه ـ مبوجبــه حضــر املواطن‬\n‫‪ ...‬يحمــل الهويــة الوطنيــة رقــم ‪ ......‬ولــم يحضــر املدعى عليه وال من ينوب‬\n‫عنــه هــذا وقــد وردنــا مــن قســم محضــري اخلصــوم يف هــذه احملكمــة‬\n‫مايفيــد علــى أنــه مت الذهــاب إلــى عنوانــه عــدة مــرات ولــم يجــدوا أحــد ًا‬\n\n                                                                                       ‫‪170‬‬\n\f      ‫وأنــه قــد مت تســليم التبليــغ إلــى عمــدة احلــي ولــم يــرد مايفيــد تبلغــه‬\n      ‫وعليــه فقــد أمــرت برفــع اجللســة إلــى يــوم األربعــاء ‪1433/11/17‬ه ـ‬\n      ‫الســاعة الثامنــة صباح ـ ًا هــذا ويف يــوم األربعــاء ‪1433/11/17‬ه ـ ويف‬\n      ‫متــام الســاعة الثامنــة والنصــف فتحــت اجللســة الثانيــة وفيهــا حضــر‬\n      ‫املدعــي ولــم يحضــر املدعــى عليــه وقــد جــرى محاولــة تبليغــه عــن طريــق‬\n      ‫عمــدة احلــي (حــي ‪ )........‬وقــد وردنــا إفــادة عمــدة احلــي شــرح ًا علــى‬\n      ‫ورقــة التبليــغ املؤرخــة يف ‪1433/11/1‬ه ـ واملتضمنــه انــه مت الذهــاب‬\n      ‫الــى منــزل املذكــور عــدة مــرات ولــم يجــده أحــد ًا يف املنــزل ولــم يتــم‬\n      ‫فتــح البــاب نهائي ـ ًا وعليــه قــررت ســماع الدعــوى عليــه غيابي ـ ًا وادعــى‬\n      ‫ا انــه بتاريــخ‬\n                     ‫املدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم قائـ ً‬\n      ‫‪1433/5/15‬ه ـ اتفقــت اتفاق ـ ًا مبدئي ـ ًا مــع املدعــى عليــه الغائــب عــن‬\n      ‫مجلــس احلكــم علــى أن نقــوم بإنشــاء مشــروع تربيــة دواجــن شــراكة‬\n      ‫بيننــا منــي رأس املــال ومنــه العمــل ومتابعــة املشــروع وســلمته مبلــغ وقــدره‬\n      ‫خمســون ألــف ريــال دفعــة مقدمــة علــى أن يقــوم املدعــى عليــه بعــد يومــن‬\n      ‫بكتابــة صيغــة عقــد الشــراكة الــذي بيننــا ويبــن فيــه نســبة األربــاح‬\n      ‫التــي بيننــا إال أن املدعــى عليــه لــم يأتنــي بعقــد وال بغيــره حتــى أول شــهر‬\n      ‫جمــاد اآلخــرة فذهبــت إليــه وقلــت لــه ملــا لــم تأتينــي بالعقــد حتــى نقيــم‬\n      ‫الشــراكة بيننــا فحصــل خــاف بيننــا علــى إثــره قــال لــي املدعــى عليــه‬\n      ‫أنــا أحتمــل املشــروع لوحــدي وأنــت مالــك إال رأس مالــك وســوف أعيــده‬\n      ‫لــك واتفقــت أنــا وإيــاه علــى إعــادة رأس مالــي املبلــغ املدعــى بــه وقــدره‬\n      ‫خمســون ألــف ريــال علــى دفعتــن الدفعــة األولــى قدرهــا خمســة وثالثــون‬\n      ‫ألــف ريــال يف ‪1433/6/29‬ه ـ والدفعــة الثانيــة قدرها خمســة عشــر ألف‬\n      ‫ريــال يف ‪1433/7/29‬ه ـ ولــم يلتــزم املدعــى عليــه بدفــع املبلــغ لــي بهــذه‬\n\n\n‫‪171‬‬\n\f‫التواريــخ ولــم يدفــع لــي حتــى تاريــخ هــذا اليــوم ريــا ًال واحــد ًا واملدعــى‬\n‫عليــه الغائــب قــد ماطلنــي كثيــر ًا يف دفــع هــذا املبلــغ وقــد تضــررت‬\n‫مــن مماطلتــه وتهربــه عــن دفــع هــذا املبلــغ لــي أطلــب إثبــات ذلــك وإلــزام‬\n‫املدعــى عليــه الغائــب عــن مجلــس احلكــم بدفــع املبلــغ املدعــى بــه وقــدره‬\n‫خمســون ألــف ريــال حــا ًال هــذه دعــواي ثــم جــرى منــا ســؤال املدعــي هــل‬\n‫ا نعــم لــدي بينــة علــى هــذه الدعــوى‬     ‫لديــه بينــة علــى دعــواه فأجــاب قائـ ً‬\n‫هــذا وقــد أحضــر معــه املواطــن يحمــل الهويــة الوطنيــة رقــم وطلــب ســماع‬\n‫ا أشــهد هلل تعالــى بأنــه قبــل‬    ‫مــا لديــه وبســؤاله عمــا لديــه شــهد قائ ـ ً‬\n‫حوالــي أربعــة أشــهر ونصــف يف شــهر جمــادى اآلخــرة طلــب منــي املدعــى‬\n‫عليــه أن آتــي إليــه يف منــزل املدعــي ‪........‬هــذا احلاضــر الكائــن يف حــي‬\n‫‪........‬فذهبــت إلــى منــزل املدعــي ووجــدت املدعــى عليــه عنــده وقــال لــي‬\n‫املدعــى عليــه باحلــرف الواحــد يــا ‪ ........‬اشــهد بــأن يف ذمتــي مبلــغ وقــدره‬\n‫خمســون ألــف ريــال لـ‪........‬أســدده لــه خــال شــهر نصف املبلــغ أو أكثره‬\n‫والباقــي خــال شــهرين مــن تاريــخ هــذا اليــوم ولكنــه لــم يــوف ثــم جــاء‬\n                                                      ‫إلــي املدعــى عليــه مــرة أخــرى‪.‬‬\n‫وطلــب منــي أن أشــفع لــه عنــد املدعــي لكــي يعطيــه مهلــة أخــرى‬\n‫لتســديد هــذا املبلــغ املدعــى بــه وقــدره خمســون ألــف ريــال فذهبــت إلــى‬\n‫املدعــي وطلبــت منــه أن يعطيــه مهلــة أخيــرة يف ‪1433/10/15‬ه ـ ولكــن‬\n‫لــم يســدده حتــى تاريــخ هــذا اليــوم ريــا ًال واحــد ًا هــذا مــا لــدي وبــه أشــهد‬\n‫هكــذا شــهد ثــم جــرى منــا ســؤال املدعــي عــن معدلــن لهــذا الشــاهد‬\n‫ا ســوف أحضــر املزكيــن يف اجللســة القادمــة هكــذا‬                    ‫فأجــاب قائ ـ ً‬\n‫ا‬\n‫أجــاب ثــم جــرى منــا ســؤال املدعــي هــل لديــه زيــادة بينــة فأجــاب قائـ ً‬\n‫نعــم ولكــن أطلــب إعطائــي مهلــة هكــذا أجــاب وعليــه فقــد أمــرت‬\n\n\n                                                                                             ‫‪172‬‬\n\f      ‫برفــع اجللســة إلــى يــوم األحــد ‪1433/11/21‬ه ـ الســاعة الثامنــة صباحـ ًا‬\n      ‫هــذا ويف يــوم األحــد ‪1433/11/21‬ه ـ ويف متــام الســاعة الثامنــة صباحـ ًا‬\n      ‫فتحــت اجللســة الثالثــة وفيهــا حضــر املدعــي ويرافقــه الشــاهد املدونــه‬\n      ‫هويتــه بعاليــه ســابق ًا ثــم جــرى منــا ســؤال املدعــي عــن املعدلــن لبينتــه‬\n      ‫ا نعــم لقــد أحضرتهــم هــذا وقــد احضــر معه‬       ‫املدونــه بعاليــه فأجــاب قائـ ً‬\n      ‫ال من املواطن ‪ .....‬يحمل الهوية الوطنية رقم ‪ .....‬واملواطن ‪ .....‬يحمل‬            ‫ك ً‬\n      ‫الهويــة الوطنيــة رقــم ‪ .....‬وبســؤالهما عمــا لديهما شــهدا قائلني نشــهد هلل‬\n      ‫تعالــى بــأن هــذا الشــاهد عــدل ثقــة مرضــي الشــهادة لنــا وعلينــا هكــذا‬\n      ‫ا‬ ‫شــهدا ثــم جــرى منــا ســؤال املدعــي هــل لديــه زيــادة بينــة فأجــاب قائـ ً‬\n      ‫ليــس لــدي زيــادة بينــة علــى هــذه الدعــوى هكــذا أجــاب ثــم جــرى منــا‬\n      ‫عــرض ميــن االســتظهار علــى املدعــي يف إثبــات دعــواه فاســتعد بآدائهــا‬\n      ‫وقــد جــرى منــا تخويفــه بــاهلل ســبحانه وتعالــى مــن اليمــن الغمــوس‬\n      ‫ا واهلل العظيــم‬   ‫فاســتعد بآدائهــا ثــم أذنــت لــه بــآداء اليمــن فحلــف قائ ـ ً‬\n      ‫الــذي ال الــه اال هــو احلــي القيــوم عالــم الغيــب والشــهادة فاطــر الســموات‬\n      ‫واالرض بــأن لــي يف ذمــة املدعــى عليــه الغائــب عــن مجلــس احلكــم ‪.....‬‬\n      ‫يحمــل الســجل املدنــي رقــم ‪ .....‬مبلغ ـ ًا وقــدره خمســون ألــف ريــال لــم‬\n      ‫يســلمني منهــا ريــا ًال واحــد ًا وأننــي أعطيتــه مهلــة أخيــرة يف تســديد هــذا‬\n      ‫املبلــغ بتاريــخ ‪1433/10/15‬ه ـ ولــم يســددني شــيئ ًا مــن هــذا املبلــغ واهلل‬\n      ‫ـاء علــى ماتقــدم مــن الدعــوى‬    ‫علــى مــا أقــول شــهيد هكــذا حلــف فبنـ ً‬\n      ‫واالطــاع علــى اوراق املعاملــة ونظــر ًا ملــا جــاء يف شــهادة الشــاهد املعدلــة‬\n      ‫شــرع ًا املتضمنــة ان املدعــى عليــه أقــر وأســتعد بدفــع املبلــغ املدعــى بــه‬\n      ‫وقــدره خمســون ألــف ريــال يف مهلــة أقصاهــا ‪1433/10/15‬ه ـ ولــم‬\n      ‫يســدد املدعــي شــيئا مــن هــذا املبلــغ حتــى تاريــخ هــذا اليــوم ومبــا أن‬\n\n\n‫‪173‬‬\n\f‫املدعــي قــد أدى ميــن االســتظهار املقويــة لبينتــه املدونــة بعاليــه وملــا روي‬\n‫عــن ابــن عبــاس رضــي اهلل عنــه ( ان رســول اهلل صلــى اهلل عليــه وســلم‬\n                                             ‫قضــى بيمــن وشــاهد ) رواه مســلم‬\n‫ومبــا أن املدعــى عليــه قــد تعــذر تبليغــه عــن طريــق محضــر اخلصــوم يف‬\n‫هــذه احملكمــة وعــن طريــق عمــدة احلــي ومبــا أن الشــريعة جــاءت برفــع‬\n‫الضــرر حلديــث ال ضــرر وال ضــرار ومبــا أن للحاكــم واليــة علــى مــال‬\n‫الغائــب ويجــوز لــه احلكــم عليــه وعلــى املســتتر واملمتنــع ولــو كان يف‬\n‫البلــد كمــا صــرح بذلــك أهــل العلــم ومنهــم صاحــب املبــدع والكشــاف‬\n‫وغيرهــم ونظــر ًا ملــا نصــت عليــه املادتــن (‪18‬و‪ )55‬مــن نظــام املرافعــات‬\n‫الشــرعية جلميــع مــا ذكــر فقــد ألزمــت املدعــى عليــه بدفــع مبلغـ ًا وقــدره‬\n‫خمســون ألــف ريــال حــا ًال للمدعــي هــذا مــا ظهــر لــي وبــه حكمــت هــذا‬\n‫وقــررت ببعــث نســخة مــن صــك احلكــم بعــد تســجيله للمدعــى عليــه‬\n‫لتبليغــه باحلكــم وأفهامــه بأنــه لــه مهلــة ثالثــن يوم ـ ًا مــن تاريــخ تبليغــه‬\n‫لتقــدمي الئحتــه االعتراضيــه فــإذا لــم يتقــدم بالئحتــه االعتراضيــة خــال‬\n‫هــذه املــدة فــإن حقــه يســقط يف تقــدمي االعتــراض ويكتســب احلكــم‬\n‫القطعيــة وهــذا احلكــم يعــد يف حــق املدعــى عليــه غيابيــا وهــو علــى‬\n‫حجتــه متــى ماحضــر وبــه اختتمــت اجللســة يف متــام الســاعة التاســعة‬\n‫إالربــع وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/11/21‬ه ـ‬\n\n\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي هــذا‬\n‫اليــوم الثالثــاء ‪1434/3/3‬ه ـ عــادت لنــا املعاملــة مــن محكمــة‬\n‫اإلســتئناف مبكــة املكرمــة مبوجــب خطابهــم ذي الرقــم ‪331822590‬‬\n‫يف ‪1434/1/25‬ه ـ وقــد جــرى تدقيــق احلكــم واملصادقــة عليــه مــن قبــل‬\n\n\n                                                                                         ‫‪174‬‬\n\f      ‫الدائــرة احلقوقيــة الســابعة مبوجــب قرارهــم ذي الرقــم ‪ 33461365‬يف‬\n      ‫‪1434/11/21‬ه ـ قاضــي اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫ختمــه وتوقيعــه ورئيــس الدائــرة ختمــه وتوقيعه وللمعلوميــة جرى حتريره‬\n      ‫حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر‬\n                                                                    ‫يف ‪1434/3/3‬هــ‪.‬‬\n      ‫احلمد هلل وحده‪ ،‬والصالة والسالم على من ال نبي بعده ‪ ،‬وبعد ‪ :‬ـ فقد‬\n      ‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــا ُع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 331822590‬وتاريــخ ‪25‬‬\n      ‫‪ 1434/1/‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ /‬القاضــي‬\n      ‫باحملكمــة العامــة باملدينــة املنــورة املســجل برقــم ‪ 33461365‬وتاريــخ‬\n      ‫‪1433/11/21‬ه ـ املتضمــن دعــوى‪ /‬ضــد‪ /‬وبدراســة الصــك وص ــورة‬\n      ‫ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم‪ .‬واهلل املوفــق وصل ــى اهلل عل ــى‬\n                                           ‫نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪175‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":169,"source_page_end":175,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"797e365d318e109c67aae44f102b0eecc3a7ca14514c26ad16ba7251ac9b9854","normalized_text_hash":"754da0e8b03d60ea46f6c2a0f4fa2ab987361916cdbd975b1d3f6318618ede07","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p169-33461365"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
